import { useEffect, useState } from 'react';
import api from '../api';
import {
  Activity, Heart, Droplets, ThermometerSun, Wind,
  Weight, HeartPulse, AlertTriangle, Loader2, RefreshCw, Pill,
} from 'lucide-react';
import { useT, type Lang } from '../i18n/LanguageContext';

const LOCALES: Record<Lang, string> = { pt: 'pt-PT', en: 'en-GB', fr: 'fr-FR', es: 'es-ES', zh: 'zh-CN' };
type TFn = (k: string) => string;

// ── Types ─────────────────────────────────────────────────────────────────────

type ReadingType =
  | 'blood_pressure' | 'glucose' | 'temperature'
  | 'oxygen_saturation' | 'weight' | 'heart_rate';

interface DeviceReading {
  id: string;
  reading_type: ReadingType;
  value: number | null;
  unit: string | null;
  systolic: number | null;
  diastolic: number | null;
  pulse: number | null;
  measured_at: string;
  source: string | null;
  device_brand: string | null;
  device_model: string | null;
  notes: string | null;
}

interface ReadingListOut {
  total: number;
  readings: DeviceReading[];
}

interface PatientMedication {
  id: string;
  medication_name: string;
  dosage: string | null;
  frequency: string | null;
  is_current: boolean;
  reason: string | null;
  prescribed_by: string | null;
}

// ── Range flags (visual only — NOT diagnosis) ─────────────────────────────────

interface RangeRule {
  key: string;
  check: (r: DeviceReading) => boolean;
}

const RANGE_RULES: Record<ReadingType, RangeRule[]> = {
  blood_pressure: [
    { key: 'prp.flag_systolic', check: r => r.systolic != null && (r.systolic < 90 || r.systolic > 140) },
    { key: 'prp.flag_diastolic', check: r => r.diastolic != null && (r.diastolic < 60 || r.diastolic > 90) },
  ],
  glucose: [
    { key: 'prp.flag_glucose', check: r => r.value != null && (r.value < 70 || r.value > 125) },
  ],
  temperature: [
    { key: 'prp.flag_temp', check: r => r.value != null && (r.value < 36.0 || r.value > 37.5) },
  ],
  oxygen_saturation: [
    { key: 'prp.flag_o2', check: r => r.value != null && r.value < 95 },
  ],
  weight: [],
  heart_rate: [
    { key: 'prp.flag_hr', check: r => r.value != null && (r.value < 50 || r.value > 100) },
  ],
};

/** Returns matching range-rule translation keys for a reading. */
function getFlagKeys(r: DeviceReading): string[] {
  return (RANGE_RULES[r.reading_type] ?? [])
    .filter(rule => rule.check(r))
    .map(rule => rule.key);
}

// ── Metadata ──────────────────────────────────────────────────────────────────

const TYPE_META: Record<ReadingType, { labelKey: string; icon: React.ElementType; color: string; bg: string }> = {
  blood_pressure:    { labelKey: 'prp.type_bp',      icon: Heart,          color: '#ef4444', bg: 'rgba(239,68,68,0.1)'   },
  glucose:           { labelKey: 'prp.type_glucose', icon: Droplets,       color: '#f59e0b', bg: 'rgba(245,158,11,0.1)'  },
  temperature:       { labelKey: 'prp.type_temp',    icon: ThermometerSun, color: '#f97316', bg: 'rgba(249,115,22,0.1)'  },
  oxygen_saturation: { labelKey: 'prp.type_o2',      icon: Wind,           color: '#3b82f6', bg: 'rgba(59,130,246,0.1)'  },
  weight:            { labelKey: 'prp.type_weight',  icon: Weight,         color: '#6366f1', bg: 'rgba(99,102,241,0.1)'  },
  heart_rate:        { labelKey: 'prp.type_hr',      icon: HeartPulse,     color: '#ec4899', bg: 'rgba(236,72,153,0.1)'  },
};

// ── Formatters ────────────────────────────────────────────────────────────────

function fmtValue(r: DeviceReading): string {
  if (r.reading_type === 'blood_pressure') {
    if (r.systolic != null && r.diastolic != null) {
      return `${r.systolic}/${r.diastolic} mmHg${r.pulse ? ` · ${r.pulse} bpm` : ''}`;
    }
    return '—';
  }
  return r.value != null ? `${r.value} ${r.unit ?? ''}`.trim() : '—';
}

function fmtDate(iso: string, locale: string) {
  return new Date(iso).toLocaleString(locale, {
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

// ── Summary Card ──────────────────────────────────────────────────────────────

function SummaryCard({ type, reading, t, locale }: { type: ReadingType; reading: DeviceReading | undefined; t: TFn; locale: string }) {
  const meta = TYPE_META[type];
  const Icon = meta.icon;
  const flags = reading ? getFlagKeys(reading).map(t) : [];
  const hasFlag = flags.length > 0;

  return (
    <div style={{
      background: 'var(--surface, #fff)', border: `1px solid ${hasFlag ? '#fca5a5' : 'var(--border)'}`,
      borderRadius: '12px', padding: '0.85rem 1rem', display: 'flex', flexDirection: 'column', gap: '0.35rem',
      boxShadow: hasFlag ? '0 0 0 2px rgba(239,68,68,0.12)' : undefined,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', marginBottom: '0.1rem' }}>
        <span style={{ width: 28, height: 28, borderRadius: '8px', background: meta.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
          <Icon size={14} style={{ color: meta.color }} />
        </span>
        <span style={{ fontSize: '0.72rem', fontWeight: 600, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.04em' }}>{t(meta.labelKey)}</span>
        {hasFlag && <span title={flags[0]} style={{ marginLeft: 'auto', lineHeight: 0 }}><AlertTriangle size={13} style={{ color: '#f97316' }} /></span>}
      </div>
      <div style={{ fontSize: '1.1rem', fontWeight: 800, color: hasFlag ? '#dc2626' : 'var(--text-primary)', lineHeight: 1 }}>
        {reading ? fmtValue(reading) : <span style={{ fontSize: '0.85rem', fontWeight: 400, color: 'var(--text-muted)' }}>{t('prp.no_data')}</span>}
      </div>
      {reading && (
        <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)' }}>{fmtDate(reading.measured_at, locale)}</div>
      )}
      {hasFlag && (
        <div style={{ fontSize: '0.68rem', color: '#d97706', background: 'rgba(251,191,36,0.08)', border: '1px solid rgba(251,191,36,0.25)', borderRadius: 6, padding: '0.2rem 0.4rem', marginTop: '0.1rem', lineHeight: 1.4 }}>
          ⚠ {flags[0]}
        </div>
      )}
    </div>
  );
}

// ── Main Component ─────────────────────────────────────────────────────────────

interface Props {
  patientId: string;
  /** Optional patient name for the panel heading */
  patientName?: string;
}

const ALL_TYPES: ReadingType[] = [
  'blood_pressure', 'glucose', 'temperature', 'oxygen_saturation', 'weight', 'heart_rate',
];

export default function PatientReadingsPanel({ patientId, patientName }: Props) {
  const { t, lang } = useT();
  const locale = LOCALES[lang] || 'pt-PT';
  const [readings, setReadings] = useState<DeviceReading[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [medications, setMedications] = useState<PatientMedication[]>([]);
  const [medsLoading, setMedsLoading] = useState(true);

  const load = () => {
    setLoading(true);
    setError('');
    api.get<ReadingListOut>(`/api/v1/readings/patient/${patientId}?limit=50`)
      .then(r => { setReadings(r.data.readings); setTotal(r.data.total); })
      .catch(() => setError(t('prp.readings_error')))
      .finally(() => setLoading(false));

    setMedsLoading(true);
    api.get<PatientMedication[]>(`/api/v1/medications/patient/${patientId}`)
      .then(r => setMedications(r.data))
      .catch(() => {})
      .finally(() => setMedsLoading(false));
  };

  useEffect(() => { if (patientId) load(); }, [patientId]);

  // Latest reading per type
  const latest = Object.fromEntries(
    ALL_TYPES.map(rt => [rt, readings.find(r => r.reading_type === rt)])
  ) as Record<ReadingType, DeviceReading | undefined>;

  const allFlags = readings.flatMap(r => getFlagKeys(r).map(fk => ({ type: r.reading_type, flag: t(fk), date: r.measured_at })));

  return (
    <div>
      {/* Panel header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          <Activity size={16} style={{ color: 'var(--brand-primary)' }} />
          <span style={{ fontWeight: 700, fontSize: '0.9rem' }}>
            {t('prp.heading')}{patientName ? ` — ${patientName}` : ''}
          </span>
          {total > 0 && (
            <span style={{ fontSize: '0.72rem', padding: '0.15rem 0.5rem', borderRadius: 999, background: 'var(--brand-light)', color: 'var(--brand-primary)', fontWeight: 700 }}>
              {total} {t('prp.total')}
            </span>
          )}
        </div>
        <button onClick={load} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '0.25rem', fontSize: '0.75rem', padding: '0.25rem' }}>
          <RefreshCw size={12} /> {t('common.refresh')}
        </button>
      </div>

      {loading ? (
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--text-muted)', fontSize: '0.85rem', padding: '1rem 0' }}>
          <Loader2 size={16} className="spin" /> {t('prp.loading_readings')}
        </div>
      ) : error ? (
        <div style={{ color: '#dc2626', fontSize: '0.85rem', padding: '0.75rem', background: 'rgba(239,68,68,0.06)', borderRadius: 8 }}>
          {error}
        </div>
      ) : readings.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '1.5rem', color: 'var(--text-muted)', fontSize: '0.85rem' }}>
          <Activity size={24} style={{ color: 'var(--border)', marginBottom: '0.5rem', display: 'block', margin: '0 auto 0.5rem' }} />
          {t('prp.no_readings')}
        </div>
      ) : (
        <>
          {/* Range flags summary */}
          {allFlags.length > 0 && (
            <div style={{ background: 'rgba(251,191,36,0.08)', border: '1px solid rgba(251,191,36,0.3)', borderRadius: 10, padding: '0.75rem 1rem', marginBottom: '1rem' }}>
              <div style={{ fontWeight: 700, fontSize: '0.78rem', color: '#d97706', marginBottom: '0.35rem', display: 'flex', alignItems: 'center', gap: '0.3rem' }}>
                <AlertTriangle size={13} /> {allFlags.length} {allFlags.length > 1 ? t('prp.flags_many') : t('prp.flags_one')}
              </div>
              <ul style={{ margin: 0, padding: '0 0 0 1rem', fontSize: '0.73rem', color: 'var(--text-secondary)' }}>
                {allFlags.slice(0, 5).map((f, i) => (
                  <li key={i}>{t(TYPE_META[f.type].labelKey)}: {f.flag}</li>
                ))}
              </ul>
            </div>
          )}

          {/* 6 latest summary cards */}
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(160px, 1fr))', gap: '0.6rem', marginBottom: '1.25rem' }}>
            {ALL_TYPES.map(rt => <SummaryCard key={rt} type={rt} reading={latest[rt]} t={t} locale={locale} />)}
          </div>

          {/* History table */}
          <div style={{ borderRadius: '10px', border: '1px solid var(--border)', overflow: 'hidden' }}>
            <div style={{ padding: '0.65rem 1rem', background: 'var(--surface-2, #f9fafb)', borderBottom: '1px solid var(--border)', fontSize: '0.75rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              {t('prp.history')} ({readings.length})
            </div>
            <div style={{ overflowX: 'auto' }}>
              <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.8rem' }}>
                <thead>
                  <tr style={{ background: 'var(--surface-2, #f9fafb)' }}>
                    {[['type', t('prp.col_type')], ['value', t('prp.col_value')], ['date', t('prp.col_date')], ['device', t('prp.col_device')], ['notes', t('prp.col_notes')], ['sp', '']].map(([k, h]) => (
                      <th key={k} style={{ padding: '0.5rem 0.75rem', textAlign: 'left', fontWeight: 600, color: 'var(--text-muted)', fontSize: '0.72rem', whiteSpace: 'nowrap' }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {readings.map((r, i) => {
                    const meta = TYPE_META[r.reading_type];
                    const flags = getFlagKeys(r).map(t);
                    return (
                      <tr key={r.id} style={{ borderTop: i > 0 ? '1px solid var(--border)' : 'none', background: flags.length > 0 ? 'rgba(251,191,36,0.04)' : undefined }}>
                        <td style={{ padding: '0.6rem 0.75rem', whiteSpace: 'nowrap' }}>
                          <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.35rem', fontWeight: 600 }}>
                            <meta.icon size={12} style={{ color: meta.color }} />
                            {t(meta.labelKey)}
                          </span>
                        </td>
                        <td style={{ padding: '0.6rem 0.75rem', fontWeight: 700, whiteSpace: 'nowrap', color: flags.length > 0 ? '#dc2626' : 'var(--text-primary)' }}>
                          {fmtValue(r)}
                          {flags.length > 0 && <span title={flags[0]} style={{ lineHeight: 0 }}><AlertTriangle size={11} style={{ color: '#f97316', marginLeft: 4, verticalAlign: 'middle' }} /></span>}
                        </td>
                        <td style={{ padding: '0.6rem 0.75rem', color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>{fmtDate(r.measured_at, locale)}</td>
                        <td style={{ padding: '0.6rem 0.75rem', color: 'var(--text-muted)' }}>
                          {[r.device_brand, r.device_model].filter(Boolean).join(' ') || r.source || '—'}
                        </td>
                        <td style={{ padding: '0.6rem 0.75rem', color: 'var(--text-muted)', maxWidth: 180 }}>
                          <span title={r.notes ?? ''} style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', display: 'block' }}>
                            {r.notes || '—'}
                          </span>
                        </td>
                        <td style={{ padding: '0.6rem 0.75rem' }} />
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}

      {/* ── Medications section ── */}
      <div style={{ marginTop: '1.5rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.75rem' }}>
          <Pill size={15} style={{ color: '#ef4444' }} />
          <span style={{ fontWeight: 700, fontSize: '0.88rem' }}>{t('prp.meds_current')}</span>
          {medications.length > 0 && (
            <span style={{ fontSize: '0.7rem', padding: '0.1rem 0.45rem', borderRadius: 999, background: 'rgba(239,68,68,0.1)', color: '#ef4444', fontWeight: 700 }}>
              {medications.filter(m => m.is_current).length} {t('prp.meds_badge')}
            </span>
          )}
        </div>
        {medsLoading ? (
          <div style={{ color: 'var(--text-muted)', fontSize: '0.8rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
            <Loader2 size={13} className="spin" /> {t('prp.loading_meds')}
          </div>
        ) : medications.length === 0 ? (
          <div style={{ color: 'var(--text-muted)', fontSize: '0.8rem' }}>{t('prp.no_meds')}</div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
            {medications.map(med => (
              <div key={med.id} style={{
                display: 'flex', alignItems: 'flex-start', gap: '0.6rem',
                background: 'var(--surface, #fff)', border: '1px solid var(--border)',
                borderRadius: 10, padding: '0.6rem 0.85rem',
                opacity: med.is_current ? 1 : 0.55,
              }}>
                <Pill size={13} style={{ color: '#ef4444', marginTop: 2, flexShrink: 0 }} />
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 700, fontSize: '0.85rem', color: 'var(--text-primary)' }}>
                    {med.medication_name}
                    {!med.is_current && <span style={{ marginLeft: '0.5rem', fontSize: '0.7rem', color: 'var(--text-muted)', fontWeight: 400 }}>({t('prp.historic')})</span>}
                  </div>
                  <div style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginTop: '0.15rem' }}>
                    {med.dosage && <span style={{ marginRight: '0.65rem' }}>💊 {med.dosage}</span>}
                    {med.frequency && <span style={{ marginRight: '0.65rem' }}>🔁 {med.frequency}</span>}
                    {med.reason && <span style={{ marginRight: '0.65rem' }}>📋 {med.reason}</span>}
                    {med.prescribed_by && <span>👤 {med.prescribed_by}</span>}
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import { X, CheckCircle2, Copy, Loader2, Smartphone, CreditCard, Landmark, ChevronRight } from 'lucide-react';

interface CheckoutResponse {
  payment_id: string;
  status: string;
  amount: number;              // in centavos
  currency: string;
  provider?: string;
  provider_reference?: string;
  qr_code?: string;
  redirect_url?: string;
  client_secret?: string;
  transfer_details?: Record<string, string | number>;
  instructions?: string;
}

interface PaymentMethod { id: string; label: string; description: string; enabled: boolean; }

interface Props {
  open: boolean;
  consultationId: string;
  onClose: () => void;
  onPaid: () => void;
}

function formatAoa(centavos: number): string {
  const value = centavos / 100;
  return `${value.toLocaleString('pt-AO', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} Kz`;
}

const spinStyle: React.CSSProperties = { animation: 'spin 1s linear infinite' };

const METHOD_ICON: Record<string, React.ReactNode> = {
  multicaixa_express: <Smartphone size={18} />,
  visa_mastercard: <CreditCard size={18} />,
  iban_transfer: <Landmark size={18} />,
};

export default function PaymentModal({ open, consultationId, onClose, onPaid }: Props) {
  const { t } = useT();
  const [methods, setMethods] = useState<PaymentMethod[]>([]);
  const [chosen, setChosen] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [checkout, setCheckout] = useState<CheckoutResponse | null>(null);
  const [status, setStatus] = useState<string>('methods'); // methods, pending, paid, failed
  const [error, setError] = useState('');
  const [copied, setCopied] = useState<string | null>(null);
  const pollRef = useRef<number | null>(null);

  // Load available methods when opened.
  useEffect(() => {
    if (!open) return;
    setStatus('methods'); setChosen(null); setCheckout(null); setError('');
    api.get('/api/v1/billing/payment-methods')
      .then(r => setMethods((r.data.methods || []).filter((m: PaymentMethod) => m.enabled)))
      .catch(() => setMethods([
        { id: 'multicaixa_express', label: 'Multicaixa Express', description: '', enabled: true },
      ]));
  }, [open]);

  // Start checkout once a method is chosen.
  const selectMethod = (methodId: string) => {
    setChosen(methodId);
    setLoading(true);
    setError('');
    api.post('/api/v1/billing/consultation/checkout', {
      consultation_id: consultationId,
      payment_method: methodId,
    })
      .then((res) => {
        const data: CheckoutResponse = res.data;
        setCheckout(data);
        setStatus(data.status === 'paid' ? 'paid' : 'pending');
        if (data.status === 'paid') onPaid();
      })
      .catch((err) => {
        setError(err.response?.data?.detail || t('pay.error_start'));
        setStatus('failed');
      })
      .finally(() => setLoading(false));
  };

  // Poll status while pending — for auto-confirmable methods only.
  // Bank transfer (iban_transfer) confirms manually, so we don't poll it.
  useEffect(() => {
    if (status !== 'pending' || !checkout) return;
    if (checkout.provider === 'iban_transfer') return;
    const tick = async () => {
      try {
        const res = await api.get(`/api/v1/billing/consultation/${consultationId}/payment-status`);
        if (res.data.consultation_paid || res.data.status === 'paid') {
          setStatus('paid'); onPaid();
        } else if (res.data.status === 'failed') {
          setStatus('failed'); setError(t('pay.error_failed'));
        }
      } catch { /* transient — keep polling */ }
    };
    pollRef.current = window.setInterval(tick, 4000);
    return () => { if (pollRef.current) window.clearInterval(pollRef.current); };
  }, [status, checkout, consultationId]);

  if (!open) return null;

  const copy = (key: string, value?: string) => {
    if (!value) return;
    navigator.clipboard?.writeText(value);
    setCopied(key);
    setTimeout(() => setCopied(null), 1500);
  };

  const backdrop = (e: React.MouseEvent) => { if (e.target === e.currentTarget) onClose(); };
  const provider = checkout?.provider;

  return (
    <div onClick={backdrop} style={{
      position: 'fixed', inset: 0, zIndex: 9999, background: 'rgba(0,0,0,0.5)',
      backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '1rem',
    }}>
      <div style={{
        background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: '16px',
        width: '100%', maxWidth: '440px', boxShadow: '0 20px 60px rgba(0,0,0,0.3)', animation: 'fadeIn 0.2s ease',
      }}>
        {/* Header */}
        <div style={{
          display: 'flex', justifyContent: 'space-between', alignItems: 'center',
          padding: '1.25rem 1.5rem', borderBottom: '1px solid var(--border)',
        }}>
          <h3 style={{ margin: 0, fontSize: '1rem', fontWeight: 700, color: 'var(--text-primary)' }}>
            {t('pay.title')}
          </h3>
          <button onClick={onClose} aria-label={t('common.close')} style={{
            background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', padding: '0.25rem',
          }}>
            <X size={18} />
          </button>
        </div>

        {/* Body */}
        <div style={{ padding: '1.5rem' }}>
          {/* Method selection */}
          {status === 'methods' && (
            <>
              <p style={{ color: 'var(--text-secondary)', marginTop: 0, marginBottom: '1rem', fontSize: '0.9rem' }}>
                {t('pay.choose_method')}
              </p>
              {loading && <p style={{ textAlign: 'center', color: 'var(--text-secondary)' }}>
                <Loader2 size={18} style={spinStyle} /></p>}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                {methods.map(m => (
                  <button key={m.id} onClick={() => selectMethod(m.id)} disabled={loading}
                    style={{
                      display: 'flex', alignItems: 'center', gap: '0.75rem', textAlign: 'left',
                      padding: '0.85rem 1rem', borderRadius: 12, border: '1px solid var(--border)',
                      background: chosen === m.id ? 'rgba(20,184,166,0.08)' : 'var(--bg-card)', cursor: 'pointer',
                    }}>
                    <span style={{ color: 'var(--accent-teal)' }}>{METHOD_ICON[m.id] ?? <CreditCard size={18} />}</span>
                    <span style={{ flex: 1 }}>
                      <span style={{ display: 'block', fontWeight: 600, color: 'var(--text-primary)', fontSize: '0.92rem' }}>{m.label}</span>
                      {m.description && <span style={{ display: 'block', color: 'var(--text-secondary)', fontSize: '0.8rem' }}>{m.description}</span>}
                    </span>
                    <ChevronRight size={16} style={{ color: 'var(--text-muted)' }} />
                  </button>
                ))}
              </div>
            </>
          )}

          {status === 'paid' && (
            <div style={{ padding: '0.5rem 0', textAlign: 'center' }}>
              <CheckCircle2 size={48} style={{ color: '#22c55e' }} />
              <h4 style={{ margin: '0.75rem 0 0.25rem', color: 'var(--text-primary)' }}>{t('pay.paid_title')}</h4>
              <p style={{ color: 'var(--text-secondary)' }}>{t('pay.paid_desc')}</p>
              <button className="btn btn-primary" style={{ marginTop: '1rem' }} onClick={onClose}>{t('common.close')}</button>
            </div>
          )}

          {status === 'failed' && (
            <div style={{ padding: '0.5rem 0', textAlign: 'center' }}>
              <p style={{ color: '#ef4444' }}>{error || t('pay.error_start')}</p>
              <button className="btn btn-secondary" style={{ marginTop: '0.5rem' }} onClick={() => setStatus('methods')}>
                {t('pay.try_other')}
              </button>
            </div>
          )}

          {status === 'pending' && checkout && (
            <div style={{ textAlign: 'center' }}>
              <p style={{ color: 'var(--text-secondary)', marginBottom: '0.25rem' }}>{t('pay.amount')}</p>
              <p style={{ fontSize: '1.6rem', fontWeight: 700, margin: '0 0 1rem', color: 'var(--text-primary)' }}>
                {formatAoa(checkout.amount)}
              </p>

              {/* Multicaixa Express */}
              {provider === 'multicaixa_express' && (
                <>
                  <ReferenceBox label={t('pay.reference')} value={checkout.provider_reference}
                    copied={copied === 'ref'} onCopy={() => copy('ref', checkout.provider_reference)} tCopy={t('pay.copy')} tCopied={t('pay.copied')} />
                  <ol style={olStyle}>
                    <li>{t('pay.step1')}</li><li>{t('pay.step2')}</li><li>{t('pay.step3')}</li>
                  </ol>
                  <Waiting text={t('pay.waiting')} />
                </>
              )}

              {/* Card */}
              {provider === 'visa_mastercard' && (
                <>
                  {checkout.redirect_url ? (
                    <a className="btn btn-primary" href={checkout.redirect_url} target="_blank" rel="noreferrer"
                      style={{ display: 'inline-flex', marginBottom: '0.75rem' }}>
                      <CreditCard size={16} /> {t('pay.card_continue')}
                    </a>
                  ) : (
                    <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>{t('pay.card_processing')}</p>
                  )}
                  <Waiting text={t('pay.waiting')} />
                </>
              )}

              {provider === 'paypal' && (
                <>
                  {checkout.redirect_url ? (
                    <a className="btn btn-primary" href={checkout.redirect_url} target="_blank" rel="noreferrer"
                      style={{ display: 'inline-flex', marginBottom: '0.75rem' }}>
                      <CreditCard size={16} /> PayPal
                    </a>
                  ) : (
                    <p style={{ color: 'var(--text-secondary)', fontSize: '0.9rem' }}>{t('pay.card_processing')}</p>
                  )}
                  <Waiting text={t('pay.waiting')} />
                </>
              )}

              {/* Bank transfer */}
              {provider === 'iban_transfer' && checkout.transfer_details && (
                <div style={{ textAlign: 'left' }}>
                  <TransferRow label={t('pay.bank')} value={String(checkout.transfer_details.bank_name ?? '')} />
                  <TransferRow label={t('pay.beneficiary')} value={String(checkout.transfer_details.beneficiary ?? '')} />
                  <ReferenceBox label="IBAN" value={String(checkout.transfer_details.iban ?? '')}
                    copied={copied === 'iban'} onCopy={() => copy('iban', String(checkout.transfer_details?.iban ?? ''))} tCopy={t('pay.copy')} tCopied={t('pay.copied')} />
                  <ReferenceBox label={t('pay.reference')} value={checkout.provider_reference}
                    copied={copied === 'ref'} onCopy={() => copy('ref', checkout.provider_reference)} tCopy={t('pay.copy')} tCopied={t('pay.copied')} />
                  <p style={{ color: 'var(--text-secondary)', fontSize: '0.82rem', marginTop: '0.75rem', lineHeight: 1.5 }}>
                    {t('pay.transfer_note')}
                  </p>
                  <button className="btn btn-primary" style={{ marginTop: '0.5rem', width: '100%' }} onClick={onClose}>
                    {t('common.close')}
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

const olStyle: React.CSSProperties = {
  textAlign: 'left', color: 'var(--text-secondary)', fontSize: '0.9rem',
  paddingLeft: '1.25rem', lineHeight: 1.6, margin: 0,
};

function ReferenceBox({ label, value, copied, onCopy, tCopy, tCopied }: {
  label: string; value?: string; copied: boolean; onCopy: () => void; tCopy: string; tCopied: string;
}) {
  return (
    <div style={{ background: 'var(--bg-subtle, rgba(148,163,184,0.12))', borderRadius: 12, padding: '0.85rem 1rem', margin: '0.5rem 0', textAlign: 'left' }}>
      <p style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', margin: '0 0 0.25rem' }}>{label}</p>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifyContent: 'space-between' }}>
        <code style={{ fontSize: '0.98rem', fontWeight: 600, letterSpacing: '0.5px', color: 'var(--text-primary)', wordBreak: 'break-all' }}>{value}</code>
        <button className="btn btn-ghost btn-sm" onClick={onCopy} style={{ flexShrink: 0 }}>
          <Copy size={14} /> {copied ? tCopied : tCopy}
        </button>
      </div>
    </div>
  );
}

function TransferRow({ label, value }: { label: string; value: string }) {
  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, padding: '0.35rem 0', borderBottom: '1px solid var(--border)' }}>
      <span style={{ color: 'var(--text-secondary)', fontSize: '0.85rem' }}>{label}</span>
      <span style={{ color: 'var(--text-primary)', fontSize: '0.85rem', fontWeight: 600 }}>{value}</span>
    </div>
  );
}

function Waiting({ text }: { text: string }) {
  return (
    <p style={{ display: 'flex', justifyContent: 'center', gap: 8, color: 'var(--text-secondary)', fontSize: '0.85rem', marginTop: '1rem' }}>
      <Loader2 size={14} style={spinStyle} /> {text}
    </p>
  );
}

import { useState } from 'react';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import { X, Star, CheckCircle2 } from 'lucide-react';

interface Props {
  open: boolean;
  consultationId: string;
  title?: string;
  onClose: () => void;
  onDone?: () => void;
}

export default function ReviewModal({ open, consultationId, title, onClose, onDone }: Props) {
  const { t } = useT();
  const [rating, setRating] = useState(0);
  const [hover, setHover] = useState(0);
  const [comment, setComment] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const [error, setError] = useState('');

  if (!open) return null;

  const submit = async () => {
    if (rating < 1) { setError(t('review.pick')); return; }
    setSubmitting(true);
    setError('');
    try {
      await api.post(`/api/v1/consultations/${consultationId}/review`, { rating, comment: comment.trim() || undefined });
      setDone(true);
      onDone?.();
    } catch (err: any) {
      setError(err.response?.data?.detail || t('review.error'));
    } finally {
      setSubmitting(false);
    }
  };

  const backdrop = (e: React.MouseEvent) => { if (e.target === e.currentTarget) onClose(); };

  return (
    <div onClick={backdrop} style={{
      position: 'fixed', inset: 0, zIndex: 9999, background: 'rgba(0,0,0,0.5)',
      backdropFilter: 'blur(4px)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '1rem',
    }}>
      <div style={{
        background: 'var(--bg-card)', border: '1px solid var(--border)', borderRadius: '16px',
        width: '100%', maxWidth: '400px', boxShadow: '0 20px 60px rgba(0,0,0,0.3)', animation: 'fadeIn 0.2s ease',
      }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '1rem 1.25rem', borderBottom: '1px solid var(--border)' }}>
          <h3 style={{ margin: 0, fontSize: '1rem', fontWeight: 700, color: 'var(--text-primary)' }}>{t('review.title')}</h3>
          <button onClick={onClose} aria-label={t('common.close')} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}><X size={18} /></button>
        </div>

        <div style={{ padding: '1.5rem', textAlign: 'center' }}>
          {done ? (
            <>
              <CheckCircle2 size={44} style={{ color: '#22c55e' }} />
              <p style={{ color: 'var(--text-primary)', fontWeight: 600, marginTop: '0.75rem' }}>{t('review.thanks')}</p>
              <button className="btn btn-primary" style={{ marginTop: '0.5rem' }} onClick={onClose}>{t('common.close')}</button>
            </>
          ) : (
            <>
              {title && <p style={{ color: 'var(--text-secondary)', marginTop: 0, fontSize: '0.85rem' }}>{title}</p>}
              <div style={{ display: 'flex', justifyContent: 'center', gap: '0.35rem', margin: '0.75rem 0 1rem' }}>
                {[1, 2, 3, 4, 5].map(i => (
                  <button key={i} onClick={() => setRating(i)} onMouseEnter={() => setHover(i)} onMouseLeave={() => setHover(0)}
                    style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}>
                    <Star size={32} fill={i <= (hover || rating) ? '#f59e0b' : 'none'} style={{ color: '#f59e0b' }} />
                  </button>
                ))}
              </div>
              <textarea className="form-input" placeholder={t('review.comment_ph')} value={comment}
                onChange={e => setComment(e.target.value)} rows={3}
                style={{ width: '100%', resize: 'vertical', marginBottom: '0.75rem' }} />
              {error && <p style={{ color: '#ef4444', fontSize: '0.82rem', margin: '0 0 0.5rem' }}>{error}</p>}
              <button className="btn btn-primary" style={{ width: '100%' }} disabled={submitting} onClick={submit}>
                {submitting ? t('review.sending') : t('review.submit')}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { NavLink, useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../AuthContext';
import { getInitials } from '../api';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import { useUnreadNotifications } from '../hooks/useUnreadNotifications';
import { useState, useEffect } from 'react';
import {
  Activity, User, Users, Stethoscope, ClipboardList, Calendar,
  Shield, ShieldCheck, LayoutDashboard, LogOut, UserCog, Heart, Settings, Home, X, HeartPulse, Briefcase, Building2, Clock, ShoppingBag,
  Cpu, CreditCard, UserCheck, Bell, Video, FileText, MessageSquare,
  DollarSign, Star, Globe, HelpCircle, Lock, FileCheck2,
} from 'lucide-react';

interface Props {
  open: boolean;
  onClose: () => void;
}

export function Sidebar({ open, onClose }: Props) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
