export type ViewType = 'orientation' | 'context' | 'closeup';

interface PhotoSlot {
  viewType: ViewType;
  labelKey: string;
  helpKey: string;
}

interface PreparedPhoto {
  blob: Blob;
  previewUrl: string;
  technicalCheck: {
    original_width: number;
    original_height: number;
    sanitized_width: number;
    sanitized_height: number;
    average_brightness: number;
    issues: string[];
    metadata_removed: true;
  };
}

const PHOTO_SLOTS: PhotoSlot[] = [
  { viewType: 'orientation', labelKey: 'triage.photo_orientation', helpKey: 'triage.photo_orientation_help' },
  { viewType: 'context', labelKey: 'triage.photo_context', helpKey: 'triage.photo_context_help' },
  { viewType: 'closeup', labelKey: 'triage.photo_closeup', helpKey: 'triage.photo_closeup_help' },
];

async function preparePhoto(file: File): Promise<PreparedPhoto> {
  const sourceUrl = URL.createObjectURL(file);
  try {
    const image = new Image();
    image.decoding = 'async';
    image.src = sourceUrl;
    await image.decode();

    const originalWidth = image.naturalWidth;
    const originalHeight = image.naturalHeight;
    const scale = Math.min(1, 1600 / Math.max(originalWidth, originalHeight));
    const width = Math.max(1, Math.round(originalWidth * scale));
    const height = Math.max(1, Math.round(originalHeight * scale));
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext('2d', { willReadFrequently: true });
    if (!context) throw new Error('canvas-unavailable');
    context.fillStyle = '#fff';
    context.fillRect(0, 0, width, height);
    context.drawImage(image, 0, 0, width, height);

    const sampleCanvas = document.createElement('canvas');
    const sampleWidth = Math.min(160, width);
    const sampleHeight = Math.max(1, Math.round(height * (sampleWidth / width)));
    sampleCanvas.width = sampleWidth;
    sampleCanvas.height = sampleHeight;
    const sampleContext = sampleCanvas.getContext('2d', { willReadFrequently: true });
    if (!sampleContext) throw new Error('canvas-unavailable');
    sampleContext.drawImage(canvas, 0, 0, sampleWidth, sampleHeight);
    const pixels = sampleContext.getImageData(0, 0, sampleWidth, sampleHeight).data;
    let brightnessTotal = 0;
    for (let i = 0; i < pixels.length; i += 4) {
      brightnessTotal += (pixels[i] * 0.299) + (pixels[i + 1] * 0.587) + (pixels[i + 2] * 0.114);
    }
    const averageBrightness = Math.round(brightnessTotal / (pixels.length / 4));
    const issues: string[] = [];
    if (Math.min(originalWidth, originalHeight) < 640) issues.push('low_resolution');
    if (averageBrightness < 45) issues.push('too_dark');
    if (averageBrightness > 235) issues.push('too_bright');

    const blob = await new Promise<Blob>((resolve, reject) => {
      canvas.toBlob(
        value => value ? resolve(value) : reject(new Error('image-encode-failed')),
        'image/jpeg',
        0.88,
      );
    });
    return {
      blob,
      previewUrl: URL.createObjectURL(blob),
      technicalCheck: {
        original_width: originalWidth,
        original_height: originalHeight,
        sanitized_width: width,
        sanitized_height: height,
        average_brightness: averageBrightness,
        issues,
        metadata_removed: true,
      },
    };
  } finally {
    URL.revokeObjectURL(sourceUrl);
  }
}

export default function TriagePhotoGuide({
  sessionId,
  requestedViews,
  onPhotoUploaded,
}: {
  sessionId: string;
  requestedViews?: ViewType[];
  onPhotoUploaded?: (viewType: ViewType) => void;
}) {
  const { t } = useT();
  const [consented, setConsented] = useState(false);
  const [previews, setPreviews] = useState<Partial<Record<ViewType, string>>>({});
  const [photoIds, setPhotoIds] = useState<Partial<Record<ViewType, string>>>({});
  const [warnings, setWarnings] = useState<Partial<Record<ViewType, string[]>>>({});
  const [uploading, setUploading] = useState<ViewType | null>(null);
  const [deleting, setDeleting] = useState<ViewType | null>(null);
  const [exporting, setExporting] = useState(false);
  const [error, setError] = useState('');
  const previewRef = useRef(previews);

  useEffect(() => {
    previewRef.current = previews;
  }, [previews]);

  useEffect(() => () => {
    Object.values(previewRef.current).forEach(url => {
      if (url) URL.revokeObjectURL(url);
    });
  }, []);

  const upload = async (slot: PhotoSlot, file?: File) => {
    if (!file || !consented || uploading) return;
    setError('');
    setUploading(slot.viewType);
    try {
      const prepared = await preparePhoto(file);
      const form = new FormData();
      form.append('file', prepared.blob, `${slot.viewType}.jpg`);
      form.append('view_type', slot.viewType);
      form.append('technical_check', JSON.stringify(prepared.technicalCheck));
      const response = await api.post(`/api/v1/triage/${sessionId}/photos`, form, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setPhotoIds(current => ({ ...current, [slot.viewType]: response.data.id }));
      setPreviews(current => {
        const previous = current[slot.viewType];
        if (previous) URL.revokeObjectURL(previous);
        return { ...current, [slot.viewType]: prepared.previewUrl };
      });
      setWarnings(current => ({ ...current, [slot.viewType]: prepared.technicalCheck.issues }));
      onPhotoUploaded?.(slot.viewType);
    } catch (uploadError: any) {
      setError(apiErrorMessage(uploadError, t('triage.photo_upload_error')));
    } finally {
      setUploading(null);
    }
  };

  const remove = async (viewType: ViewType) => {
    const photoId = photoIds[viewType];
    if (!photoId || deleting || !window.confirm(t('triage.photo_delete_confirm'))) return;
    setDeleting(viewType);
    setError('');
    try {
      await api.delete(`/api/v1/triage/${sessionId}/photos/${photoId}`);
      setPreviews(current => {
        const preview = current[viewType];
        if (preview) URL.revokeObjectURL(preview);
        const next = { ...current };
        delete next[viewType];
        return next;
      });
      setPhotoIds(current => {
        const next = { ...current };
        delete next[viewType];
        return next;
      });
      setWarnings(current => {
        const next = { ...current };
        delete next[viewType];
        return next;
      });
    } catch (deleteError: any) {
      setError(apiErrorMessage(deleteError, t('triage.photo_delete_error')));
    } finally {
      setDeleting(null);
    }
  };

  const warningLabel = (issue: string) => {
    if (issue === 'too_dark') return t('triage.photo_too_dark');
    if (issue === 'too_bright') return t('triage.photo_too_bright');
    return t('triage.photo_low_resolution');
  };

  const exportPhotos = async () => {
    if (exporting || !Object.keys(photoIds).length) return;
    setExporting(true);
    setError('');
    try {
      const response = await api.get(`/api/v1/triage/${sessionId}/photos-export`, {
        responseType: 'blob',
      });
      const url = URL.createObjectURL(response.data);
      const link = document.createElement('a');
      link.href = url;
      link.download = `kaya-triage-${sessionId}-photos.zip`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (exportError: any) {
      setError(apiErrorMessage(exportError, t('triage.photo_export_error')));
    } finally {
      setExporting(false);
    }
  };

  return (
    <section className="triage-photo-guide" aria-labelledby="triage-photo-title">
      <div className="triage-photo-guide__heading">
        <div className="triage-photo-guide__icon"><Camera size={20} /></div>
        <div>
          <h4 id="triage-photo-title">{t('triage.photo_title')}</h4>
          <p>{t('triage.photo_intro')}</p>
        </div>
      </div>

      <div className="triage-photo-guide__boundary">
        <ShieldCheck size={17} />
        <span>{t('triage.photo_boundary')}</span>
      </div>

      <label className="triage-photo-guide__consent">
        <input
          type="checkbox"
          checked={consented}
          onChange={event => setConsented(event.target.checked)}
        />
        <span>{t('triage.photo_consent')}</span>
      </label>

      <div className="triage-photo-guide__grid">
        {PHOTO_SLOTS
          .filter(slot => !requestedViews?.length || requestedViews.includes(slot.viewType))
          .map((slot, index) => {
          const preview = previews[slot.viewType];
          const slotWarnings = warnings[slot.viewType] || [];
          const isUploading = uploading === slot.viewType;
          const isDeleting = deleting === slot.viewType;
          return (
            <div className="triage-photo-slot" key={slot.viewType}>
              <div className="triage-photo-slot__number">{index + 1}</div>
              {preview ? (
                <img src={preview} alt={t(slot.labelKey)} className="triage-photo-slot__preview" />
              ) : (
                <div className="triage-photo-slot__placeholder"><ImagePlus size={24} /></div>
              )}
              <strong>{t(slot.labelKey)}</strong>
              <span>{t(slot.helpKey)}</span>
              <div className="triage-photo-slot__actions">
                <label className={`btn btn-sm ${preview ? 'btn-outline' : 'btn-primary'} triage-photo-slot__button`}>
                  {preview ? <CheckCircle2 size={14} /> : <Camera size={14} />}
                  {isUploading ? t('triage.photo_uploading') : preview ? t('triage.photo_replace') : t('triage.photo_add')}
                  <input
                    type="file"
                    accept="image/jpeg,image/png,image/webp"
                    capture="environment"
                    disabled={!consented || Boolean(uploading) || Boolean(deleting)}
                    onChange={event => {
                      void upload(slot, event.target.files?.[0]);
                      event.currentTarget.value = '';
                    }}
                  />
                </label>
                {preview && (
                  <button
                    type="button"
                    className="btn btn-sm btn-outline triage-photo-slot__delete"
                    disabled={Boolean(uploading) || Boolean(deleting)}
                    onClick={() => void remove(slot.viewType)}
                    title={t('triage.photo_delete')}
                  >
                    <Trash2 size={14} />
                    {isDeleting ? t('triage.photo_deleting') : t('triage.photo_delete')}
                  </button>
                )}
              </div>
              {slotWarnings.length > 0 && (
                <div className="triage-photo-slot__warning">
                  <TriangleAlert size={13} />
                  <span>{slotWarnings.map(warningLabel).join(' · ')}</span>
                </div>
              )}
            </div>
          );
          })}
      </div>

      <div className="triage-photo-guide__footer">
        <p className="triage-photo-guide__optional">{t('triage.photo_optional')}</p>
        {Object.keys(photoIds).length > 0 && (
          <button
            type="button"
            className="btn btn-sm btn-outline triage-photo-guide__export"
            disabled={exporting || Boolean(uploading) || Boolean(deleting)}
            onClick={() => void exportPhotos()}
          >
            <Download size={14} />
            {exporting ? t('triage.photo_exporting') : t('triage.photo_export')}
          </button>
        )}
      </div>
      {error && <div className="triage-photo-guide__error">{error}</div>}
    </section>
  );
}

import { useEffect, useState } from 'react';
import { Camera, ImagePlus, ShieldCheck, TriangleAlert } from 'lucide-react';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import { apiErrorMessage } from '../utils/apiError';

interface TriagePhoto {
  id: string;
  view_type: 'orientation' | 'context' | 'closeup';
  content_url: string;
  technical_check?: { issues?: string[] };
}

interface ReviewPhoto extends TriagePhoto {
  objectUrl: string;
}

interface PhotoRequest {
  id: string;
  view_type: 'orientation' | 'context' | 'closeup';
  message?: string;
  status: 'requested' | 'fulfilled';
}

const VIEW_KEYS = {
  orientation: 'triage.photo_orientation',
  context: 'triage.photo_context',
  closeup: 'triage.photo_closeup',
} as const;

export default function TriagePhotoReview({ triageId }: { triageId: string }) {
  const { t } = useT();
  const [photos, setPhotos] = useState<ReviewPhoto[]>([]);
  const [requests, setRequests] = useState<PhotoRequest[]>([]);
  const [loading, setLoading] = useState(true);
  const [requesting, setRequesting] = useState(false);
  const [requestView, setRequestView] = useState<PhotoRequest['view_type']>('closeup');
  const [requestMessage, setRequestMessage] = useState('');
  const [requestError, setRequestError] = useState('');

  useEffect(() => {
    let active = true;
    const objectUrls: string[] = [];
    setLoading(true);
    Promise.resolve()
      .then(async () => {
        const [metadata, requestData] = await Promise.all([
          api.get<TriagePhoto[]>(`/api/v1/triage/${triageId}/photos`),
          api.get<PhotoRequest[]>(`/api/v1/triage/${triageId}/photo-requests`),
        ]);
        const loaded = await Promise.all(metadata.data.map(async photo => {
          const content = await api.get(photo.content_url, { responseType: 'blob' });
          const objectUrl = URL.createObjectURL(content.data);
          objectUrls.push(objectUrl);
          return { ...photo, objectUrl };
        }));
        if (active) {
          setPhotos(loaded);
          setRequests(requestData.data);
        }
      })
      .catch(() => {
        if (active) setPhotos([]);
      })
      .finally(() => {
        if (active) setLoading(false);
      });
    return () => {
      active = false;
      objectUrls.forEach(url => URL.revokeObjectURL(url));
    };
  }, [triageId]);

  const submitRequest = async () => {
    setRequesting(true);
    setRequestError('');
    try {
      const response = await api.post<PhotoRequest>(
        `/api/v1/triage/${triageId}/photo-requests`,
        { view_type: requestView, message: requestMessage.trim() || undefined },
      );
      setRequests(current => [
        response.data,
        ...current.filter(item => item.id !== response.data.id),
      ]);
      setRequestMessage('');
    } catch (error: any) {
      setRequestError(apiErrorMessage(error, t('triage.photo_request_error')));
    } finally {
      setRequesting(false);
    }
  };

  if (loading) {
    return <div style={{ color: 'var(--text-muted)', fontSize: '0.78rem' }}>{t('triage.photo_review_loading')}</div>;
  }
  return (
    <section className="triage-photo-review">
      <div className="triage-photo-review__title">
        <Camera size={15} />
        <strong>{t('triage.photo_review_title')}</strong>
        <span>{photos.length}</span>
      </div>
      <div className="triage-photo-review__boundary">
        <ShieldCheck size={14} />
        <span>{t('triage.photo_review_boundary')}</span>
      </div>
      {photos.length > 0 ? (
        <div className="triage-photo-review__grid">
          {photos.map(photo => (
          <figure key={photo.id}>
            <img src={photo.objectUrl} alt={t(VIEW_KEYS[photo.view_type])} />
            <figcaption>{t(VIEW_KEYS[photo.view_type])}</figcaption>
            {Boolean(photo.technical_check?.issues?.length) && (
              <div className="triage-photo-review__warning" title={photo.technical_check?.issues?.join(', ')}>
                <TriangleAlert size={12} /> {t('triage.photo_review_quality')}
              </div>
            )}
          </figure>
          ))}
        </div>
      ) : (
        <p className="triage-photo-review__empty">{t('triage.photo_review_empty')}</p>
      )}
      <div className="triage-photo-review__request">
        <div className="triage-photo-review__request-title">
          <ImagePlus size={14} />
          <strong>{t('triage.photo_request_title')}</strong>
        </div>
        {requests.filter(request => request.status === 'requested').map(request => (
          <div className="triage-photo-review__request-pending" key={request.id}>
            {t(VIEW_KEYS[request.view_type])}
            {request.message ? ` — ${request.message}` : ''}
          </div>
        ))}
        <div className="triage-photo-review__request-form">
          <select
            className="form-select"
            value={requestView}
            onChange={event => setRequestView(event.target.value as PhotoRequest['view_type'])}
          >
            {(Object.keys(VIEW_KEYS) as PhotoRequest['view_type'][]).map(view => (
              <option key={view} value={view}>{t(VIEW_KEYS[view])}</option>
            ))}
          </select>
          <input
            className="form-input"
            maxLength={500}
            placeholder={t('triage.photo_request_placeholder')}
            value={requestMessage}
            onChange={event => setRequestMessage(event.target.value)}
          />
          <button
            type="button"
            className="btn btn-sm btn-primary"
            disabled={requesting}
            onClick={() => void submitRequest()}
          >
            {requesting ? t('triage.photo_request_sending') : t('triage.photo_request_send')}
          </button>
        </div>
        {requestError && <div className="triage-photo-guide__error">{requestError}</div>}
      </div>
    </section>
  );
}

