import { useState, useEffect, useCallback } from 'react';
import api from '../api';
import { useAuth } from '../AuthContext';

/**
 * Polls /api/v1/notifications/unread-count every 60 s.
 * Returns the count so the sidebar badge stays in sync.
 */
export function useUnreadNotifications(pollMs = 60_000): number {
  const { user } = useAuth();
  const [count, setCount] = useState(0);

  const fetch = useCallback(async () => {
    if (!user) return;
    try {
      const { data } = await api.get<{ unread: number }>('/api/v1/notifications/unread-count');
      setCount(data.unread);
    } catch {
      // ignore — non-critical
    }
  }, [user]);

  useEffect(() => {
    fetch();
    const id = setInterval(fetch, pollMs);
    return () => clearInterval(id);
  }, [fetch, pollMs]);

  return count;
}

import { createContext, useContext, useState, useCallback, type ReactNode } from 'react';
import translations, { type Lang, LANG_LABELS, LANG_FLAGS } from './translations';

interface I18nContextValue {
  lang: Lang;
  setLang: (lang: Lang) => void;
  t: (key: string) => string;
}

const I18nContext = createContext<I18nContextValue>({
  lang: 'pt',
  setLang: () => {},
  t: (k: string) => k,
});

const STORAGE_KEY = 'health_lang';

function getInitialLang(): Lang {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved === 'pt' || saved === 'en' || saved === 'fr' || saved === 'es' || saved === 'zh') return saved;
  } catch { /* SSR / no localStorage */ }
  return 'pt';
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [lang, setLangState] = useState<Lang>(getInitialLang);

  const setLang = useCallback((newLang: Lang) => {
    setLangState(newLang);
    try { localStorage.setItem(STORAGE_KEY, newLang); } catch { /* ignore */ }
  }, []);

  const t = useCallback(
    (key: string): string => {
      const entry = translations[key];
      if (!entry) return key; // fallback: show key itself
      // Chinese (and any missing translation) falls back to English, then Portuguese.
      return entry[lang] ?? entry.en ?? entry.pt ?? key;
    },
    [lang],
  );

  return (
    <I18nContext.Provider value={{ lang, setLang, t }}>
      {children}
    </I18nContext.Provider>
  );
}

export function useT() {
  return useContext(I18nContext);
}

export { LANG_LABELS, LANG_FLAGS };
export type { Lang };

