                <input className="form-input" value={specialty} onChange={e => setSpecialty(e.target.value)} placeholder={t('dreg.specialty_nurse_ph')} />
              ) : (
                <select className="form-input" value={specialty} onChange={e => setSpecialty(e.target.value)}>
                  {SPECIALTY_VALUES.map(v => <option key={v} value={v}>{t(`spec.${v}`)}</option>)}
                </select>
              )}
            </div>
            <div>
              <label className="form-label">{t('dreg.license')} *</label>
              <input className="form-input" placeholder={t('dreg.license_ph')} value={license} onChange={e => setLicense(e.target.value)} required />
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))', gap: '0.75rem' }}>
            {[
              ['dreg.country_practice', practiceCountry, setPracticeCountry],
              ['dreg.country_licence', licenceCountry, setLicenceCountry],
              ['dreg.country_diploma', diplomaCountry, setDiplomaCountry],
            ].map(([labelKey, value, setter]: any) => (
              <div key={labelKey}>
                <label className="form-label">{t(labelKey)}</label>
                <select className="form-input" value={value} onChange={e => setter(e.target.value)}>
                  {CREDENTIAL_COUNTRY_CODES.map(code => <option key={code} value={code}>{regionNames.of(code) || code}</option>)}
                </select>
              </div>
            ))}
          </div>
          {licenceCountry === 'US' && (
            <input className="form-input" placeholder={t('dreg.us_jurisdiction_ph')}
              value={licenceJurisdiction} onChange={e => setLicenceJurisdiction(e.target.value)} required />
          )}
          {practiceCountry !== diplomaCountry && (
            <div style={{ padding: '.65rem', borderRadius: 8, background: '#fffbeb', color: '#92400e', fontSize: '.78rem' }}>
              {t('dreg.foreign_diploma')}
            </div>
          )}
          <input className="form-input" placeholder={t('dreg.authority_ph')} value={authority} onChange={e => setAuthority(e.target.value)} required />
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
            <input className="form-input" placeholder={t('dreg.institution_ph')} value={institution} onChange={e => setInstitution(e.target.value)} required />
            <input className="form-input" placeholder={t('dreg.degree_ph')} value={degreeTitle} onChange={e => setDegreeTitle(e.target.value)} required />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
            <div>
              <label className="form-label">{t('dpe.years_exp')} <span style={{ color: 'var(--text-muted)', fontWeight: 400 }}>{t('dpe.optional')}</span></label>
              <input className="form-input" type="number" min="0" max="60" placeholder={t('dreg.years_ph')} value={years} onChange={e => setYears(e.target.value)} />
            </div>
          </div>

          {/* ── Location ── */}
          <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: 'var(--text-primary)', margin: 0, borderBottom: '1px solid var(--border)', paddingBottom: '0.75rem' }}>
            <MapPin size={15} style={{ verticalAlign: 'middle', marginRight: '0.4rem' }} />{t('dpe.sec_location')}
          </h3>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
            <div>
              <label className="form-label">{t('dpe.city')}</label>
              <input className="form-input" placeholder={t('dreg.city_ph')} value={city} onChange={e => setCity(e.target.value)} />
            </div>
            <div>
              <label className="form-label">{t('dpe.province')}</label>
              <select className="form-input" value={province} onChange={e => setProvince(e.target.value)}>
                <option value="">{t('dpe.select')}</option>
                {PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>

          {/* ── Consultation types ── */}
          <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: 'var(--text-primary)', margin: 0, borderBottom: '1px solid var(--border)', paddingBottom: '0.75rem' }}>
            <Globe size={15} style={{ verticalAlign: 'middle', marginRight: '0.4rem' }} />{t('dpe.sec_consult_type')}
          </h3>
          <div style={{ display: 'flex', gap: '0.75rem', flexWrap: 'wrap' }}>
            {[
              { key: 'teleconsulta', label: t('dpe.ct_tele') },
              { key: 'presencial',   label: t('dpe.ct_presencial') },
              { key: 'domicilio',    label: t('dpe.ct_domicilio') },
            ].map(ct => (
              <label key={ct.key} style={{
                display: 'flex', alignItems: 'center', gap: '0.4rem',
                padding: '0.5rem 1rem', borderRadius: '999px', cursor: 'pointer',
                background: consultTypes.includes(ct.key) ? 'var(--brand-light)' : 'var(--bg-card)',
                border: `1.5px solid ${consultTypes.includes(ct.key) ? 'var(--brand-primary)' : 'var(--border)'}`,
                color: consultTypes.includes(ct.key) ? 'var(--brand-primary)' : 'var(--text-secondary)',
                fontWeight: consultTypes.includes(ct.key) ? 600 : 400,
                fontSize: '0.85rem',
              }}>
                <input type="checkbox" checked={consultTypes.includes(ct.key)} onChange={() => toggleConsultType(ct.key)} style={{ display: 'none' }} />
                {ct.label}
              </label>
            ))}
          </div>

          {/* ── Bio ── */}
          <div>
            <label className="form-label"><BookOpen size={13} /> {t('dreg.bio_label')} <span style={{ color: 'var(--text-muted)', fontWeight: 400 }}>{t('dreg.bio_optional')}</span></label>
            <textarea className="form-input" rows={3} placeholder={t('dreg.bio_ph')} value={bio} onChange={e => setBio(e.target.value)} style={{ resize: 'vertical' }} />
          </div>

          {error && (
            <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', padding: '0.75rem 1rem', borderRadius: '10px', background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)', color: '#dc2626', fontSize: '0.85rem' }}>
              <AlertCircle size={16} /> {error}
            </div>
          )}

          <button type="submit" disabled={loading} className="btn btn-primary" style={{ padding: '0.9rem', fontSize: '0.95rem', fontWeight: 700 }}>
            {loading ? <><Loader2 size={16} style={{ animation: 'spin 1s linear infinite' }} /> {t('dreg.registering')}</> : <>{t('dreg.submit')} <ChevronRight size={16} /></>}
          </button>

          <p style={{ textAlign: 'center', fontSize: '0.78rem', color: 'var(--text-muted)' }}>
            {t('dreg.footer_pre')} <Link to="/terms" style={{ color: 'var(--brand-primary)' }}>{t('dreg.terms_link')}</Link>.
          </p>
        </form>
      </div>

      <Footer />
    </div>
  );
}

import { useState } from 'react';
import { Link } from 'react-router-dom';
import { Lock, Eye, EyeOff, ShieldCheck, ChevronRight } from 'lucide-react';
import api from '../api';
import { useT } from '../i18n/LanguageContext';

export default function DoctorSecurityPage() {
  const { t } = useT();
  const [form, setForm] = useState({ current: '', next: '', confirm: '' });
  const [show, setShow] = useState(false);
  const [msg, setMsg] = useState('');
  const [err, setErr] = useState('');
  const [loading, setLoading] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMsg(''); setErr('');
    if (form.next !== form.confirm) { setErr(t('dsec.mismatch')); return; }
    if (form.next.length < 8) { setErr(t('dsec.too_short')); return; }
    setLoading(true);
    try {
      await api.post('/auth/change-password', { old_password: form.current, new_password: form.next });
      setMsg(t('dsec.updated'));
      setForm({ current: '', next: '', confirm: '' });
    } catch (e: any) {
      setErr(e?.response?.data?.detail ?? t('dsec.update_error'));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ maxWidth: 540, margin: '0 auto', padding: '1.5rem 1.25rem 4rem' }}>
      <h1 style={{ fontSize: '1.25rem', fontWeight: 800, margin: '0 0 1.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
        <Lock size={20} style={{ color: 'var(--brand-primary)' }} /> {t('dsec.title')}
      </h1>

      <div className="card" style={{ padding: '1.5rem', marginBottom: '1rem' }}>
        <div style={{ fontWeight: 700, marginBottom: '1.25rem' }}>{t('dsec.change_password')}</div>
        <form onSubmit={submit}>
          {[
            { key: 'current', label: t('dsec.current') },
            { key: 'next',    label: t('dsec.new') },
            { key: 'confirm', label: t('dsec.confirm') },
          ].map(f => (
            <div key={f.key} style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', fontSize: '0.82rem', fontWeight: 600, marginBottom: '0.3rem' }}>{f.label}</label>
              <div style={{ position: 'relative' }}>
                <input className="form-input" type={show ? 'text' : 'password'} value={(form as any)[f.key]} onChange={e => setForm(prev => ({ ...prev, [f.key]: e.target.value }))} required style={{ paddingRight: '2.5rem' }} />
                <button type="button" onClick={() => setShow(s => !s)} style={{ position: 'absolute', right: '0.75rem', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}>
                  {show ? <EyeOff size={16} /> : <Eye size={16} />}
                </button>
              </div>
            </div>
          ))}
          {err && <div style={{ color: '#dc2626', fontSize: '0.82rem', marginBottom: '0.75rem' }}>{err}</div>}
          {msg && <div style={{ color: '#059669', fontSize: '0.82rem', marginBottom: '0.75rem' }}>{msg}</div>}
          <button type="submit" disabled={loading} style={{ width: '100%', padding: '0.7rem', borderRadius: '10px', background: 'var(--brand-primary)', color: '#fff', border: 'none', fontWeight: 700, cursor: 'pointer' }}>
            {loading ? t('dsec.saving') : t('dsec.update_btn')}
          </button>
        </form>
      </div>

      <Link to="/security/mfa" className="card" style={{ padding: '1.25rem', display: 'flex', alignItems: 'center', gap: '1rem', textDecoration: 'none', color: 'inherit' }}>
        <ShieldCheck size={28} style={{ color: '#10b981', flexShrink: 0 }} />
        <div>
          <div style={{ fontWeight: 700, fontSize: '0.9rem' }}>{t('dsec.mfa_title')}</div>
          <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)', marginTop: '0.2rem' }}>{t('dsec.mfa_desc')}</div>
        </div>
        <ChevronRight size={18} style={{ marginLeft: 'auto', color: 'var(--text-muted)' }} />
      </Link>
    </div>
  );
}

import { useState, useEffect, useCallback, type ReactElement } from 'react';
import { Link } from 'react-router-dom';
import { Search, MapPin, Video, Building2, Home, Star, Filter, X, Loader2 } from 'lucide-react';
import api from '../api';
import { useT } from '../i18n/LanguageContext';

// value = filter code sent to backend; labelKey = translation key ('' = all).
const SPECIALTY_OPTIONS: Array<{ value: string; labelKey: string }> = [
  { value: '', labelKey: 'dlist.all_specialties' },
  { value: 'clinica_geral', labelKey: 'spec.clinica_geral' },
  { value: 'pediatria', labelKey: 'spec.pediatria' },
  { value: 'cardiologia', labelKey: 'spec.cardiologia' },
  { value: 'ginecologia', labelKey: 'spec.ginecologia' },
  { value: 'dermatologia', labelKey: 'spec.dermatologia' },
  { value: 'ortopedia', labelKey: 'spec.ortopedia' },
  { value: 'oftalmologia', labelKey: 'spec.oftalmologia' },
  { value: 'neurologia', labelKey: 'spec.neurologia' },
  { value: 'psiquiatria', labelKey: 'spec.psiquiatria' },
  { value: 'psicologia', labelKey: 'spec.psicologia' },
  { value: 'fisioterapia', labelKey: 'spec.fisioterapia' },
  { value: 'odontologia', labelKey: 'spec.odontologia' },
  { value: 'medicina_interna', labelKey: 'spec.medicina_interna' },
  { value: 'urgencia', labelKey: 'spec.urgencia' },
  { value: 'outro', labelKey: 'spec.outro' },
];

const CONSULT_ICONS: Record<string, ReactElement> = {
  teleconsulta: <Video size={12} />,
  presencial: <Building2 size={12} />,
  domicilio: <Home size={12} />,
};

const CONSULT_KEYS: Record<string, string> = {
  teleconsulta: 'appt.teleconsulta',
  presencial: 'appt.presencial',
  domicilio: 'appt.domicilio',
};

interface Doctor {
  id: number;
  display_name: string | null;
  title: string | null;
  specialization: string | null;
  slug: string | null;
  photo_url: string | null;
  bio: string | null;
  location_city: string | null;
  location_province: string | null;
  years_experience: number | null;
  accepts_new_patients: boolean | null;
  consultation_types: string[] | null;
  price_min: number | null;
  price_max: number | null;
  languages: string[] | null;
}

export default function DoctorsListPage() {
  const { t } = useT();
  const [doctors, setDoctors] = useState<Doctor[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [specialty, setSpecialty] = useState('');
  const [consultType, setConsultType] = useState('');
  const [showFilters, setShowFilters] = useState(false);

  const fetchDoctors = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const params: Record<string, string> = {};
      if (specialty) params.specialty = specialty;
      if (consultType) params.consultation_type = consultType;
      const res = await api.get('/api/v1/doctors/', { params });
      let data: Doctor[] = res.data;
      if (search.trim()) {
        const q = search.toLowerCase();
        data = data.filter(d =>
          d.display_name?.toLowerCase().includes(q) ||
          d.location_city?.toLowerCase().includes(q) ||
          d.specialization?.toLowerCase().includes(q) ||
          d.bio?.toLowerCase().includes(q)
        );
      }
      setDoctors(data);
    } catch {
      setError(t('dlist.error'));
    } finally {
      setLoading(false);
    }
  }, [specialty, consultType, search, t]);

  useEffect(() => { fetchDoctors(); }, [fetchDoctors]);

  const activeFilters = [specialty, consultType].filter(Boolean).length;

  return (
    <div style={{ maxWidth: 960, margin: '0 auto', padding: '2rem 1.25rem 4rem' }}>
      <div style={{ marginBottom: '2rem' }}>
        <h1 style={{ fontSize: '1.6rem', fontWeight: 800, margin: '0 0 0.25rem' }}>{t('dlist.title')}</h1>
        <p style={{ color: 'var(--text-secondary)', margin: 0, fontSize: '0.9rem' }}>
          {t('dlist.subtitle')}
        </p>
      </div>

      {/* Search + filter bar */}
      <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1.25rem', flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 240, position: 'relative' }}>
          <Search size={16} style={{ position: 'absolute', left: '0.8rem', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
          <input
            className="form-input"
            placeholder={t('dlist.search_ph')}
            value={search}
            onChange={e => setSearch(e.target.value)}
            style={{ paddingLeft: '2.2rem' }}
          />
        </div>
        <button
          onClick={() => setShowFilters(f => !f)}
          style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', padding: '0.6rem 1rem', borderRadius: '10px', border: '1.5px solid var(--border)', background: showFilters ? 'var(--brand-light)' : 'var(--bg-card)', color: showFilters ? 'var(--brand-primary)' : 'var(--text-secondary)', fontWeight: 600, fontSize: '0.85rem', cursor: 'pointer' }}
        >
          <Filter size={15} /> {t('dlist.filters')} {activeFilters > 0 && <span style={{ background: 'var(--brand-primary)', color: '#fff', borderRadius: 999, padding: '0 5px', fontSize: '0.7rem' }}>{activeFilters}</span>}
        </button>
      </div>

      {showFilters && (
        <div style={{ display: 'flex', gap: '0.75rem', marginBottom: '1.25rem', flexWrap: 'wrap', padding: '1rem', borderRadius: '12px', background: 'var(--bg-card)', border: '1px solid var(--border)' }}>
          <select className="form-input" style={{ minWidth: 200 }} value={specialty} onChange={e => setSpecialty(e.target.value)}>
            {SPECIALTY_OPTIONS.map(s => <option key={s.value} value={s.value}>{t(s.labelKey)}</option>)}
          </select>
          <select className="form-input" style={{ minWidth: 180 }} value={consultType} onChange={e => setConsultType(e.target.value)}>
            <option value="">{t('dlist.consult_type')}</option>
            <option value="teleconsulta">📹 {t('appt.teleconsulta')}</option>
            <option value="presencial">🏥 {t('appt.presencial')}</option>
            <option value="domicilio">🏠 {t('appt.domicilio')}</option>
          </select>
          {activeFilters > 0 && (
            <button onClick={() => { setSpecialty(''); setConsultType(''); }} style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', padding: '0.5rem 0.85rem', borderRadius: '8px', border: 'none', background: 'rgba(239,68,68,0.08)', color: '#dc2626', fontWeight: 600, fontSize: '0.82rem', cursor: 'pointer' }}>
              <X size={13} /> {t('dlist.clear')}
            </button>
          )}
        </div>
      )}

      {loading ? (
        <div style={{ display: 'flex', justifyContent: 'center', padding: '4rem 0' }}>
          <Loader2 size={28} style={{ color: 'var(--brand-primary)', animation: 'spin 1s linear infinite' }} />
        </div>
      ) : error ? (
        <div style={{ textAlign: 'center', padding: '3rem 0', color: 'var(--text-muted)' }}>{error}</div>
      ) : doctors.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '4rem 0' }}>
          <p style={{ color: 'var(--text-secondary)', fontSize: '0.95rem' }}>{t('dlist.empty')}</p>
          {(specialty || consultType || search) && (
            <button onClick={() => { setSpecialty(''); setConsultType(''); setSearch(''); }} style={{ marginTop: '0.75rem', padding: '0.5rem 1rem', borderRadius: '8px', border: 'none', background: 'var(--brand-primary)', color: '#fff', fontWeight: 600, fontSize: '0.85rem', cursor: 'pointer' }}>
              {t('dlist.clear')}
            </button>
          )}
        </div>
      ) : (
        <>
          <p style={{ fontSize: '0.82rem', color: 'var(--text-muted)', marginBottom: '1rem' }}>
            {doctors.length} {doctors.length !== 1 ? t('dlist.found_many') : t('dlist.found_one')}
          </p>
          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '1rem' }}>
            {doctors.map(d => (
              <DoctorCard key={d.id} doctor={d} />
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function DoctorCard({ doctor: d }: { doctor: Doctor }) {
  const { t } = useT();
  const initials = (d.display_name || 'M').split(' ').map(w => w[0]).slice(0, 2).join('').toUpperCase();
  const specKey = SPECIALTY_OPTIONS.find(s => s.value === d.specialization)?.labelKey;
  const specialtyLabel = specKey ? t(specKey) : d.specialization ?? t('dlist.default_specialty');

  return (
    <Link to={d.slug ? `/medicos/${d.slug}` : '#'} style={{ textDecoration: 'none', color: 'inherit' }}>
      <div className="card" style={{ padding: '1.25rem', transition: 'box-shadow 0.2s, transform 0.15s', cursor: 'pointer' }}
        onMouseEnter={e => { (e.currentTarget as HTMLElement).style.transform = 'translateY(-2px)'; (e.currentTarget as HTMLElement).style.boxShadow = '0 8px 24px rgba(0,0,0,0.1)'; }}
        onMouseLeave={e => { (e.currentTarget as HTMLElement).style.transform = ''; (e.currentTarget as HTMLElement).style.boxShadow = ''; }}>
        <div style={{ display: 'flex', gap: '0.9rem', alignItems: 'flex-start' }}>
          {d.photo_url ? (
            <img src={d.photo_url} alt={d.display_name || ''} style={{ width: 52, height: 52, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }} />
          ) : (
            <div style={{ width: 52, height: 52, borderRadius: '50%', background: 'var(--brand-light)', color: 'var(--brand-primary)', fontWeight: 800, fontSize: '1.1rem', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
              {initials}
            </div>
          )}
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 700, fontSize: '0.95rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {d.title ? `${d.title} ` : ''}{d.display_name || t('dlist.doctor')}
            </div>
            <div style={{ fontSize: '0.8rem', color: 'var(--brand-primary)', fontWeight: 600, marginTop: '0.1rem' }}>{specialtyLabel}</div>
          </div>
        </div>

        {d.bio && (
          <p style={{ fontSize: '0.8rem', color: 'var(--text-secondary)', margin: '0.75rem 0 0', lineHeight: 1.5, display: '-webkit-box', WebkitLineClamp: 2, WebkitBoxOrient: 'vertical', overflow: 'hidden' }}>
            {d.bio}
          </p>
        )}

        <div style={{ display: 'flex', gap: '0.5rem', marginTop: '0.75rem', flexWrap: 'wrap' }}>
          {(d.consultation_types || []).map(ct => (
            <span key={ct} style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.72rem', padding: '0.25rem 0.6rem', borderRadius: 999, background: 'var(--brand-light)', color: 'var(--brand-primary)', fontWeight: 600 }}>
              {CONSULT_ICONS[ct]} {CONSULT_KEYS[ct] ? t(CONSULT_KEYS[ct]) : ct}
            </span>
          ))}
          {d.accepts_new_patients === false && (
            <span style={{ fontSize: '0.72rem', padding: '0.25rem 0.6rem', borderRadius: 999, background: 'rgba(239,68,68,0.08)', color: '#dc2626', fontWeight: 600 }}>{t('dlist.no_slots')}</span>
          )}
        </div>

        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.85rem' }}>
          {(d.location_city || d.location_province) && (
            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.77rem', color: 'var(--text-muted)' }}>
              <MapPin size={11} /> {[d.location_city, d.location_province].filter(Boolean).join(', ')}
            </span>
          )}
          {(d.price_min || d.price_max) && (
            <span style={{ fontSize: '0.77rem', fontWeight: 600, color: 'var(--text-secondary)', marginLeft: 'auto' }}>
              {d.price_min && d.price_max ? `${d.price_min.toLocaleString()}–${d.price_max.toLocaleString()} Kz` : d.price_min ? `${t('dlist.price_from')} ${d.price_min.toLocaleString()} Kz` : `${t('dlist.price_upto')} ${d.price_max!.toLocaleString()} Kz`}
            </span>
          )}
        </div>
      </div>
    </Link>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import {
  Users, Plus, Trash2, Save, X, Edit2, Activity,
  Phone, Mail, AlertCircle, Loader2,
} from 'lucide-react';

// ── Types ─────────────────────────────────────────────────────────────────────

interface FamilyMember {
  id: string;
  owner_patient_id: string;
  full_name: string;
  relationship: string;
  date_of_birth: string | null;
  gender: string | null;
  phone: string | null;
  email: string | null;
  is_minor: boolean;
  emergency_contact: boolean;
  notes: string | null;
  created_at: string;
}

interface FormState {
  full_name: string;
  relationship: string;
  date_of_birth: string;
  gender: string;
  phone: string;
  email: string;
  is_minor: boolean;
  emergency_contact: boolean;
  notes: string;
}

const BLANK_FORM: FormState = {
  full_name: '', relationship: 'filho', date_of_birth: '',
  gender: '', phone: '', email: '',
  is_minor: false, emergency_contact: false, notes: '',
};

const REL_OPTIONS = [
  { value: 'filho',    key: 'fam.rel_filho' },
  { value: 'filha',    key: 'fam.rel_filha' },
  { value: 'pai',      key: 'fam.rel_pai' },
  { value: 'mãe',      key: 'fam.rel_mae' },
  { value: 'cônjuge',  key: 'fam.rel_conjuge' },
  { value: 'irmão',    key: 'fam.rel_irmao' },
  { value: 'irmã',     key: 'fam.rel_irma' },
  { value: 'avô',      key: 'fam.rel_avo_m' },
  { value: 'avó',      key: 'fam.rel_avo_f' },
  { value: 'outro',    key: 'fam.rel_outro' },
];
const REL_KEY = Object.fromEntries(REL_OPTIONS.map(o => [o.value, o.key]));

function calcAge(dob: string): number {
  return Math.floor((Date.now() - new Date(dob).getTime()) / (1000 * 60 * 60 * 24 * 365.25));
}

export default function FamilyPage() {
  const { t } = useT();
  const navigate = useNavigate();

  const [members, setMembers] = useState<FamilyMember[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  const [showForm, setShowForm] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [form, setForm] = useState<FormState>(BLANK_FORM);
  const [saving, setSaving] = useState(false);
  const [formError, setFormError] = useState('');

  const [deleteId, setDeleteId] = useState<string | null>(null);
  const [deleting, setDeleting] = useState(false);

  // ── Load ──────────────────────────────────────────────────────────────────

  useEffect(() => {
    api.get<FamilyMember[]>('/api/v1/family/me')
      .then(r => setMembers(r.data))
      .catch(() => setError(t('fam.err_load')))
      .finally(() => setLoading(false));
  }, []);

  // ── Form helpers ──────────────────────────────────────────────────────────

  const openAdd = () => { setEditId(null); setForm(BLANK_FORM); setFormError(''); setShowForm(true); };

  const openEdit = (m: FamilyMember) => {
    setEditId(m.id);
    setForm({
      full_name: m.full_name, relationship: m.relationship,
      date_of_birth: m.date_of_birth ?? '', gender: m.gender ?? '',
      phone: m.phone ?? '', email: m.email ?? '',
      is_minor: m.is_minor, emergency_contact: m.emergency_contact,
      notes: m.notes ?? '',
    });
    setFormError(''); setShowForm(true);
  };

  const closeForm = () => { setShowForm(false); setEditId(null); setForm(BLANK_FORM); };

  const f = (field: keyof FormState, value: string | boolean) =>
    setForm(prev => ({ ...prev, [field]: value }));

  const handleDobChange = (dob: string) => {
    f('date_of_birth', dob);
    if (dob) f('is_minor', calcAge(dob) < 16);
  };

  const handleSave = async () => {
    if (!form.full_name.trim()) { setFormError('O nome é obrigatório.'); return; }
    setSaving(true); setFormError('');
    const payload = {
      full_name: form.full_name.trim(),
      relationship: form.relationship,
      date_of_birth: form.date_of_birth || null,
      gender: form.gender || null,
      phone: form.phone.trim() || null,
      email: form.email.trim() || null,
      is_minor: form.is_minor,
      emergency_contact: form.emergency_contact,
      notes: form.notes.trim() || null,
    };
    try {
      if (editId) {
        const r = await api.patch<FamilyMember>(`/api/v1/family/${editId}`, payload);
        setMembers(prev => prev.map(m => m.id === editId ? r.data : m));
      } else {
        const r = await api.post<FamilyMember>('/api/v1/family', payload);
        setMembers(prev => [...prev, r.data]);
      }
      closeForm();
    } catch (err: any) {
      setFormError(err.response?.data?.detail || 'Erro ao guardar. Tente novamente.');
    }
    setSaving(false);
  };

  const confirmDelete = async (id: string) => {
    setDeleting(true);
    try {
      await api.delete(`/api/v1/family/${id}`);
      setMembers(prev => prev.filter(m => m.id !== id));
    } catch {
      setError(t('fam.err_remove'));
    }
    setDeleting(false); setDeleteId(null);
  };

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <>
      <div className="page-header">
        <h1>{t('family.title')}</h1>
        <p style={{ fontSize: '0.85rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
          Perfis de membros da família ou dependentes ligados à sua conta. Estes perfis não implicam cobertura médica automática.
        </p>
      </div>

      {error && (
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.25)', borderRadius: 10, padding: '0.75rem 1rem', marginBottom: '1rem', maxWidth: 700, color: '#dc2626', fontSize: '0.85rem' }}>
          <AlertCircle size={15} /> {error}
        </div>
      )}

      <div className="card" style={{ maxWidth: '700px' }}>
        {/* Header */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1.25rem', borderBottom: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Users size={20} style={{ color: 'var(--accent-teal)' }} />
            <div>
              <h3 style={{ fontSize: '0.95rem', fontWeight: 600, margin: 0 }}>{t('family.title')}</h3>
              <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', margin: '0.1rem 0 0' }}>
                {members.length} membro{members.length !== 1 ? 's' : ''} registado{members.length !== 1 ? 's' : ''}
              </p>
            </div>
          </div>
          {!showForm && (
            <button className="btn btn-sm btn-outline" onClick={openAdd}>
              <Plus size={14} /> {t('family.add')}
            </button>
          )}
        </div>

        <div style={{ padding: '1.25rem' }}>
          {loading && (
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', color: 'var(--text-muted)', fontSize: '0.85rem', padding: '1rem 0' }}>
              <Loader2 size={16} className="spin" /> A carregar…
            </div>
          )}

          {!loading && members.length === 0 && !showForm && (
            <div className="empty-state" style={{ padding: '3rem 2rem' }}>
              <div className="empty-state-icon"><Users size={28} style={{ color: 'var(--accent-teal)' }} /></div>
              <div className="empty-state-title">{t('family.none')}</div>
              <div className="empty-state-desc" style={{ maxWidth: 360, margin: '0 auto 1.25rem' }}>
                Adicione um membro da família ou dependente para poder realizar triagens em nome deles e acompanhar a sua saúde.
              </div>
              <button className="btn btn-primary btn-sm" onClick={openAdd}>
                <Plus size={14} /> {t('family.add')}
              </button>
            </div>
          )}

          {members.map(m => {
            const age = m.date_of_birth ? calcAge(m.date_of_birth) : null;
            const relLabel = REL_KEY[m.relationship] ? t(REL_KEY[m.relationship]) : m.relationship;
            return (
              <div key={m.id} className="profile-dependent-card" style={{ marginBottom: '0.75rem' }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap', marginBottom: '0.2rem' }}>
                    <span style={{ fontWeight: 700, fontSize: '0.92rem', color: 'var(--text-primary)' }}>{m.full_name}</span>
                    {m.is_minor && (
                      <span style={{ fontSize: '0.68rem', padding: '0.1rem 0.45rem', borderRadius: 20, background: 'rgba(234,179,8,0.15)', color: '#eab308', border: '1px solid rgba(234,179,8,0.3)', fontWeight: 600 }}>
                        Pediátrico
                      </span>
                    )}
                    {m.emergency_contact && (
                      <span style={{ fontSize: '0.68rem', padding: '0.1rem 0.45rem', borderRadius: 20, background: 'rgba(239,68,68,0.1)', color: '#ef4444', border: '1px solid rgba(239,68,68,0.25)', fontWeight: 600 }}>
                        Emergência
                      </span>
                    )}
                  </div>
                  <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                    <span>{relLabel}</span>
                    {age !== null && <span>• {age} anos</span>}
                    {m.gender && <span>• {m.gender}</span>}
                  </div>
                  {(m.phone || m.email) && (
                    <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '0.25rem', display: 'flex', gap: '0.75rem' }}>
                      {m.phone && <span><Phone size={10} style={{ verticalAlign: 'middle', marginRight: 3 }} />{m.phone}</span>}
                      {m.email && <span><Mail size={10} style={{ verticalAlign: 'middle', marginRight: 3 }} />{m.email}</span>}
                    </div>
                  )}
                  {m.notes && (
                    <div style={{ fontSize: '0.73rem', color: 'var(--text-muted)', marginTop: '0.2rem', fontStyle: 'italic' }}>{m.notes}</div>
                  )}
                </div>

                <div style={{ display: 'flex', gap: '0.4rem', flexShrink: 0 }}>
                  <button
                    className="btn btn-sm btn-primary"
                    onClick={() => navigate('/triage', { state: { dependent: { id: m.id, name: m.full_name, is_minor: m.is_minor } } })}
                  >
                    <Activity size={12} /> Triagem
                  </button>
                  <button className="btn btn-sm btn-outline" onClick={() => openEdit(m)}>
                    <Edit2 size={12} />
                  </button>
                  {deleteId === m.id ? (
                    <>
                      <button
                        className="btn btn-sm"
                        style={{ background: '#dc2626', color: '#fff', border: 'none' }}
                        onClick={() => confirmDelete(m.id)}
                        disabled={deleting}
                      >
                        {deleting ? <Loader2 size={12} className="spin" /> : <Trash2 size={12} />} Confirmar
                      </button>
                      <button className="btn btn-sm btn-outline" onClick={() => setDeleteId(null)}>
                        <X size={12} />
                      </button>
                    </>
                  ) : (
                    <button
                      className="btn btn-sm"
                      style={{ color: '#fca5a5', background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)' }}
                      onClick={() => setDeleteId(m.id)}
                    >
                      <Trash2 size={12} />
                    </button>
                  )}
                </div>
              </div>
            );
          })}

          {/* Add / Edit form */}
          {showForm && (
            <div className="profile-med-form" style={{ marginTop: members.length > 0 ? '1rem' : 0 }}>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '0.85rem' }}>
                <span style={{ fontWeight: 700, fontSize: '0.88rem', color: 'var(--text-primary)' }}>
                  {editId ? t('fam.edit_member') : t('fam.add_member')}
                </span>
                <button className="btn btn-sm btn-outline" onClick={closeForm}><X size={13} /></button>
              </div>

              {formError && (
                <div style={{ fontSize: '0.8rem', color: '#dc2626', background: 'rgba(239,68,68,0.06)', borderRadius: 8, padding: '0.5rem 0.75rem', marginBottom: '0.75rem' }}>
                  {formError}
                </div>
              )}

              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '0.75rem', marginBottom: '0.75rem' }}>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('fam.full_name')} *</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="text"
                    placeholder={t('fam.name_ph')} value={form.full_name}
                    onChange={e => f('full_name', e.target.value)} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('fam.relationship')} *</label>
                  <select className="form-select" style={{ fontSize: '0.85rem' }} value={form.relationship}
                    onChange={e => f('relationship', e.target.value)}>
                    {REL_OPTIONS.map(o => <option key={o.value} value={o.value}>{t(o.key)}</option>)}
                  </select>
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.75rem', marginBottom: '0.75rem' }}>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('fam.dob')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="date"
                    value={form.date_of_birth} onChange={e => handleDobChange(e.target.value)} />
                  {form.date_of_birth && (
                    <span style={{ fontSize: '0.72rem', color: form.is_minor ? '#eab308' : 'var(--text-muted)' }}>
                      {calcAge(form.date_of_birth)} {t('fam.years')}{form.is_minor ? ` — ${t('fam.pediatric')}` : ''}
                    </span>
                  )}
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('fam.gender')}</label>
                  <select className="form-select" style={{ fontSize: '0.85rem' }} value={form.gender}
                    onChange={e => f('gender', e.target.value)}>
                    <option value="">{t('fam.gender_none')}</option>
                    <option value="Masculino">{t('fam.gender_m')}</option>
                    <option value="Feminino">{t('fam.gender_f')}</option>
                    <option value="Outro">{t('fam.rel_outro')}</option>
                  </select>
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('fam.phone')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="tel"
                    placeholder="+244 ..." value={form.phone} onChange={e => f('phone', e.target.value)} />
                </div>
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem', marginBottom: '0.75rem' }}>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>E-mail</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="email"
                    placeholder="opcional" value={form.email} onChange={e => f('email', e.target.value)} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('fam.notes')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="text"
                    placeholder={t('fam.notes_ph')} value={form.notes} onChange={e => f('notes', e.target.value)} />
                </div>
              </div>

              <div style={{ display: 'flex', gap: '1.25rem', marginBottom: '0.85rem' }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.8rem', cursor: 'pointer' }}>
                  <input type="checkbox" checked={form.emergency_contact}
                    onChange={e => f('emergency_contact', e.target.checked)} />
                  Contacto de emergência
                </label>
                <label style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', fontSize: '0.8rem', cursor: 'pointer' }}>
                  <input type="checkbox" checked={form.is_minor}
                    onChange={e => f('is_minor', e.target.checked)} />
                  {t('fam.minor_pediatric')}
                </label>
              </div>

              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button className="btn btn-primary btn-sm" onClick={handleSave} disabled={saving}>
                  <Save size={13} /> {saving ? t('common.saving') : (editId ? t('fam.update') : t('family.save'))}
                </button>
                <button className="btn btn-outline btn-sm" onClick={closeForm}>{t('family.cancel_add')}</button>
              </div>
            </div>
          )}
        </div>
      </div>

      <div style={{ maxWidth: 700, marginTop: '1rem', padding: '0.75rem 1rem', background: 'rgba(6,182,212,0.05)', border: '1px solid rgba(6,182,212,0.2)', borderRadius: 10, fontSize: '0.78rem', color: 'var(--text-muted)', lineHeight: 1.6 }}>
        ℹ️ Os perfis de membros da família são geridos por si e ligados à sua conta. Podem ser seleccionados ao iniciar uma triagem em nome de outra pessoa. Não implicam automaticamente responsabilidade médica ou cobertura de seguro.
      </div>
    </>
  );
}

import { useState, type FormEvent } from 'react';
import { useNavigate, useLocation, Link } from 'react-router-dom';
import { Heart, Eye, EyeOff, Mail, Lock } from 'lucide-react';
import { useAuth } from '../AuthContext';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import kayaLogo from '/kaya-logo.svg';
import LanguageSelector from '../components/LanguageSelector';
import { apiErrorMessage } from '../utils/apiError';

export default function LoginPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const { t } = useT();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPw, setShowPw] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  /* Forgot-password modal */
  const [showForgot, setShowForgot] = useState(false);
  const [forgotEmail, setForgotEmail] = useState('');
  const [forgotMsg, setForgotMsg] = useState('');

  // MFA challenge state — set when /auth/login returns mfa_required.
  const [mfaToken, setMfaToken] = useState<string | null>(null);
  const [mfaCode, setMfaCode] = useState('');

  const finishLogin = (data: any) => {
    login(data);
    const role = data.user?.role;
    const from = (location.state as any)?.from?.pathname;
    const defaultDest = role === 'admin' ? '/admin' : role === 'doctor' ? '/doctor/dashboard' : role === 'nurse' ? '/nurse' : role === 'corporate_admin' ? '/corporate' : '/dashboard';
    navigate(from || defaultDest, { replace: true });
  };

  const handleLogin = async (e: FormEvent) => {
    e.preventDefault();
    setError(''); setSuccess(''); setLoading(true);
    try {
      const res = await api.post('/auth/login', { email, password });
      // MFA gate: password alone did not yield tokens.
      if (res.data.mfa_required) {
        setMfaToken(res.data.mfa_token);
        setLoading(false);
        return;
      }
      finishLogin(res.data);
    } catch (err: any) {
      setError(apiErrorMessage(err, t('login.invalid')));
    } finally { setLoading(false); }
  };

  const handleMfaChallenge = async (e: FormEvent) => {
    e.preventDefault();
    setError(''); setLoading(true);
    try {
      const res = await api.post('/auth/mfa/challenge', { mfa_token: mfaToken, code: mfaCode.trim() });
      finishLogin(res.data);
    } catch (err: any) {
      setError(apiErrorMessage(err, t('mfa.invalid_code')));
    } finally { setLoading(false); }
  };

  const handleForgotPw = async (e: FormEvent) => {
    e.preventDefault();
    setForgotMsg('');
    try {
      await api.post('/auth/forgot-password', { email: forgotEmail });
      setForgotMsg(t('login.forgot_msg'));
    } catch {
      setForgotMsg(t('login.forgot_msg'));
    }
  };

  const handleOAuth = (provider: 'google' | 'microsoft') => {
    window.location.href = `/auth/${provider}/login`;
  };

  return (
    <div className="auth-shell">
      {/* Language Selector */}
      <div style={{ position: 'absolute', top: '1rem', right: '1rem', zIndex: 100 }}>
        <LanguageSelector />
      </div>

      {/* Login Card */}
      <div className="auth-card">
        {/* Brand */}
        <div className="auth-brand">
          <img src={kayaLogo} alt="KAYA" style={{ width: 48, height: 48 }} />
          <span className="auth-brand-text">KAYA</span>
        </div>

        <h1 className="auth-title">{mfaToken ? t('mfa.challenge_title') : t('login.title')}</h1>
        <p className="auth-subtitle">{mfaToken ? t('mfa.challenge_subtitle') : t('login.subtitle')}</p>

        {/* MFA challenge step — shown after a correct password when MFA is on */}
        {mfaToken ? (
          <form onSubmit={handleMfaChallenge}>
            <div className="form-group">
              <label className="form-label">{t('mfa.code_label')}</label>
              <input
                className="form-input"
                inputMode="numeric"
                autoComplete="one-time-code"
                autoFocus
                value={mfaCode}
                onChange={e => setMfaCode(e.target.value)}
                placeholder="123456"
                style={{ letterSpacing: '0.3em', fontSize: '1.1rem', textAlign: 'center' }}
              />
              <div style={{ fontSize: '0.78rem', color: 'var(--text-muted)', marginTop: 6 }}>
                {t('mfa.code_help')}
              </div>
            </div>
            {error && <div className="auth-error">{error}</div>}
