import { useEffect, useState } from 'react';
import type { CSSProperties } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import { useT } from '../i18n/LanguageContext';
import { specialtyLabel } from '../constants/specialties';
import {
  Activity, AlertTriangle, CheckCircle2, ChevronRight, ClipboardList, Clock3,
  HeartPulse, HelpCircle, RefreshCw, Search, ShieldCheck, Timer, UserRound, X,
  Stethoscope, Video, Radio, Banknote,
} from 'lucide-react';
import KpiGrid from '../components/KpiGrid';

interface QueueItem {
  id: string; patient_id?: string; patient: string; specialty: string; risk_level?: string | null;
  chief_complaint?: string | null; created_at: string; wait_minutes?: number;
}
interface Dash {
  queue_count: number; urgent_count: number; triages_today: number;
  unclassified_count: number; waiting_over_30_count: number;
  average_wait_minutes: number; longest_wait_minutes: number; recent: QueueItem[];
}

const PREVIEW_DASH: Dash = {
  queue_count: 18,
  urgent_count: 3,
  triages_today: 24,
  average_wait_minutes: 16,
  longest_wait_minutes: 42,
  waiting_over_30_count: 4,
  unclassified_count: 2,
  recent: [
    { id: 'preview-1', patient_id: 'preview-patient', patient: 'Ana Manuel', specialty: 'general_medicine', risk_level: 'HIGH', chief_complaint: 'Febre e tosse persistente', created_at: '2026-07-30T09:20:00Z', wait_minutes: 42 },
    { id: 'preview-2', patient_id: 'preview-patient', patient: 'Paulo Costa', specialty: 'cardiology', risk_level: 'MEDIUM', chief_complaint: 'Desconforto no peito', created_at: '2026-07-30T09:42:00Z', wait_minutes: 28 },
    { id: 'preview-3', patient_id: 'preview-patient', patient: 'Teresa João', specialty: 'pediatrics', risk_level: null, chief_complaint: 'Dor abdominal', created_at: '2026-07-30T10:05:00Z', wait_minutes: 11 },
  ],
};

function riskBadge(level?: string | null) {
  switch ((level || '').toUpperCase()) {
    case 'URGENT': return { label: 'Urgente', color: '#7c3aed', bg: 'rgba(124,58,237,0.12)' };
    case 'HIGH': return { label: 'Alto', color: '#dc2626', bg: 'rgba(239,68,68,0.12)' };
    case 'MEDIUM': return { label: 'Médio', color: '#d97706', bg: 'rgba(234,179,8,0.12)' };
    case 'LOW': return { label: 'Baixo', color: '#059669', bg: 'rgba(16,185,129,0.12)' };
    default: return { label: '—', color: '#64748b', bg: 'rgba(100,116,139,0.1)' };
  }
}

export default function NurseDashboardPage({ preview = false }: { preview?: boolean }) {
  const { t } = useT();
  const navigate = useNavigate();
  const [dash, setDash] = useState<Dash | null>(preview ? PREVIEW_DASH : null);
  const [loading, setLoading] = useState(!preview);
  const [refreshing, setRefreshing] = useState(false);
  const [query, setQuery] = useState('');
  const [riskFilter, setRiskFilter] = useState<'all' | 'priority' | 'unclassified'>('all');
  const [selected, setSelected] = useState<QueueItem | null>(null);

  const loadDashboard = () => {
    if (preview) {
      setDash(PREVIEW_DASH);
      setRefreshing(false);
      return;
    }
    setRefreshing(true);
    api.get('/api/v1/nurse/dashboard')
      .then(r => setDash(r.data))
      .catch(() => {})
      .finally(() => { setLoading(false); setRefreshing(false); });
  };

  useEffect(() => { loadDashboard(); }, [preview]);

  if (loading) return <div className="page-loading"><div className="spinner" /></div>;

  const waitMinutes = (item: QueueItem) => item.wait_minutes ?? Math.max(0, Math.floor((Date.now() - new Date(item.created_at).getTime()) / 60000));
  const sla = dash?.queue_count ? Math.max(0, Math.round(((dash.queue_count - dash.waiting_over_30_count) / dash.queue_count) * 100)) : 100;
  const kpis = dash ? [
    { id: 'queue', label: t('nurse.kpi_queue'), value: dash.queue_count, helper: t('nurse.kpi_queue_help'), icon: <ClipboardList size={18} />, color: '#0d9488' },
    { id: 'urgent', label: t('nurse.kpi_urgent'), value: dash.urgent_count, helper: t('nurse.kpi_urgent_help'), icon: <AlertTriangle size={18} />, color: '#dc2626', tone: dash.urgent_count > 0 ? 'attention' as const : 'default' as const },
    { id: 'triages', label: t('nurse.kpi_triages'), value: dash.triages_today, helper: t('nurse.kpi_triages_help'), icon: <Activity size={18} />, color: '#2563eb', tone: 'positive' as const },
    { id: 'wait', label: t('nurse.kpi_wait'), value: `${dash.average_wait_minutes} min`, helper: t('nurse.kpi_wait_help'), icon: <Clock3 size={18} />, color: '#7c3aed' },
    { id: 'late', label: t('nurse.kpi_over_30'), value: dash.waiting_over_30_count, helper: t('nurse.kpi_over_30_help'), icon: <Timer size={18} />, color: '#ea580c', tone: dash.waiting_over_30_count > 0 ? 'attention' as const : 'default' as const },
    { id: 'unclassified', label: t('nurse.kpi_unclassified'), value: dash.unclassified_count, helper: t('nurse.kpi_unclassified_help'), icon: <HelpCircle size={18} />, color: '#64748b' },
  ] : [];

  const filteredItems = (dash?.recent || []).filter(item => {
    const matchesSearch = `${item.patient} ${item.chief_complaint || ''} ${item.specialty}`.toLowerCase().includes(query.toLowerCase());
    const risk = (item.risk_level || '').toUpperCase();
    const matchesRisk = riskFilter === 'all'
      || (riskFilter === 'priority' && ['URGENT', 'HIGH'].includes(risk))
      || (riskFilter === 'unclassified' && !risk);
    return matchesSearch && matchesRisk;
  });

  return (
    <div className="nurse-dashboard">
      <section className="nurse-hero">
        <div>
          <div className="nurse-hero__meta">
            {preview && <span className="nurse-preview-chip">{t('nurse.preview')}</span>}
            <span className="nurse-shift-chip"><span /> {t('nurse.shift_active')}</span>
          </div>
          <h1><HeartPulse size={25} /> {t('nurse.dashboard')}</h1>
          <p>{t('nurse.workspace_desc')}</p>
        </div>
        <div className="nurse-hero__actions">
          <span>{t('nurse.updated_now')}</span>
          <button type="button" onClick={loadDashboard} disabled={refreshing}>
            <RefreshCw size={16} className={refreshing ? 'spin' : ''} /> {t('nurse.refresh')}
          </button>
        </div>
      </section>

      {(dash?.urgent_count || dash?.unclassified_count) ? (
        <section className="nurse-alerts" aria-label={t('nurse.attention')}>
          {!!dash?.urgent_count && (
            <div className="nurse-alert nurse-alert--danger">
              <span className="nurse-alert__icon"><AlertTriangle size={19} /></span>
              <div><strong>{dash.urgent_count} {t('nurse.priority_patients')}</strong><span>{t('nurse.priority_action')}</span></div>
              <ChevronRight size={18} />
            </div>
          )}
          {!!dash?.unclassified_count && (
            <div className="nurse-alert nurse-alert--warning">
              <span className="nurse-alert__icon"><HelpCircle size={19} /></span>
              <div><strong>{dash.unclassified_count} {t('nurse.unclassified_patients')}</strong><span>{t('nurse.unclassified_action')}</span></div>
              <ChevronRight size={18} />
            </div>
          )}
        </section>
      ) : null}

      <KpiGrid items={kpis} ariaLabel={t('kpi.summary')} />

      <section className="nurse-ecosystem" aria-label="Operações clínicas">
        <header>
          <div><span>ECOSSISTEMA CLÍNICO</span><h2>Da triagem à continuidade dos cuidados</h2></div>
          <p>A enfermagem prepara, monitoriza e escala; o médico diagnostica e prescreve.</p>
        </header>
        <div>
          <button type="button" onClick={() => navigate(preview ? '/preview/clinician/patient' : filteredItems[0]?.patient_id ? `/clinician/patients/${filteredItems[0].patient_id}` : '/nurse')}>
            <span className="teal"><Stethoscope size={18} /></span><strong>Encaminhar ao médico</strong><small>Prioridade + passagem clínica + Patient 360</small><ChevronRight size={16} />
          </button>
          <button type="button" onClick={() => navigate(preview ? '/preview/clinician/patient' : filteredItems[0]?.patient_id ? `/clinician/patients/${filteredItems[0].patient_id}` : '/nurse')}>
            <span className="blue"><Video size={18} /></span><strong>Teleconsulta assistida</strong><small>Preparar paciente, sinais vitais e sala clínica</small><ChevronRight size={16} />
          </button>
          <button type="button" onClick={() => navigate(preview ? '/preview/clinician/patient' : filteredItems[0]?.patient_id ? `/clinician/patients/${filteredItems[0].patient_id}` : '/nurse')}>
            <span className="purple"><Radio size={18} /></span><strong>Monitorização remota</strong><small>RENPHO, Apple Health, Health Connect e alertas</small><ChevronRight size={16} />
          </button>
          <button type="button" onClick={() => navigate(preview ? '/preview/clinician/patient' : '/settings')}>
            <span className="amber"><Banknote size={18} /></span><strong>Atividade remunerada</strong><small>Eventos auditados e divisão profissional/plataforma</small><ChevronRight size={16} />
          </button>
        </div>
      </section>

      <section className="nurse-workspace-grid">
        <div className="nurse-queue-card">
          <div className="nurse-card-header">
            <div>
              <h2>{t('nurse.live_queue')}</h2>
              <p>{t('nurse.live_queue_desc')}</p>
            </div>
            <span className="nurse-count-badge">{dash?.queue_count || 0}</span>
          </div>
          <div className="nurse-queue-toolbar">
            <label className="nurse-search">
              <Search size={16} />
              <input value={query} onChange={e => setQuery(e.target.value)} placeholder={t('nurse.search')} />
            </label>
            <div className="nurse-filters" role="group" aria-label={t('nurse.filter')}>
              {([
                ['all', t('nurse.filter_all')],
                ['priority', t('nurse.filter_priority')],
                ['unclassified', t('nurse.filter_unclassified')],
              ] as const).map(([value, label]) => (
                <button type="button" key={value} className={riskFilter === value ? 'active' : ''} onClick={() => setRiskFilter(value)}>{label}</button>
              ))}
            </div>
          </div>

          {filteredItems.length === 0 ? (
            <div className="nurse-empty"><CheckCircle2 size={28} /><strong>{t('nurse.empty')}</strong></div>
          ) : (
            <div className="table-container nurse-table-wrap">
              <table className="nurse-queue-table">
                <thead><tr><th>#</th><th>{t('table.patient')}</th><th>{t('nurse.reason')}</th><th>{t('table.risk')}</th><th>{t('nurse.wait')}</th><th /></tr></thead>
                <tbody>
                  {filteredItems.map((i, index) => {
                  const r = riskBadge(i.risk_level);
                  const minutes = waitMinutes(i);
                  const initials = i.patient.split(' ').slice(0, 2).map(part => part[0]).join('');
                  return (
                    <tr key={i.id}>
                      <td><span className="nurse-priority-number">{index + 1}</span></td>
                      <td>
                        <div className="nurse-patient-cell">
                          <span className="nurse-patient-avatar">{initials}</span>
                          <span><strong>{i.patient}</strong><small>{specialtyLabel(i.specialty, t)}</small></span>
                        </div>
                      </td>
                      <td><span className="nurse-complaint">{i.chief_complaint || '—'}</span></td>
                      <td><span className="nurse-risk-badge" style={{ background: r.bg, color: r.color }}>{r.label}</span></td>
                      <td><span className={`nurse-wait ${minutes >= 30 ? 'late' : ''}`}><Clock3 size={14} /> {minutes} min</span></td>
                      <td>
                        <button
                          className="nurse-open-patient"
                          type="button"
                          onClick={() => preview ? navigate('/preview/clinician/patient') : i.patient_id ? navigate(`/clinician/patients/${i.patient_id}`) : setSelected(i)}
                        >
                          {t('nurse.open')}
                        </button>
                      </td>
                    </tr>
                  );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>

        <aside className="nurse-operations">
          {selected ? (
            <div className="nurse-patient-panel">
              <button className="nurse-panel-close" type="button" onClick={() => setSelected(null)} aria-label={t('common.close')}><X size={17} /></button>
              <div className="nurse-panel-avatar"><UserRound size={23} /></div>
              <span className="nurse-panel-eyebrow">{t('nurse.patient_detail')}</span>
              <h3>{selected.patient}</h3>
              <dl>
                <div><dt>{t('table.specialty')}</dt><dd>{specialtyLabel(selected.specialty, t)}</dd></div>
                <div><dt>{t('nurse.reason')}</dt><dd>{selected.chief_complaint || '—'}</dd></div>
                <div><dt>{t('table.risk')}</dt><dd>{riskBadge(selected.risk_level).label}</dd></div>
                <div><dt>{t('nurse.wait')}</dt><dd>{waitMinutes(selected)} min</dd></div>
              </dl>
              <button type="button" className="nurse-primary-action">{t('nurse.review_triage')} <ChevronRight size={16} /></button>
            </div>
          ) : (
            <>
              <div className="nurse-card-header">
                <div><h2>{t('nurse.shift_summary')}</h2><p>{t('nurse.shift_summary_desc')}</p></div>
              </div>
              <div className="nurse-sla">
                <div className="nurse-sla__ring" style={{ '--progress': `${sla * 3.6}deg` } as CSSProperties}>
                  <span><strong>{sla}%</strong><small>SLA</small></span>
                </div>
                <div><strong>{t('nurse.response_target')}</strong><span>{t('nurse.response_target_desc')}</span></div>
              </div>
              <div className="nurse-operation-list">
                <div><span className="nurse-op-icon nurse-op-icon--green"><ShieldCheck size={17} /></span><span><strong>{dash?.triages_today || 0}</strong><small>{t('nurse.completed_today')}</small></span></div>
                <div><span className="nurse-op-icon nurse-op-icon--orange"><Timer size={17} /></span><span><strong>{dash?.longest_wait_minutes || 0} min</strong><small>{t('nurse.longest_wait')}</small></span></div>
                <div><span className="nurse-op-icon nurse-op-icon--blue"><Activity size={17} /></span><span><strong>{dash?.queue_count ? Math.round(dash.triages_today / Math.max(1, dash.queue_count) * 10) / 10 : 0}×</strong><small>{t('nurse.flow_ratio')}</small></span></div>
              </div>
              <div className="nurse-priority-note">
                <AlertTriangle size={18} />
                <div><strong>{t('nurse.next_priority')}</strong><span>{dash?.urgent_count ? t('nurse.next_priority_urgent') : t('nurse.next_priority_clear')}</span></div>
              </div>
            </>
          )}
        </aside>
      </section>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { ArrowLeft, ArrowRight, Building2, CheckCircle2, Loader2, MapPin, Plus, Trash2 } from 'lucide-react';
import api from '../api';
import DocumentUpload from '../components/DocumentUpload';
import { useT } from '../i18n/LanguageContext';

const inputStyle: React.CSSProperties = {
  width: '100%', padding: '0.65rem 0.8rem', borderRadius: 8,
  border: '1px solid var(--border)', background: 'var(--bg-primary)',
  fontSize: '0.9rem', color: 'var(--text-primary)',
};

interface OrgProfile {
  id: string;
  status: string;
  locations: Array<{ id: string; name: string; city?: string }>;
  documents: Array<{ id: string; kind: string; filename: string }>;
}

export default function OrganisationOnboardingPage() {
  const { t } = useT();
  const navigate = useNavigate();
  const [params] = useSearchParams();
  const presetType = params.get('type') === 'pharmacy' ? 'pharmacy_org' : 'clinic';

  const [step, setStep] = useState(1);
  const [org, setOrg] = useState<OrgProfile | null>(null);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [done, setDone] = useState(false);
  const TOTAL = 5;

  // Step 1 fields
  const [orgType, setOrgType] = useState(presetType);
  const [legalName, setLegalName] = useState('');
  const [tradingName, setTradingName] = useState('');
  const [regNumber, setRegNumber] = useState('');
  const [taxNumber, setTaxNumber] = useState('');
  const [genEmail, setGenEmail] = useState('');
  const [genPhone, setGenPhone] = useState('');
  const [rep, setRep] = useState('');
  const [respPro, setRespPro] = useState('');
  // Step 4 fields
  const [bankHolder, setBankHolder] = useState('');
  const [iban, setIban] = useState('');
  const [plan, setPlan] = useState('standard');
  const [hasApi, setHasApi] = useState(false);
  const [csvImport, setCsvImport] = useState(false);
  // Step 3 location entry
  const [locName, setLocName] = useState('');
  const [locCity, setLocCity] = useState('');

  // Load any existing draft profile on mount.
  useEffect(() => {
    api.get('/api/v1/organisations/me')
      .then(r => {
        setOrg(r.data);
        setOrgType(r.data.org_type || presetType);
        setLegalName(r.data.legal_name || '');
        setTradingName(r.data.trading_name || '');
        setRegNumber(r.data.registration_number || '');
        setTaxNumber(r.data.tax_number || '');
        setGenEmail(r.data.general_email || '');
        setGenPhone(r.data.general_phone || '');
        setRep(r.data.representative_name || '');
        setRespPro(r.data.responsible_professional || '');
      })
      .catch(() => { /* no draft yet — fine */ });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const saveProfile = async (): Promise<boolean> => {
    setBusy(true); setError('');
    try {
      const r = await api.post('/api/v1/organisations', {
        org_type: orgType,
        legal_name: legalName,
        trading_name: tradingName || null,
        registration_number: regNumber,
        tax_number: taxNumber || null,
        country: 'AO',
        general_email: genEmail || null,
        general_phone: genPhone || null,
        representative_name: rep || null,
        responsible_professional: respPro || null,
        bank_holder_name: bankHolder || null,
        iban: iban || null,
        subscription_plan: plan,
        integration: { has_api: hasApi, csv_import: csvImport },
      });
      setOrg(r.data);
      return true;
    } catch (e: any) {
      setError(e.response?.data?.detail || 'Erro ao guardar.');
      return false;
    } finally { setBusy(false); }
  };

  const refresh = async () => {
    const r = await api.get('/api/v1/organisations/me');
    setOrg(r.data);
  };

  const addLocation = async () => {
    if (!locName.trim()) return;
    setBusy(true); setError('');
    try {
      const r = await api.post('/api/v1/organisations/me/locations', { name: locName.trim(), city: locCity.trim() || null });
      setOrg(r.data);
      setLocName(''); setLocCity('');
    } catch (e: any) {
      setError(e.response?.data?.detail || 'Erro ao adicionar localização.');
    } finally { setBusy(false); }
  };

  const removeLocation = async (id: string) => {
    const r = await api.delete(`/api/v1/organisations/me/locations/${id}`);
    setOrg(r.data);
  };

  const next = async () => {
    setError('');
    if (step === 1) {
      if (!legalName.trim() || !regNumber.trim()) { setError('Preencha o nome legal e o número de registo.'); return; }
      if (!(await saveProfile())) return;
    }
    if (step === 4) {
      if (!(await saveProfile())) return;
    }
    if (step < TOTAL) { setStep(step + 1); window.scrollTo({ top: 0, behavior: 'smooth' }); }
  };

  const submit = async () => {
    setBusy(true); setError('');
    try {
      await saveProfile();
      await api.post('/api/v1/organisations/me/submit');
      setDone(true);
    } catch (e: any) {
      const d = e.response?.data?.detail;
      setError(typeof d === 'object' ? 'Precisa de pelo menos um documento e uma localização.' : (d || 'Erro ao submeter.'));
    } finally { setBusy(false); }
  };

  if (done) {
    return (
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2rem 1rem' }}>
        <div className="card" style={{ padding: '2rem 1.75rem', maxWidth: 460, textAlign: 'center' }}>
          <CheckCircle2 size={56} style={{ color: '#22c55e', marginBottom: '0.75rem' }} />
          <h1 style={{ margin: '0 0 0.5rem', fontSize: '1.3rem', fontWeight: 800 }}>{t('org.done_title')}</h1>
          <p style={{ margin: '0 0 1.5rem', color: 'var(--text-secondary)' }}>{t('org.done_sub')}</p>
          <button className="btn btn-primary" onClick={() => navigate('/dashboard')}>{t('org.go_dashboard')}</button>
        </div>
      </div>
    );
  }

  const progressPct = Math.round((step / TOTAL) * 100);

  return (
    <div style={{ minHeight: '100vh', background: 'var(--bg-secondary)', paddingTop: '2rem' }}>
      <div style={{ maxWidth: 720, margin: '0 auto', padding: '0 1.25rem 4rem' }}>
        {/* Progress */}
        <div style={{ marginBottom: '1.5rem' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '0.8rem', color: 'var(--text-muted)', marginBottom: '0.4rem' }}>
            <span>{t('org.step')} {step} {t('org.of')} {TOTAL}</span>
            <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}><Building2 size={13} /> {t('org.title')}</span>
          </div>
          <div style={{ height: 6, background: 'var(--bg-hover)', borderRadius: 999, overflow: 'hidden' }}>
            <div style={{ width: `${progressPct}%`, height: '100%', background: 'var(--brand-primary)', transition: 'width 240ms ease' }} />
          </div>
        </div>

        <div className="card" style={{ padding: '1.5rem', marginBottom: '1.25rem' }}>
          {/* Step 1 — details */}
          {step === 1 && (
            <>
              <h2 style={{ margin: '0 0 1rem', fontSize: '1.15rem', fontWeight: 800 }}>{t('org.s1_title')}</h2>
              <label style={{ display: 'block', marginBottom: '1rem' }}>
                <div style={{ fontSize: '0.85rem', fontWeight: 600, marginBottom: '0.35rem' }}>{t('org.type')}</div>
                <select value={orgType} onChange={e => setOrgType(e.target.value)} style={inputStyle}>
                  <option value="clinic">{t('org.type_clinic')}</option>
                  <option value="laboratory">{t('org.type_lab')}</option>
                  <option value="pharmacy_org">{t('org.type_pharmacy')}</option>
                  <option value="health_org">{t('org.type_health_org')}</option>
                </select>
              </label>
              <Field label={t('org.legal_name')} required><input style={inputStyle} value={legalName} onChange={e => setLegalName(e.target.value)} /></Field>
              <Field label={t('org.trading_name')}><input style={inputStyle} value={tradingName} onChange={e => setTradingName(e.target.value)} /></Field>
              <Field label={t('org.reg_number')} required><input style={inputStyle} value={regNumber} onChange={e => setRegNumber(e.target.value)} /></Field>
              <Field label={t('org.tax_number')}><input style={inputStyle} value={taxNumber} onChange={e => setTaxNumber(e.target.value)} /></Field>
              <Field label={t('org.gen_email')}><input style={inputStyle} type="email" value={genEmail} onChange={e => setGenEmail(e.target.value)} /></Field>
              <Field label={t('org.gen_phone')}><input style={inputStyle} value={genPhone} onChange={e => setGenPhone(e.target.value)} /></Field>
              <Field label={t('org.rep')}><input style={inputStyle} value={rep} onChange={e => setRep(e.target.value)} /></Field>
              <Field label={t('org.resp_pro')}><input style={inputStyle} value={respPro} onChange={e => setRespPro(e.target.value)} /></Field>
            </>
          )}

          {/* Step 2 — documents */}
          {step === 2 && (
            <>
              <h2 style={{ margin: '0 0 0.25rem', fontSize: '1.15rem', fontWeight: 800 }}>{t('org.s2_title')}</h2>
              <p style={{ marginTop: 0, color: 'var(--text-secondary)', fontSize: '0.85rem' }}>{t('org.s2_sub')}</p>
              <DocumentUpload kind="business_registration" label="Registo comercial" onUploaded={refresh}
                currentFilename={org?.documents.find(d => d.kind === 'business_registration')?.filename} />
              <DocumentUpload kind="operating_licence" label="Licença de funcionamento" onUploaded={refresh}
                currentFilename={org?.documents.find(d => d.kind === 'operating_licence')?.filename} />
              <DocumentUpload kind="healthcare_licence" label="Licença sanitária" onUploaded={refresh}
                currentFilename={org?.documents.find(d => d.kind === 'healthcare_licence')?.filename} />
              {orgType === 'pharmacy_org' && (
                <DocumentUpload kind="pharmacy_licence" label="Licença de farmácia" onUploaded={refresh}
                  currentFilename={org?.documents.find(d => d.kind === 'pharmacy_licence')?.filename} />
              )}
              {orgType === 'laboratory' && (
                <DocumentUpload kind="lab_accreditation" label="Acreditação laboratorial" onUploaded={refresh}
                  currentFilename={org?.documents.find(d => d.kind === 'lab_accreditation')?.filename} />
              )}
              <DocumentUpload kind="insurance" label="Seguro" onUploaded={refresh}
                currentFilename={org?.documents.find(d => d.kind === 'insurance')?.filename} />
            </>
          )}

          {/* Step 3 — locations */}
          {step === 3 && (
            <>
              <h2 style={{ margin: '0 0 0.25rem', fontSize: '1.15rem', fontWeight: 800 }}>{t('org.s3_title')}</h2>
              <p style={{ marginTop: 0, color: 'var(--text-secondary)', fontSize: '0.85rem' }}>{t('org.s3_sub')}</p>
              {(org?.locations || []).map(loc => (
                <div key={loc.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0.6rem 0.8rem', border: '1px solid var(--border)', borderRadius: 8, marginBottom: 8 }}>
                  <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8, fontSize: '0.88rem' }}>
                    <MapPin size={15} style={{ color: 'var(--brand-primary)' }} /> <strong>{loc.name}</strong>{loc.city ? ` · ${loc.city}` : ''}
                  </span>
                  <button className="btn btn-ghost btn-sm" onClick={() => removeLocation(loc.id)} style={{ color: '#b91c1c' }}>
                    <Trash2 size={14} /> {t('org.remove')}
                  </button>
                </div>
              ))}
              <div style={{ display: 'flex', gap: 8, marginTop: 8, flexWrap: 'wrap' }}>
                <input style={{ ...inputStyle, flex: 2, minWidth: 160 }} placeholder={t('org.loc_name')} value={locName} onChange={e => setLocName(e.target.value)} />
                <input style={{ ...inputStyle, flex: 1, minWidth: 120 }} placeholder={t('org.loc_city')} value={locCity} onChange={e => setLocCity(e.target.value)} />
                <button className="btn btn-primary btn-sm" onClick={addLocation} disabled={busy || !locName.trim()} style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                  <Plus size={14} /> {t('org.add_location')}
                </button>
              </div>
              <div style={{ marginTop: 8, fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                {(org?.locations || []).length} {t('org.loc_added')}
              </div>
            </>
          )}

          {/* Step 4 — banking + integration */}
          {step === 4 && (
            <>
              <h2 style={{ margin: '0 0 1rem', fontSize: '1.15rem', fontWeight: 800 }}>{t('org.s4_title')}</h2>
              <Field label={t('org.bank_holder')}><input style={inputStyle} value={bankHolder} onChange={e => setBankHolder(e.target.value)} /></Field>
              <Field label={t('org.iban')} hint={t('org.iban_hint')}><input style={inputStyle} value={iban} onChange={e => setIban(e.target.value)} placeholder="AO06 …" /></Field>
              <Field label={t('org.plan')}>
                <select style={inputStyle} value={plan} onChange={e => setPlan(e.target.value)}>
                  <option value="standard">Standard</option>
                  <option value="premium">Premium</option>
                  <option value="enterprise">Enterprise</option>
                </select>
              </Field>
              <label style={{ display: 'flex', gap: 8, alignItems: 'center', padding: '0.5rem 0', cursor: 'pointer' }}>
                <input type="checkbox" checked={hasApi} onChange={e => setHasApi(e.target.checked)} style={{ accentColor: 'var(--brand-primary)' }} />
                <span style={{ fontSize: '0.88rem' }}>{t('org.has_api')}</span>
              </label>
              <label style={{ display: 'flex', gap: 8, alignItems: 'center', padding: '0.5rem 0', cursor: 'pointer' }}>
                <input type="checkbox" checked={csvImport} onChange={e => setCsvImport(e.target.checked)} style={{ accentColor: 'var(--brand-primary)' }} />
                <span style={{ fontSize: '0.88rem' }}>{t('org.csv_import')}</span>
              </label>
            </>
          )}

          {/* Step 5 — review */}
          {step === 5 && (
            <>
              <h2 style={{ margin: '0 0 0.5rem', fontSize: '1.15rem', fontWeight: 800 }}>{t('org.s5_title')}</h2>
              <p style={{ marginTop: 0, color: 'var(--text-secondary)', fontSize: '0.85rem', lineHeight: 1.6 }}>{t('org.review_note')}</p>
              <ul style={{ fontSize: '0.88rem', color: 'var(--text-secondary)', lineHeight: 1.8 }}>
                <li><strong>{legalName}</strong> ({orgType})</li>
                <li>{(org?.documents || []).length} documento(s)</li>
                <li>{(org?.locations || []).length} localização(ões)</li>
              </ul>
            </>
          )}

          {error && (
            <div role="alert" style={{ marginTop: '1rem', padding: '0.7rem 0.9rem', borderRadius: 8, background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.25)', color: '#b91c1c', fontSize: '0.85rem' }}>
              {error}
            </div>
          )}
        </div>

        {/* Actions */}
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: '0.75rem' }}>
          <button className="btn btn-ghost" onClick={() => setStep(Math.max(1, step - 1))} disabled={step === 1 || busy}
            style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
            <ArrowLeft size={16} /> {t('org.back')}
          </button>
          {step < TOTAL ? (
            <button className="btn btn-primary" onClick={next} disabled={busy} style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
              {busy ? <><Loader2 size={16} className="spin" /> {t('org.saving')}</> : <>{t('org.next')} <ArrowRight size={16} /></>}
            </button>
          ) : (
            <button className="btn btn-primary" onClick={submit} disabled={busy} style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
              {busy ? <><Loader2 size={16} className="spin" /> {t('org.saving')}</> : <>{t('org.submit')} <CheckCircle2 size={16} /></>}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

function Field({ label, required, hint, children }: { label: string; required?: boolean; hint?: string; children: React.ReactNode }) {
  return (
    <label style={{ display: 'block', marginBottom: '1rem' }}>
      <div style={{ fontSize: '0.85rem', fontWeight: 600, marginBottom: '0.35rem' }}>
        {label}{required && <span style={{ color: '#dc2626', marginLeft: 4 }}>*</span>}
      </div>
      {children}
      {hint && <div style={{ marginTop: '0.35rem', fontSize: '0.78rem', color: 'var(--text-muted)' }}>{hint}</div>}
    </label>
  );
}

import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import {
  Pill, CheckCircle2, X, Clock, ChevronDown, ChevronUp,
  AlertTriangle, Loader2, Send, ArrowLeft,
} from 'lucide-react';
import api from '../api';
import { useT, type Lang } from '../i18n/LanguageContext';

const LOCALES: Record<Lang, string> = { pt: 'pt-PT', en: 'en-GB', fr: 'fr-FR', es: 'es-ES', zh: 'zh-CN' };

interface Doctor {
  id: string;
  display_name: string;
  title?: string;
  specialization?: string;
}

interface RxRequest {
  id: string;
  medication_name: string;
  dose?: string;
  frequency?: string;
  reason?: string;
  status: string;
  doctor_note?: string;
  adjusted_dose?: string;
  adjusted_frequency?: string;
  created_at: string;
  decided_at?: string;
}

const STATUS_CONFIG: Record<string, { key: string; color: string; bg: string; icon: React.ReactNode }> = {
  pending:           { key: 'ppr.st_pending', color: '#d97706', bg: 'rgba(234,179,8,0.1)',    icon: <Clock size={13} /> },
  approve:           { key: 'ppr.st_approve', color: '#059669', bg: 'rgba(16,185,129,0.1)',   icon: <CheckCircle2 size={13} /> },
  adjust:            { key: 'ppr.st_adjust',  color: '#3b82f6', bg: 'rgba(59,130,246,0.1)',   icon: <CheckCircle2 size={13} /> },
  consult_requested: { key: 'ppr.st_consult', color: '#8b5cf6', bg: 'rgba(139,92,246,0.1)',   icon: <Clock size={13} /> },
  exams_requested:   { key: 'ppr.st_exams',   color: '#f59e0b', bg: 'rgba(245,158,11,0.1)',   icon: <Clock size={13} /> },
  reject:            { key: 'ppr.st_reject',  color: '#dc2626', bg: 'rgba(239,68,68,0.1)',    icon: <X size={13} /> },
};

export default function PatientPrescriptionRequestPage() {
  const { t, lang } = useT();
  const locale = LOCALES[lang] || 'pt-PT';
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();

  // Pre-fill from query params (coming from SelfCare "Renovar" button)
  const initMed  = searchParams.get('med')  ?? '';
  const initDose = searchParams.get('dose') ?? '';
  const initFreq = searchParams.get('freq') ?? '';

  // Form state
  const [medName, setMedName]     = useState(initMed);
  const [dose, setDose]           = useState(initDose);
  const [frequency, setFrequency] = useState(initFreq);
  const [reason, setReason]       = useState('');
  const [doctorId, setDoctorId]   = useState('');
  const [doctors, setDoctors]     = useState<Doctor[]>([]);
  const [loadingDocs, setLoadingDocs] = useState(true);

  // Submissions
  const [submitting, setSubmitting]   = useState(false);
  const [successMsg, setSuccessMsg]   = useState('');
  const [errorMsg, setErrorMsg]       = useState('');

  // History
  const [history, setHistory]         = useState<RxRequest[]>([]);
  const [loadingHist, setLoadingHist] = useState(true);
  const [expandedId, setExpandedId]   = useState<string | null>(null);

  // Show form toggle
  const [showForm, setShowForm]       = useState(!!initMed);

  useEffect(() => {
    api.get('/api/v1/doctors').then(r => {
      setDoctors(r.data);
      if (r.data.length === 1) setDoctorId(r.data[0].id);
    }).catch(() => {}).finally(() => setLoadingDocs(false));

    api.get<RxRequest[]>('/api/v1/prescription-requests')
      .then(r => setHistory(r.data))
      .catch(() => {})
      .finally(() => setLoadingHist(false));
  }, []);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!medName.trim() || !doctorId) return;
    setSubmitting(true); setErrorMsg(''); setSuccessMsg('');
    try {
      const { data } = await api.post<RxRequest>('/api/v1/prescription-requests', {
        doctor_id: doctorId,
        medication_name: medName.trim(),
        dose: dose.trim() || undefined,
        frequency: frequency.trim() || undefined,
        reason: reason.trim() || undefined,
      });
      setHistory(h => [data, ...h]);
      setSuccessMsg(t('ppr.success'));
      setMedName(''); setDose(''); setFrequency(''); setReason(''); setDoctorId('');
      setShowForm(false);
    } catch (err: any) {
      setErrorMsg(err?.response?.data?.detail ?? t('ppr.error'));
    } finally {
      setSubmitting(false);
    }
  };

  const pending = history.filter(r => r.status === 'pending').length;

  return (
    <div style={{ maxWidth: 680, margin: '0 auto', padding: '1.5rem 1.25rem 4rem' }}>

      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', marginBottom: '1.5rem' }}>
        <button onClick={() => navigate(-1)} style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)', display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.83rem', padding: '0.35rem 0.6rem', borderRadius: '8px' }}>
          <ArrowLeft size={16} />
        </button>
        <div style={{ flex: 1 }}>
          <h1 style={{ fontSize: '1.2rem', fontWeight: 800, margin: 0, display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Pill size={20} style={{ color: 'var(--brand-primary)' }} /> {t('ppr.title')}
          </h1>
          <p style={{ color: 'var(--text-secondary)', margin: 0, fontSize: '0.82rem' }}>
            {t('ppr.subtitle')}
          </p>
        </div>
        <button
          onClick={() => setShowForm(f => !f)}
          style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', padding: '0.5rem 1rem', borderRadius: '10px', background: 'var(--brand-primary)', color: '#fff', border: 'none', fontWeight: 700, fontSize: '0.82rem', cursor: 'pointer' }}
        >
          <Send size={14} /> {t('ppr.new_request')}
        </button>
      </div>

      {/* Pending badge */}
      {pending > 0 && (
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', padding: '0.65rem 1rem', borderRadius: '10px', background: 'rgba(234,179,8,0.08)', border: '1px solid rgba(234,179,8,0.25)', marginBottom: '1.25rem', fontSize: '0.82rem', color: '#d97706', fontWeight: 600 }}>
          <Clock size={15} /> {pending} {pending > 1 ? t('ppr.pending_many') : t('ppr.pending_one')}
        </div>
      )}

      {/* Success / Error banners */}
      {successMsg && (
        <div style={{ display: 'flex', gap: '0.6rem', padding: '0.8rem 1rem', borderRadius: '10px', background: 'rgba(16,185,129,0.08)', border: '1px solid rgba(16,185,129,0.25)', marginBottom: '1rem', color: '#059669', fontSize: '0.83rem', fontWeight: 500 }}>
          <CheckCircle2 size={16} style={{ flexShrink: 0, marginTop: 1 }} />{successMsg}
        </div>
      )}
      {errorMsg && (
        <div style={{ display: 'flex', gap: '0.6rem', padding: '0.8rem 1rem', borderRadius: '10px', background: 'rgba(239,68,68,0.07)', border: '1px solid rgba(239,68,68,0.2)', marginBottom: '1rem', color: '#dc2626', fontSize: '0.83rem', fontWeight: 500 }}>
          <AlertTriangle size={16} style={{ flexShrink: 0, marginTop: 1 }} />{errorMsg}
        </div>
      )}

      {/* New request form */}
      {showForm && (
        <div className="card" style={{ padding: '1.5rem', marginBottom: '1.5rem' }}>
          <h2 style={{ fontSize: '1rem', fontWeight: 700, margin: '0 0 1.25rem', display: 'flex', alignItems: 'center', gap: '0.45rem' }}>
            <Send size={16} style={{ color: 'var(--brand-primary)' }} /> {t('ppr.form_title')}
          </h2>

          {/* Safety notice */}
          <div style={{ display: 'flex', gap: '0.6rem', padding: '0.75rem 1rem', borderRadius: '10px', background: 'rgba(59,130,246,0.06)', border: '1px solid rgba(59,130,246,0.2)', marginBottom: '1.25rem', fontSize: '0.8rem', color: '#3b82f6' }}>
            <AlertTriangle size={15} style={{ flexShrink: 0, marginTop: 1 }} />
            <span>{t('ppr.safety_pre')} <strong>112</strong> {t('ppr.safety_post')}</span>
          </div>

          <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            <div>
              <label className="form-label">{t('ppr.med')} *</label>
              <input className="form-input" placeholder={t('ppr.med_ph')} value={medName} onChange={e => setMedName(e.target.value)} required />
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '0.75rem' }}>
              <div>
                <label className="form-label">{t('ppr.dose')}</label>
                <input className="form-input" placeholder={t('ppr.dose_ph')} value={dose} onChange={e => setDose(e.target.value)} />
              </div>
              <div>
                <label className="form-label">{t('ppr.freq')}</label>
                <input className="form-input" placeholder={t('ppr.freq_ph')} value={frequency} onChange={e => setFrequency(e.target.value)} />
              </div>
            </div>
            <div>
              <label className="form-label">{t('ppr.reason')}</label>
              <textarea className="form-input" rows={3} placeholder={t('ppr.reason_ph')} value={reason} onChange={e => setReason(e.target.value)} style={{ resize: 'vertical' }} />
            </div>
            <div>
              <label className="form-label">{t('ppr.doctor')} *</label>
              {loadingDocs ? (
                <div style={{ color: 'var(--text-muted)', fontSize: '0.82rem', padding: '0.5rem 0' }}><Loader2 size={14} style={{ display: 'inline', marginRight: 6 }} />{t('ppr.loading_docs')}</div>
              ) : doctors.length === 0 ? (
                <div style={{ color: 'var(--text-muted)', fontSize: '0.82rem', padding: '0.5rem 0' }}>{t('ppr.no_docs')}</div>
              ) : (
                <select className="form-input" value={doctorId} onChange={e => setDoctorId(e.target.value)} required>
                  <option value="">{t('ppr.select_doctor')}</option>
                  {doctors.map(d => (
                    <option key={d.id} value={d.id}>
                      {d.title ? `${d.title} ` : ''}{d.display_name}{d.specialization ? ` · ${d.specialization}` : ''}
                    </option>
                  ))}
                </select>
              )}
            </div>
            <div style={{ display: 'flex', gap: '0.5rem', justifyContent: 'flex-end', marginTop: '0.25rem' }}>
              <button type="button" onClick={() => setShowForm(false)} style={{ padding: '0.55rem 1.1rem', borderRadius: '10px', background: 'none', border: '1px solid var(--border)', fontWeight: 600, fontSize: '0.83rem', cursor: 'pointer' }}>
                {t('common.cancel')}
              </button>
              <button type="submit" disabled={submitting || !medName.trim() || !doctorId} style={{ display: 'flex', alignItems: 'center', gap: '0.4rem', padding: '0.55rem 1.25rem', borderRadius: '10px', background: 'var(--brand-primary)', color: '#fff', border: 'none', fontWeight: 700, fontSize: '0.83rem', cursor: submitting ? 'not-allowed' : 'pointer', opacity: submitting ? 0.7 : 1 }}>
                {submitting ? <Loader2 size={15} /> : <Send size={15} />}
                {submitting ? t('ppr.sending') : t('ppr.send')}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* History */}
      <div>
        <div style={{ fontSize: '0.78rem', fontWeight: 700, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '0.75rem' }}>
          {t('ppr.history')}
        </div>
        {loadingHist && (
          <div style={{ textAlign: 'center', padding: '2.5rem 0', color: 'var(--text-muted)' }}>
            <Loader2 size={24} style={{ display: 'block', margin: '0 auto 0.5rem' }} /> {t('common.loading')}
          </div>
        )}
        {!loadingHist && history.length === 0 && (
          <div style={{ textAlign: 'center', padding: '3rem 0', color: 'var(--text-muted)', fontSize: '0.88rem' }}>
            {t('ppr.no_history')}
          </div>
        )}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
          {history.map(req => {
            const sc = STATUS_CONFIG[req.status] ?? { key: '', color: '#6b7280', bg: 'rgba(107,114,128,0.1)', icon: null };
            const scLabel = sc.key ? t(sc.key) : req.status;
            const isOpen = expandedId === req.id;
            const hasDecision = req.doctor_note || req.adjusted_dose || req.adjusted_frequency;
            return (
              <div key={req.id} className="card" style={{ padding: 0, overflow: 'hidden' }}>
                <div
                  style={{ display: 'flex', alignItems: 'center', gap: '0.85rem', padding: '0.9rem 1.1rem', cursor: hasDecision ? 'pointer' : 'default' }}
                  onClick={() => hasDecision && setExpandedId(isOpen ? null : req.id)}
                >
                  <Pill size={18} style={{ color: 'var(--brand-primary)', flexShrink: 0 }} />
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontWeight: 700, fontSize: '0.88rem' }}>{req.medication_name}</div>
                    <div style={{ fontSize: '0.76rem', color: 'var(--text-muted)', marginTop: '0.1rem' }}>
                      {req.dose && <span>{req.dose} · </span>}
                      {req.frequency && <span>{req.frequency} · </span>}
                      {new Date(req.created_at).toLocaleDateString(locale)}
                    </div>
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
                    <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', fontSize: '0.75rem', fontWeight: 700, padding: '0.2rem 0.6rem', borderRadius: 999, background: sc.bg, color: sc.color }}>
                      {sc.icon} {scLabel}
                    </span>
                    {hasDecision && (isOpen ? <ChevronUp size={14} style={{ color: 'var(--text-muted)' }} /> : <ChevronDown size={14} style={{ color: 'var(--text-muted)' }} />)}
                  </div>
                </div>
                {isOpen && hasDecision && (
                  <div style={{ padding: '0.85rem 1.1rem', borderTop: '1px solid var(--border)', background: 'rgba(0,0,0,0.018)', fontSize: '0.82rem' }}>
                    {(req.adjusted_dose || req.adjusted_frequency) && (
                      <div style={{ marginBottom: '0.5rem', fontWeight: 600 }}>
                        {t('ppr.adjusted')} {req.adjusted_dose ?? req.dose}{req.adjusted_frequency ? ` · ${req.adjusted_frequency}` : ''}
                      </div>
                    )}
                    {req.doctor_note && (
                      <div style={{ color: 'var(--text-secondary)', fontStyle: 'italic' }}>
                        "{req.doctor_note}"
                      </div>
                    )}
                    {req.decided_at && (
                      <div style={{ fontSize: '0.73rem', color: 'var(--text-muted)', marginTop: '0.4rem' }}>
                        {t('ppr.decided_at')} {new Date(req.decided_at).toLocaleString(locale)}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api';
import type { Patient } from '../types';
import { User, Save, AlertCircle, Plus, Trash2, Users, Pill, Activity, Building2 } from 'lucide-react';
import { useT } from '../i18n/LanguageContext';

// ─── Local Types ─────────────────────────────────────────────

interface Medication {
  id: string;
  medication_name: string;
  dosage: string | null;
  frequency: string | null;
  is_current: boolean;
  reason: string | null;
  prescribed_by: string | null;
}

interface Dependent {
  id: string;
  full_name: string;
  relationship: string;
  date_of_birth: string | null;
  is_minor: boolean;
}

function calcAge(dob: string): number {
  const diff = Date.now() - new Date(dob).getTime();
  return Math.floor(diff / (1000 * 60 * 60 * 24 * 365.25));
}

// ─── Partners data removed — network under construction ───────

export default function PatientProfilePage() {
  const { t } = useT();
  const navigate = useNavigate();

  const [profile, setProfile] = useState<Patient | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState('');

  // ── Core profile fields ───────────────────────────────────
  const [dob, setDob] = useState('');
  const [gender, setGender] = useState('');
  const [bloodType, setBloodType] = useState('');
  const [allergies, setAllergies] = useState('');
  const [chronic, setChronic] = useState('');
  const [emergName, setEmergName] = useState('');
  const [emergPhone, setEmergPhone] = useState('');

  // ── Medications ───────────────────────────────────────────
  const [medications, setMedications] = useState<Medication[]>([]);
  const [medsLoading, setMedsLoading] = useState(false);
  const [medsError, setMedsError] = useState('');
  const [showMedForm, setShowMedForm] = useState(false);
  const [newMedName, setNewMedName] = useState('');
  const [newMedDosage, setNewMedDosage] = useState('');
  const [newMedFreq, setNewMedFreq] = useState('');
  const [savingMed, setSavingMed] = useState(false);

  // ── Family / Dependents ───────────────────────────────────
  const [dependents, setDependents] = useState<Dependent[]>([]);
  const [depsLoading, setDepsLoading] = useState(false);
  const [showDepForm, setShowDepForm] = useState(false);
  const [newDepName, setNewDepName] = useState('');
  const [newDepDob, setNewDepDob] = useState('');
  const [newDepRel, setNewDepRel] = useState('filho');
  const [savingDep, setSavingDep] = useState(false);

  useEffect(() => {
    api.get('/api/v1/patients/me')
      .then((r: any) => {
        const p = r.data;
        setProfile(p);
        setDob(p.date_of_birth || '');
        setGender(p.gender || '');
        setBloodType(p.blood_type || '');
        setAllergies((p.allergies || []).join(', '));
        setChronic((p.chronic_conditions || []).join(', '));
        setEmergName(p.emergency_contact_name || '');
        setEmergPhone(p.emergency_contact_phone || '');
      })
      .catch(() => { /* No profile yet */ })
      .finally(() => setLoading(false));

    // Load medications from backend
    setMedsLoading(true);
    api.get('/api/v1/medications/me')
      .then((r: any) => setMedications(r.data))
      .catch(() => setMedsError('Não foi possível carregar os medicamentos.'))
      .finally(() => setMedsLoading(false));

    // Load family members from backend
    setDepsLoading(true);
    api.get('/api/v1/family/me')
      .then((r: any) => setDependents(r.data))
      .catch(() => {})
      .finally(() => setDepsLoading(false));
  }, []);

  const handleSave = async (e: FormEvent) => {
    e.preventDefault();
    setSaving(true); setMsg('');
    const body = {
      date_of_birth: dob || null,
      gender: gender || null,
      blood_type: bloodType || null,
      allergies: allergies ? allergies.split(',').map((s: string) => s.trim()).filter(Boolean) : [],
      chronic_conditions: chronic ? chronic.split(',').map((s: string) => s.trim()).filter(Boolean) : [],
      emergency_contact_name: emergName || null,
      emergency_contact_phone: emergPhone || null,
    };
    try {
      if (profile) {
        await api.patch('/api/v1/patients/me', body);
      } else {
        await api.post('/api/v1/patients/profile', body);
      }
      setMsg(t('profile.saved'));
    } catch (err: any) {
      setMsg(err.response?.data?.detail || t('profile.save_error'));
    }
    setSaving(false);
  };

  // ── Medication helpers ────────────────────────────────────
  const addMedication = async () => {
    if (!newMedName.trim()) return;
    setSavingMed(true);
    try {
      const res = await api.post('/api/v1/medications', {
        medication_name: newMedName.trim(),
        dosage: newMedDosage.trim() || null,
        frequency: newMedFreq.trim() || null,
      });
      setMedications(prev => [...prev, res.data]);
      setNewMedName(''); setNewMedDosage(''); setNewMedFreq('');
      setShowMedForm(false);
    } catch {
      setMedsError('Erro ao guardar medicamento.');
    }
    setSavingMed(false);
  };

  const removeMedication = async (id: string) => {
    try {
      await api.delete(`/api/v1/medications/${id}`);
      setMedications(prev => prev.filter(m => m.id !== id));
    } catch {
      setMedsError('Erro ao remover medicamento.');
    }
  };

  // ── Dependent helpers ─────────────────────────────────────
  const addDependent = async () => {
    if (!newDepName.trim()) return;
    setSavingDep(true);
    try {
      const age = newDepDob ? calcAge(newDepDob) : 99;
      const r: any = await api.post('/api/v1/family', {
        full_name: newDepName.trim(),
        relationship: newDepRel,
        date_of_birth: newDepDob || null,
        is_minor: age < 16,
      });
      setDependents(prev => [...prev, r.data]);
      setNewDepName(''); setNewDepDob(''); setNewDepRel('filho');
      setShowDepForm(false);
    } catch { /* silent */ }
    setSavingDep(false);
  };

  const removeDependent = async (id: string) => {
    try {
      await api.delete(`/api/v1/family/${id}`);
      setDependents(prev => prev.filter(d => d.id !== id));
    } catch { /* silent */ }
  };

  if (loading) return <div className="page-loading"><div className="spinner" /></div>;

  return (
    <>
      <div className="page-header">
        <h1>{t('profile.title')}</h1>
        <p>{t('profile.subtitle')}</p>
      </div>

      {/* ── Personal Profile Form ── */}
      <div className="card" style={{ maxWidth: '700px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1.25rem', borderBottom: '1px solid var(--border)' }}>
          <User size={20} style={{ color: 'var(--accent-teal)' }} />
          <h3 style={{ fontSize: '0.95rem', fontWeight: 600 }}>{t('profile.personal')}</h3>
        </div>
        <form onSubmit={handleSave} style={{ padding: '1.25rem' }}>
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
            <div className="form-group">
              <label className="form-label">{t('profile.dob')}</label>
              <input className="form-input" type="date" value={dob} onChange={e => setDob(e.target.value)} />
            </div>
            <div className="form-group">
              <label className="form-label">{t('profile.gender')}</label>
              <select className="form-select" value={gender} onChange={e => setGender(e.target.value)}>
                <option value="">{t('profile.gender_select')}</option>
                <option value="male">{t('profile.gender_male')}</option>
                <option value="female">{t('profile.gender_female')}</option>
                <option value="other">{t('profile.gender_other')}</option>
              </select>
            </div>
            <div className="form-group">
              <label className="form-label">{t('profile.blood_type')}</label>
              <select className="form-select" value={bloodType} onChange={e => setBloodType(e.target.value)}>
                <option value="">{t('profile.gender_select')}</option>
                {['A+','A-','B+','B-','AB+','AB-','O+','O-'].map(bt => <option key={bt} value={bt}>{bt}</option>)}
              </select>
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">{t('profile.allergies')}</label>
            <input className="form-input" type="text" placeholder={t('profile.allergies_placeholder')}
              value={allergies} onChange={e => setAllergies(e.target.value)} />
          </div>

          <div className="form-group">
            <label className="form-label">{t('profile.chronic')}</label>
            <input className="form-input" type="text" placeholder={t('profile.chronic_placeholder')}
              value={chronic} onChange={e => setChronic(e.target.value)} />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
            <div className="form-group">
              <label className="form-label">{t('profile.emergency_name')}</label>
              <input className="form-input" type="text" placeholder={t('profile.emergency_name_placeholder')}
                value={emergName} onChange={e => setEmergName(e.target.value)} />
            </div>
            <div className="form-group">
              <label className="form-label">{t('profile.emergency_phone')}</label>
              <input className="form-input" type="tel" placeholder="+244 ..."
                value={emergPhone} onChange={e => setEmergPhone(e.target.value)} />
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginTop: '0.5rem' }}>
            <button type="submit" className="btn btn-primary" disabled={saving}>
              <Save size={16} /> {saving ? t('profile.saving') : t('profile.save')}
            </button>
            {msg && (
              <span style={{ fontSize: '0.82rem', color: msg.includes(t('profile.saved')) ? 'var(--accent-green)' : '#fca5a5' }}>
                {msg}
              </span>
            )}
          </div>
        </form>
      </div>

      {/* ── Medications Section ── */}
      <div className="card profile-med-section" style={{ maxWidth: '700px', marginTop: '1.25rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1.25rem', borderBottom: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Pill size={20} style={{ color: '#ef4444' }} />
            <h3 style={{ fontSize: '0.95rem', fontWeight: 600 }}>{t('meds.title')}</h3>
          </div>
          <button className="btn btn-sm btn-outline" onClick={() => setShowMedForm(v => !v)}>
            <Plus size={14} /> {t('meds.add')}
          </button>
        </div>

        <div style={{ padding: '1.25rem' }}>
          {medsLoading && <div style={{ textAlign: 'center', padding: '1rem' }}><div className="spinner" /></div>}
          {medsError && <div style={{ fontSize: '0.82rem', color: '#fca5a5', marginBottom: '0.75rem' }}>{medsError}</div>}
          {!medsLoading && medications.length === 0 && !showMedForm && (
            <div className="empty-state" style={{ padding: '2rem' }}>
              <div className="empty-state-icon"><Pill size={22} style={{ color: '#ef4444' }} /></div>
              <div className="empty-state-title">{t('meds.none')}</div>
              <div className="empty-state-desc">{t('meds.none_hint')}</div>
            </div>
          )}

          {medications.map(med => (
            <div key={med.id} className="profile-med-card">
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--text-primary)' }}>{med.medication_name}</div>
                <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)', marginTop: '0.2rem' }}>
                  {med.dosage && <span style={{ marginRight: '0.75rem' }}>💊 {med.dosage}</span>}
                  {med.frequency && <span>🔁 {med.frequency}</span>}
                </div>
              </div>
              <button className="btn btn-sm" style={{ color: '#fca5a5', background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)' }}
                onClick={() => removeMedication(med.id)}>
                <Trash2 size={13} /> {t('meds.remove')}
              </button>
            </div>
          ))}

          {showMedForm && (
            <div className="profile-med-form">
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '0.75rem', marginBottom: '0.75rem' }}>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('meds.name')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="text"
                    placeholder="Ex: Metformina" value={newMedName} onChange={e => setNewMedName(e.target.value)} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('meds.dosage')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="text"
                    placeholder="500mg" value={newMedDosage} onChange={e => setNewMedDosage(e.target.value)} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('meds.frequency')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="text"
                    placeholder="2×/dia" value={newMedFreq} onChange={e => setNewMedFreq(e.target.value)} />
                </div>
              </div>
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button className="btn btn-primary btn-sm" onClick={addMedication} disabled={savingMed}><Save size={13} /> {savingMed ? '...' : t('meds.save')}</button>
                <button className="btn btn-outline btn-sm" onClick={() => setShowMedForm(false)}>{t('family.cancel_add')}</button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ── Family / Dependents Section ── */}
      <div className="card profile-family-section" style={{ maxWidth: '700px', marginTop: '1.25rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '1.25rem', borderBottom: '1px solid var(--border)' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
            <Users size={20} style={{ color: 'var(--accent-teal)' }} />
            <div>
              <h3 style={{ fontSize: '0.95rem', fontWeight: 600, margin: 0 }}>{t('family.title')}</h3>
              <p style={{ fontSize: '0.75rem', color: 'var(--text-muted)', margin: '0.15rem 0 0' }}>{t('family.subtitle')}</p>
            </div>
          </div>
          <button className="btn btn-sm btn-outline" onClick={() => setShowDepForm(v => !v)}>
            <Plus size={14} /> {t('family.add')}
          </button>
        </div>

        <div style={{ padding: '1.25rem' }}>
          {depsLoading && <div style={{ textAlign: 'center', padding: '1rem' }}><div className="spinner" /></div>}
          {!depsLoading && dependents.length === 0 && !showDepForm && (
            <div className="empty-state" style={{ padding: '2rem' }}>
              <div className="empty-state-icon"><Users size={22} style={{ color: 'var(--accent-teal)' }} /></div>
              <div className="empty-state-title">{t('family.none')}</div>
            </div>
          )}

          {dependents.map(dep => {
            const age = dep.date_of_birth ? calcAge(dep.date_of_birth) : null;
            return (
              <div key={dep.id} className="profile-dependent-card">
                <div style={{ flex: 1 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', marginBottom: '0.25rem' }}>
                    <span style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--text-primary)' }}>{dep.full_name}</span>
                    {dep.is_minor && (
                      <span style={{
                        fontSize: '0.68rem', padding: '0.1rem 0.45rem', borderRadius: '20px',
                        background: 'rgba(234,179,8,0.15)', color: '#eab308', border: '1px solid rgba(234,179,8,0.3)', fontWeight: 600,
                      }}>
                        {t('family.minor_badge')}
                      </span>
                    )}
                  </div>
                  <div style={{ fontSize: '0.78rem', color: 'var(--text-secondary)' }}>
                    {dep.relationship.charAt(0).toUpperCase() + dep.relationship.slice(1)}
                    {age !== null && <span style={{ marginLeft: '0.5rem' }}>• {age} anos</span>}
                  </div>
                  {dep.is_minor && (
                    <div style={{ fontSize: '0.72rem', color: 'var(--accent-teal)', marginTop: '0.2rem' }}>
                      {t('family.minor_note')}
                    </div>
                  )}
                </div>
                <div style={{ display: 'flex', gap: '0.5rem', flexShrink: 0 }}>
                  <button className="btn btn-sm btn-primary" onClick={() => navigate('/triage', { state: { dependent: { id: dep.id, name: dep.full_name, is_minor: dep.is_minor } } })}>
                    <Activity size={13} /> {t('family.triage_for')}
                  </button>
                  <button className="btn btn-sm"
                    style={{ color: '#fca5a5', background: 'rgba(239,68,68,0.08)', border: '1px solid rgba(239,68,68,0.2)' }}
                    onClick={() => removeDependent(dep.id)}>
                    <Trash2 size={13} />
                  </button>
                </div>
              </div>
            );
          })}

          {showDepForm && (
            <div className="profile-med-form">
              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr 1fr', gap: '0.75rem', marginBottom: '0.75rem' }}>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('family.name')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="text"
                    placeholder="Nome completo" value={newDepName} onChange={e => setNewDepName(e.target.value)} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('family.dob')}</label>
                  <input className="form-input" style={{ fontSize: '0.85rem' }} type="date"
                    value={newDepDob} onChange={e => setNewDepDob(e.target.value)} />
                </div>
                <div className="form-group" style={{ margin: 0 }}>
                  <label className="form-label" style={{ fontSize: '0.78rem' }}>{t('family.rel')}</label>
                  <select className="form-select" style={{ fontSize: '0.85rem' }} value={newDepRel}
                    onChange={e => setNewDepRel(e.target.value)}>
                    <option value="filho">{t('family.rel_son')}</option>
                    <option value="filha">{t('family.rel_daughter')}</option>
                    <option value="outro">{t('family.rel_other')}</option>
                  </select>
                </div>
              </div>
              {newDepDob && (
                <p style={{ fontSize: '0.78rem', color: calcAge(newDepDob) < 16 ? '#eab308' : 'var(--text-muted)', marginBottom: '0.5rem' }}>
                  {calcAge(newDepDob)} anos
                  {calcAge(newDepDob) < 16 ? ' — será criado como perfil pediátrico' : ''}
                </p>
              )}
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <button className="btn btn-primary btn-sm" onClick={addDependent} disabled={savingDep}><Save size={13} /> {savingDep ? '...' : t('family.save')}</button>
                <button className="btn btn-outline btn-sm" onClick={() => setShowDepForm(false)}>{t('family.cancel_add')}</button>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* ══ PARCEIROS DE SAÚDE ══ */}
      <div className="card" style={{ maxWidth: '700px', marginTop: '1.5rem' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem', padding: '1.25rem', borderBottom: '1px solid var(--border)' }}>
          <Building2 size={18} style={{ color: 'var(--accent-teal)' }} />
          <h3 style={{ fontSize: '0.95rem', fontWeight: 600 }}>Rede de Parceiros</h3>
        </div>
        <div style={{ padding: '1.5rem', textAlign: 'center' }}>
          <div style={{ width: 52, height: 52, borderRadius: '50%', background: 'rgba(15,118,110,0.08)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1rem' }}>
            <Building2 size={24} style={{ color: 'var(--brand-primary)' }} />
          </div>
          <p style={{ fontWeight: 600, fontSize: '0.95rem', color: 'var(--text-primary)', marginBottom: '0.5rem' }}>
            Rede em construção
          </p>
          <p style={{ fontSize: '0.83rem', color: 'var(--text-secondary)', lineHeight: 1.6, maxWidth: 440, margin: '0 auto 1.25rem' }}>
            Estamos a estabelecer parcerias com médicos independentes, clínicas e instituições de saúde.
            Quando os parceiros estiverem disponíveis na sua área, aparecerão aqui para associar ao seu perfil.
          </p>
          <a
            href="mailto:parcerias@kaya.ao"
            style={{
              display: 'inline-flex', alignItems: 'center', gap: '0.4rem',
              padding: '0.5rem 1.1rem', borderRadius: '999px',
              background: 'var(--brand-light)', color: 'var(--brand-primary)',
              border: '1px solid var(--brand-border)',
              fontSize: '0.82rem', fontWeight: 600, textDecoration: 'none',
            }}
          >
            Sugerir uma clínica ou médico →
          </a>
        </div>
      </div>

      {/* Info tip */}
      <div style={{
        marginTop: '1rem', padding: '0.85rem 1rem', borderRadius: '12px',
        border: '1px solid rgba(20,184,166,0.2)', background: 'rgba(20,184,166,0.06)',
        display: 'flex', gap: '0.65rem', alignItems: 'flex-start', maxWidth: '700px',
      }}>
        <AlertCircle size={18} style={{ color: 'var(--accent-teal)', flexShrink: 0, marginTop: '2px' }} />
        <div style={{ fontSize: '0.82rem', color: 'var(--text-secondary)' }}>
          {t('profile.info_tip')}
        </div>
      </div>
    </>
  );
}

import { useEffect, useState } from 'react';
import api from '../api';
import {
  Activity, Plus, Trash2, X, Loader2, ThermometerSun,
  Droplets, Wind, Weight, Heart, HeartPulse, Upload, Scale,
} from 'lucide-react';
import { useT } from '../i18n/LanguageContext';

// ── Types ────────────────────────────────────────────────────────────────────

type ReadingType =
  | 'blood_pressure'
  | 'glucose'
  | 'temperature'
  | 'oxygen_saturation'
  | 'weight'
  | 'heart_rate'
  | 'body_fat'
  | 'bmi'
  | 'lean_body_mass'
  | 'body_water_mass'
  | 'bone_mass'
  | 'height'
  | 'waist_circumference'
  | 'basal_metabolic_rate';

interface DeviceReading {
  id: string;
  reading_type: ReadingType;
  value: number | null;
  unit: string | null;
  systolic: number | null;
  diastolic: number | null;
  pulse: number | null;
  measured_at: string;
  source: string | null;
  device_brand: string | null;
  device_model: string | null;
  notes: string | null;
  created_at: string;
}

interface ReadingListOut {
  total: number;
  readings: DeviceReading[];
}

// ── Constants ────────────────────────────────────────────────────────────────

const READING_TYPES: { value: ReadingType; label: string; labelKey: string; icon: React.ElementType; defaultUnit: string }[] = [
  { value: 'blood_pressure',    label: 'Pressão Arterial',      labelKey: 'read.t_blood_pressure', icon: Heart,         defaultUnit: 'mmHg' },
  { value: 'glucose',           label: 'Glicose',               labelKey: 'read.t_glucose',        icon: Droplets,      defaultUnit: 'mg/dL' },
  { value: 'temperature',       label: 'Temperatura',           labelKey: 'read.t_temperature',    icon: ThermometerSun,defaultUnit: '°C' },
  { value: 'oxygen_saturation', label: 'Saturação de Oxigénio', labelKey: 'read.t_oxygen',         icon: Wind,          defaultUnit: '%' },
  { value: 'weight',            label: 'Peso',                  labelKey: 'read.t_weight',         icon: Weight,        defaultUnit: 'kg' },
  { value: 'heart_rate',        label: 'Frequência Cardíaca',   labelKey: 'read.t_heart_rate',     icon: HeartPulse,    defaultUnit: 'bpm' },
  { value: 'body_fat',          label: 'Gordura Corporal',      labelKey: 'read.t_body_fat',       icon: Activity,      defaultUnit: '%' },
  { value: 'bmi',               label: 'IMC',                    labelKey: 'read.t_bmi',            icon: Scale,         defaultUnit: 'kg/m²' },
  { value: 'lean_body_mass',    label: 'Massa Magra',            labelKey: 'read.t_lean_mass',      icon: Weight,        defaultUnit: 'kg' },
  { value: 'body_water_mass',   label: 'Água Corporal',          labelKey: 'read.t_body_water',     icon: Droplets,      defaultUnit: 'kg' },
  { value: 'bone_mass',         label: 'Massa Óssea',            labelKey: 'read.t_bone_mass',      icon: Activity,      defaultUnit: 'kg' },
  { value: 'height',            label: 'Altura',                 labelKey: 'read.t_height',         icon: Activity,      defaultUnit: 'm' },
  { value: 'waist_circumference', label: 'Cintura',              labelKey: 'read.t_waist',          icon: Activity,      defaultUnit: 'cm' },
  { value: 'basal_metabolic_rate', label: 'Metabolismo Basal',   labelKey: 'read.t_bmr',            icon: Activity,      defaultUnit: 'kcal/day' },
];

const TYPE_META = Object.fromEntries(READING_TYPES.map(t => [t.value, t])) as Record<
  ReadingType,
  (typeof READING_TYPES)[number]
>;

// ── Helpers ──────────────────────────────────────────────────────────────────

function formatDate(iso: string) {
  return new Date(iso).toLocaleString('pt-PT', {
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit',
  });
}

function readingDisplay(r: DeviceReading): string {
  if (r.reading_type === 'blood_pressure') {
    const parts = [r.systolic != null && r.diastolic != null ? `${r.systolic}/${r.diastolic}` : '—'];
    if (r.pulse) parts.push(`pulso: ${r.pulse}`);
    return parts.join(' · ') + ' mmHg';
  }
  return r.value != null ? `${r.value} ${r.unit ?? ''}`.trim() : '—';
}

function typeIcon(type: ReadingType) {
  const Icon = TYPE_META[type]?.icon ?? Activity;
  return <Icon size={14} />;
}

// ── Empty form state ─────────────────────────────────────────────────────────

const emptyForm = {
  reading_type: 'blood_pressure' as ReadingType,
  value: '',
  unit: 'mmHg',
  systolic: '',
  diastolic: '',
  pulse: '',
  measured_at: new Date().toISOString().slice(0, 16), // datetime-local format
  source: 'manual',
  device_brand: '',
  device_model: '',
  notes: '',
};

// ── Main Component ───────────────────────────────────────────────────────────

export default function PatientReadingsPage() {
  const { t } = useT();

  const [readings, setReadings]     = useState<DeviceReading[]>([]);
  const [total, setTotal]           = useState(0);
  const [loading, setLoading]       = useState(true);
  const [showForm, setShowForm]     = useState(false);
  const [form, setForm]             = useState(emptyForm);
  const [saving, setSaving]         = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [error, setError]           = useState('');
  const [success, setSuccess]       = useState('');
  const [filterType, setFilterType] = useState<ReadingType | ''>('');
  const [importing, setImporting]   = useState(false);

  // Load readings
  const load = (type?: ReadingType | '') => {
    setLoading(true);
    const params = type ? `?reading_type=${type}` : '';
    api.get<ReadingListOut>(`/api/v1/readings/me${params}`)
      .then(r => { setReadings(r.data.readings); setTotal(r.data.total); })
      .catch(() => setError(t('read.err_load')))
      .finally(() => setLoading(false));
  };

  useEffect(() => { load(); }, []);

  // Sync unit default when reading_type changes
  const handleTypeChange = (type: ReadingType) => {
    setForm(f => ({ ...f, reading_type: type, unit: TYPE_META[type].defaultUnit }));
  };

  const handleFilterChange = (type: ReadingType | '') => {
    setFilterType(type);
    load(type);
  };

  // Submit new reading
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setSaving(true);
    try {
      const payload: Record<string, unknown> = {
        reading_type: form.reading_type,
        source: form.source || 'manual',
        measured_at: form.measured_at ? new Date(form.measured_at).toISOString() : undefined,
        device_brand: form.device_brand || undefined,
        device_model: form.device_model || undefined,
        notes: form.notes || undefined,
      };

      if (form.reading_type === 'blood_pressure') {
        if (!form.systolic || !form.diastolic) {
          setError(t('read.bp_required'));
          setSaving(false);
          return;
        }
        payload.systolic  = Number(form.systolic);
        payload.diastolic = Number(form.diastolic);
        if (form.pulse)  payload.pulse = Number(form.pulse);
      } else {
        if (!form.value) {
          setError(t('read.value_required'));
          setSaving(false);
          return;
        }
        payload.value = Number(form.value);
        payload.unit  = form.unit || TYPE_META[form.reading_type].defaultUnit;
      }

      await api.post('/api/v1/readings', payload);
      setSuccess(t('read.saved'));
      setShowForm(false);
      setForm(emptyForm);
      load(filterType);
    } catch (err: any) {
      setError(err?.response?.data?.detail || t('read.err_save'));
    } finally {
      setSaving(false);
    }
  };

  // Delete a reading
  const handleDelete = async (id: string) => {
    if (!confirm(t('read.confirm_delete'))) return;
    setDeletingId(id);
    try {
      await api.delete(`/api/v1/readings/${id}`);
      setReadings(prev => prev.filter(r => r.id !== id));
      setTotal(t => t - 1);
      setSuccess(t('read.deleted'));
    } catch {
      setError(t('read.err_delete'));
    } finally {
      setDeletingId(null);
    }
  };

  const isBP = form.reading_type === 'blood_pressure';

  const importRenphoCsv = async (file?: File) => {
    if (!file) return;
    setError('');
    setSuccess('');
    setImporting(true);
    try {
      const body = new FormData();
      body.append('file', file);
      const response = await api.post('/api/v1/readings/import', body);
      setSuccess(t('read.import_success')
        .replace('{imported}', String(response.data.imported ?? 0))
        .replace('{skipped}', String(response.data.skipped ?? 0)));
      load(filterType);
    } catch (err: any) {
      setError(err?.response?.data?.detail || t('read.import_error'));
    } finally {
      setImporting(false);
    }
  };

  return (
    <>
      {/* Header */}
      <div className="page-header">
        <div>
          <h1>{t('read.title')}</h1>
          <p>{t('read.subtitle')}</p>
        </div>
        <button className="btn btn-primary" onClick={() => { setShowForm(s => !s); setError(''); setSuccess(''); }}>
          {showForm ? <><X size={16} /> {t('common.cancel')}</> : <><Plus size={16} /> {t('read.new')}</>}
        </button>
      </div>

      {/* Alerts */}
      {error   && <div className="alert alert-error"   style={{ marginBottom: '1rem' }}>{error}   <button onClick={() => setError('')}   style={{ marginLeft: 'auto', background: 'none', border: 'none', cursor: 'pointer' }}><X size={14} /></button></div>}
      {success && <div className="alert alert-success" style={{ marginBottom: '1rem' }}>{success} <button onClick={() => setSuccess('')} style={{ marginLeft: 'auto', background: 'none', border: 'none', cursor: 'pointer' }}><X size={14} /></button></div>}

      <div className="reading-import-card">
        <div className="reading-import-card__icon"><Scale size={22} /></div>
        <div className="reading-import-card__copy">
          <strong>{t('read.import_title')}</strong>
          <span>{t('read.import_desc')}</span>
        </div>
        <label className={`btn btn-outline reading-import-card__button${importing ? ' disabled' : ''}`}>
          {importing ? <Loader2 size={15} className="spin" /> : <Upload size={15} />}
          {importing ? t('read.importing') : t('read.import_button')}
          <input
            type="file"
            accept=".csv,text/csv"
            disabled={importing}
            onChange={event => {
              void importRenphoCsv(event.target.files?.[0]);
              event.currentTarget.value = '';
            }}
          />
        </label>
      </div>

      {/* ── Add form ── */}
      {showForm && (
        <div className="card" style={{ marginBottom: '1.5rem' }}>
          <h3 style={{ marginBottom: '1.25rem', fontSize: '1rem', fontWeight: 600 }}>{t('read.new')}</h3>
          <form onSubmit={handleSubmit}>
            <div className="form-grid" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(220px, 1fr))', gap: '1rem' }}>

              {/* Type */}
              <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                <label className="form-label">Tipo de Medição *</label>
                <select
                  className="form-input"
                  value={form.reading_type}
                  onChange={e => handleTypeChange(e.target.value as ReadingType)}
                  required
                >
                  {READING_TYPES.map(rt => (
                    <option key={rt.value} value={rt.value}>{t(rt.labelKey)}</option>
                  ))}
                </select>
              </div>

              {/* Blood pressure fields */}
              {isBP ? (
                <>
                  <div className="form-group">
                    <label className="form-label">Sistólica (mmHg) *</label>
                    <input className="form-input" type="number" min={40} max={300} placeholder="120"
                      value={form.systolic} onChange={e => setForm(f => ({ ...f, systolic: e.target.value }))} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Diastólica (mmHg) *</label>
                    <input className="form-input" type="number" min={20} max={200} placeholder="80"
                      value={form.diastolic} onChange={e => setForm(f => ({ ...f, diastolic: e.target.value }))} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Pulso (bpm)</label>
                    <input className="form-input" type="number" min={20} max={300} placeholder="72"
                      value={form.pulse} onChange={e => setForm(f => ({ ...f, pulse: e.target.value }))} />
                  </div>
                </>
              ) : (
                <>
                  <div className="form-group">
                    <label className="form-label">Valor *</label>
                    <input className="form-input" type="number" step="any" placeholder="0"
                      value={form.value} onChange={e => setForm(f => ({ ...f, value: e.target.value }))} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">{t('read.unit')}</label>
                    <input className="form-input" type="text" maxLength={20}
                      value={form.unit} onChange={e => setForm(f => ({ ...f, unit: e.target.value }))} />
                  </div>
                </>
              )}

              {/* measured_at */}
              <div className="form-group">
                <label className="form-label">Data / Hora da Medição</label>
                <input className="form-input" type="datetime-local"
                  value={form.measured_at} onChange={e => setForm(f => ({ ...f, measured_at: e.target.value }))} />
              </div>

              {/* device_brand */}
              <div className="form-group">
                <label className="form-label">{t('read.device_brand')}</label>
                <input className="form-input" type="text" maxLength={100} placeholder="ex: Omron"
                  value={form.device_brand} onChange={e => setForm(f => ({ ...f, device_brand: e.target.value }))} />
              </div>

              {/* device_model */}
              <div className="form-group">
                <label className="form-label">{t('read.device_model')}</label>
                <input className="form-input" type="text" maxLength={100} placeholder="ex: M3"
                  value={form.device_model} onChange={e => setForm(f => ({ ...f, device_model: e.target.value }))} />
              </div>

              {/* notes */}
              <div className="form-group" style={{ gridColumn: '1 / -1' }}>
                <label className="form-label">{t('read.notes')}</label>
                <textarea className="form-input" rows={2} maxLength={500} placeholder={t('read.notes_ph')}
                  value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))} />
              </div>
            </div>

            <div style={{ display: 'flex', gap: '0.75rem', marginTop: '1.25rem' }}>
              <button type="submit" className="btn btn-primary" disabled={saving}>
                {saving ? <><Loader2 size={14} className="spin" /> A guardar…</> : 'Guardar Medição'}
              </button>
              <button type="button" className="btn btn-ghost" onClick={() => { setShowForm(false); setForm(emptyForm); }}>
                Cancelar
              </button>
            </div>
          </form>
        </div>
      )}

      {/* ── Filter ── */}
      <div className="tab-nav" style={{ marginBottom: '1.25rem' }}>
        <button className={filterType === '' ? 'active' : ''} onClick={() => handleFilterChange('')}>{t('read.all')}</button>
        {READING_TYPES.map(rt => (
          <button key={rt.value} className={filterType === rt.value ? 'active' : ''} onClick={() => handleFilterChange(rt.value)}>
            {t(rt.labelKey)}
          </button>
        ))}
      </div>

      {/* ── Readings list ── */}
      {loading ? (
        <div className="page-loading"><div className="spinner" /></div>
      ) : readings.length === 0 ? (
        <div className="card">
          <div className="empty-state" style={{ padding: '4rem 2rem' }}>
            <div className="empty-state-icon">
              <Activity size={32} style={{ color: 'var(--accent-teal)' }} />
            </div>
            <div className="empty-state-title">{t('read.empty')}</div>
            <div className="empty-state-desc">
              {t('read.empty_hint')}
            </div>
          </div>
        </div>
      ) : (
        <div className="card" style={{ padding: 0, overflow: 'hidden' }}>
          <div style={{ padding: '1rem 1.25rem', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            <span style={{ fontSize: '0.875rem', color: 'var(--text-muted)' }}>
              {total} medição{total !== 1 ? 'ões' : ''} encontrada{total !== 1 ? 's' : ''}
            </span>
          </div>
          <div style={{ overflowX: 'auto' }}>
            <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.875rem' }}>
              <thead>
                <tr style={{ background: 'var(--surface-2, #f9fafb)' }}>
                  {['Tipo', 'Valor', 'Data / Hora', 'Dispositivo', 'Notas', ''].map(h => (
                    <th key={h} style={{ padding: '0.75rem 1rem', textAlign: 'left', fontWeight: 600, color: 'var(--text-muted)', fontSize: '0.75rem', textTransform: 'uppercase', letterSpacing: '0.05em', whiteSpace: 'nowrap' }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {readings.map((r, i) => (
                  <tr key={r.id} style={{ borderTop: i > 0 ? '1px solid var(--border)' : 'none' }}>
                    <td style={{ padding: '0.875rem 1rem', whiteSpace: 'nowrap' }}>
                      <span style={{ display: 'inline-flex', alignItems: 'center', gap: '0.4rem', fontWeight: 500 }}>
                        {typeIcon(r.reading_type)}
                        {TYPE_META[r.reading_type] ? t(TYPE_META[r.reading_type].labelKey) : r.reading_type}
                      </span>
                    </td>
                    <td style={{ padding: '0.875rem 1rem', fontWeight: 600, color: 'var(--text-primary)', whiteSpace: 'nowrap' }}>
                      {readingDisplay(r)}
                    </td>
                    <td style={{ padding: '0.875rem 1rem', color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>
                      {formatDate(r.measured_at)}
                    </td>
                    <td style={{ padding: '0.875rem 1rem', color: 'var(--text-muted)' }}>
                      {[r.device_brand, r.device_model].filter(Boolean).join(' ') || (r.source === 'manual' ? 'Manual' : r.source) || '—'}
                    </td>
                    <td style={{ padding: '0.875rem 1rem', color: 'var(--text-muted)', maxWidth: '200px' }}>
                      <span title={r.notes ?? ''} style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', display: 'block' }}>
                        {r.notes || '—'}
                      </span>
                    </td>
                    <td style={{ padding: '0.875rem 1rem', textAlign: 'right' }}>
                      <button
                        className="btn btn-ghost"
                        style={{ padding: '0.25rem 0.5rem', color: 'var(--danger, #ef4444)' }}
                        disabled={deletingId === r.id}
                        onClick={() => handleDelete(r.id)}
                        title="Eliminar"
                      >
                        {deletingId === r.id ? <Loader2 size={14} className="spin" /> : <Trash2 size={14} />}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </>
  );
}

