  ['LT', 'Lituânia'], ['LU', 'Luxemburgo'], ['MT', 'Malta'], ['NL', 'Países Baixos'],
  ['PL', 'Polónia'], ['RO', 'Roménia'], ['SK', 'Eslováquia'], ['SI', 'Eslovénia'],
  ['SE', 'Suécia'],
] as const;
const countryName = (code: string) => COUNTRIES.find(([value]) => value === code)?.[1] || code;
const CountryOptions = () => <>{COUNTRIES.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</>;

export default function RegisterPage() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const { t } = useT();

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPw, setConfirmPw] = useState('');
  const [fullName, setFullName] = useState('');
  const [sector, setSector] = useState('');
  const [role, setRole] = useState<'patient' | 'doctor' | 'nurse'>('patient');
  const [practiceCountry, setPracticeCountry] = useState('AO');
  const [licenceCountry, setLicenceCountry] = useState('AO');
  const [diplomaCountry, setDiplomaCountry] = useState('AO');
  const [issuingAuthority, setIssuingAuthority] = useState('');
  const [licenceNumber, setLicenceNumber] = useState('');
  const [licenceJurisdiction, setLicenceJurisdiction] = useState('');
  const [diplomaInstitution, setDiplomaInstitution] = useState('');
  const [degreeTitle, setDegreeTitle] = useState('');
  const [graduationYear, setGraduationYear] = useState('');
  const [showPw, setShowPw] = useState(false);
  const [showCpw, setShowCpw] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  // Consent checkboxes
  const [consents, setConsents] = useState({
    terms_of_service: false,
    privacy_policy: false,
    medical_disclaimer: false,
    health_data_processing: false,
    telemedicine_consent: false,
  });
  const allConsentsChecked = REQUIRED_CONSENTS.every(c => consents[c]);

  const sectors = [
    { value: '', label: t('register.sector_select') },
    { value: 'general', label: t('register.sector_general') },
    { value: 'cardiology', label: t('register.sector_cardiology') },
    { value: 'dermatology', label: t('register.sector_dermatology') },
    { value: 'pediatrics', label: t('register.sector_pediatrics') },
    { value: 'orthopedics', label: t('register.sector_orthopedics') },
    { value: 'neurology', label: t('register.sector_neurology') },
  ];

  const handleRegister = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    if (password !== confirmPw) { setError(t('register.pw_mismatch')); return; }
    if (password.length < 6) { setError(t('register.pw_short')); return; }
    if (!allConsentsChecked) { setError('Aceite todos os consentimentos obrigatórios para se registar.'); return; }
    if (role !== 'patient' && (!fullName || !issuingAuthority || !licenceNumber || !diplomaInstitution || !degreeTitle)) {
      setError('Complete os dados profissionais obrigatórios antes de continuar.');
      return;
    }

    setLoading(true);
    try {
      const body = {
        email,
        password,
        full_name: fullName || email.split('@')[0],
        sector_focus: 'health',
        org_name: 'KAYA',
        account_name: fullName || email.split('@')[0],
        entity_type: 'individual',
        modules_enabled: ['triage', 'teleconsulta'],
        role,
        ...(role !== 'patient' ? {
          practice_country: practiceCountry,
          licence_country: licenceCountry,
          diploma_country: diplomaCountry,
          issuing_authority: issuingAuthority,
          licence_number: licenceNumber,
          licence_jurisdiction: licenceJurisdiction || null,
          diploma_institution: diplomaInstitution,
          degree_title: degreeTitle,
          graduation_year: graduationYear ? Number(graduationYear) : null,
          specialization: sector || 'general',
        } : {}),
      };
      const res = await api.post('/auth/register', body);
      login(res.data);
      // Post consents in background (best-effort; ConsentGate will catch any failures)
      for (const ct of REQUIRED_CONSENTS) {
        api.post('/api/v1/compliance/consent', { consent_type: ct }).catch(() => {});
      }
      sessionStorage.setItem('consents_accepted', 'true');
      navigate(role === 'patient' ? '/dashboard' : '/professional-verification');
    } catch (err: any) {
      setError(apiErrorMessage(err, t('register.error')));
    } finally { setLoading(false); }
  };

  return (
    <div className="auth-shell">
      <div style={{ position: 'absolute', top: '1rem', right: '1rem', zIndex: 100 }}>
        <LanguageSelector />
      </div>

      <div className="auth-card" style={{ maxWidth: role === 'patient' ? 420 : 680, transition: 'max-width .2s ease' }}>
        {/* Brand */}
        <div className="auth-brand">
          <img src={kayaLogo} alt="KAYA" style={{ width: 48, height: 48 }} />
          <span className="auth-brand-text">KAYA</span>
        </div>

        <h1 className="auth-title">{t('register.title')}</h1>
        <p className="auth-subtitle">{t('register.subtitle')}</p>

        <form onSubmit={handleRegister}>
          <div className="form-group">
            <label className="form-label">Criar conta como</label>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.55rem' }}>
              {([
                ['patient', <User size={18} />, 'Paciente'],
                ['nurse', <HeartPulse size={18} />, 'Enfermeiro/a'],
                ['doctor', <Stethoscope size={18} />, 'Médico/a'],
              ] as const).map(([value, icon, label]) => (
                <button key={value} type="button" onClick={() => setRole(value)}
                  style={{
                    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6,
                    padding: '0.8rem 0.3rem', borderRadius: 10, cursor: 'pointer',
                    border: role === value ? '2px solid var(--accent-teal)' : '1px solid var(--border, #e2e8f0)',
                    background: role === value ? 'rgba(13,148,136,.08)' : 'var(--bg-card, white)',
                    color: role === value ? 'var(--accent-teal)' : 'var(--text-secondary, #475569)',
                    fontSize: '.76rem', fontWeight: 700,
                  }}>
                  {icon}{label}
                </button>
              ))}
            </div>
            {role !== 'patient' && (
              <p style={{ fontSize: '.76rem', color: 'var(--text-muted)', margin: '.55rem 0 0', lineHeight: 1.45 }}>
                A conta será criada com acesso limitado. Acesso clínico é activado após envio e revisão das credenciais.
              </p>
            )}
          </div>

          <div className="form-group">
            <label className="form-label">{t('register.full_name')}</label>
            <div className="form-input-icon">
              <User size={16} className="icon-left" />
              <input className="form-input" type="text" placeholder="João Silva"
                value={fullName} onChange={e => setFullName(e.target.value)} />
            </div>
          </div>

          {role !== 'patient' && (
            <div style={{ padding: '1rem', marginBottom: '1rem', border: '1px solid var(--border, #e2e8f0)', borderRadius: 10, background: 'var(--bg, #f8fafc)' }}>
              <p style={{ margin: '0 0 .8rem', fontSize: '.8rem', fontWeight: 700 }}>Dados profissionais</p>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(135px, 1fr))', gap: '.7rem' }}>
                <label className="form-group" style={{ margin: 0 }}>
                  <span className="form-label">País de exercício / registo</span>
                  <select className="form-select" value={practiceCountry} onChange={e => setPracticeCountry(e.target.value)}>
                    <CountryOptions />
                  </select>
                </label>
                <label className="form-group" style={{ margin: 0 }}>
                  <span className="form-label">País que emitiu a licença</span>
                  <select className="form-select" value={licenceCountry} onChange={e => setLicenceCountry(e.target.value)}>
                    <CountryOptions />
                  </select>
                </label>
                <label className="form-group" style={{ margin: 0 }}>
                  <span className="form-label">País que emitiu o diploma / certificado</span>
                  <select className="form-select" value={diplomaCountry} onChange={e => setDiplomaCountry(e.target.value)}>
                    <CountryOptions />
                  </select>
                </label>
              </div>
              {practiceCountry !== diplomaCountry && (
                <div style={{ margin: '.7rem 0', padding: '.65rem', borderRadius: 8, background: '#fffbeb', color: '#92400e', fontSize: '.76rem' }}>
                  Diploma estrangeiro: será obrigatório enviar o reconhecimento/equivalência para exercer em {countryName(practiceCountry)}.
                </div>
              )}
              <input className="form-input" style={{ marginTop: '.7rem' }} placeholder="Autoridade emissora / Ordem profissional *"
                value={issuingAuthority} onChange={e => setIssuingAuthority(e.target.value)} required />
              <input className="form-input" style={{ marginTop: '.7rem' }} placeholder="Número da cédula ou licença profissional *"
                value={licenceNumber} onChange={e => setLicenceNumber(e.target.value)} required />
              {licenceCountry === 'US' && (
                <input className="form-input" style={{ marginTop: '.7rem' }} placeholder="Estado / jurisdição da licença dos EUA *"
                  value={licenceJurisdiction} onChange={e => setLicenceJurisdiction(e.target.value)} required />
              )}
              <input className="form-input" style={{ marginTop: '.7rem' }} placeholder="Instituição do diploma *"
                value={diplomaInstitution} onChange={e => setDiplomaInstitution(e.target.value)} required />
              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '.7rem', marginTop: '.7rem' }}>
                <input className="form-input" placeholder="Título do curso / grau *"
                  value={degreeTitle} onChange={e => setDegreeTitle(e.target.value)} required />
                <input className="form-input" inputMode="numeric" placeholder="Ano"
                  value={graduationYear} onChange={e => setGraduationYear(e.target.value.replace(/\D/g, '').slice(0, 4))} />
              </div>
            </div>
          )}

          <div className="form-group">
            <label className="form-label">{t('register.email')}</label>
            <div className="form-input-icon">
              <Mail size={16} className="icon-left" />
              <input className="form-input" type="email" placeholder="utilizador@empresa.com"
                value={email} onChange={e => setEmail(e.target.value)} required />
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">{t('register.password')}</label>
            <div className="form-input-icon">
              <Lock size={16} className="icon-left" />
              <input className="form-input" type={showPw ? 'text' : 'password'} placeholder={t('register.password_placeholder')}
                value={password} onChange={e => setPassword(e.target.value)} required
                style={{ paddingRight: '2.5rem' }} />
              <button type="button" className="icon-right" onClick={() => setShowPw(!showPw)}
                style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}>
                {showPw ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">{t('register.confirm_password')}</label>
            <div className="form-input-icon">
              <Lock size={16} className="icon-left" />
              <input className="form-input" type={showCpw ? 'text' : 'password'} placeholder={t('register.confirm_placeholder')}
                value={confirmPw} onChange={e => setConfirmPw(e.target.value)} required
                style={{ paddingRight: '2.5rem' }} />
              <button type="button" className="icon-right" onClick={() => setShowCpw(!showCpw)}
                style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--text-muted)' }}>
                {showCpw ? <EyeOff size={16} /> : <Eye size={16} />}
              </button>
            </div>
          </div>

          <div className="form-group">
            <label className="form-label">{t('register.sector')}</label>
            <select className="form-select" value={sector} onChange={e => setSector(e.target.value)} required>
              {sectors.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
            </select>
          </div>

          {/* ── Required consents ── */}
          <div style={{ margin: '0.25rem 0 1rem', padding: '1rem', borderRadius: '8px',
            border: '1px solid var(--border, #e2e8f0)', background: 'var(--bg, #f8fafc)',
            display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
            <p style={{ margin: 0, fontSize: '0.78rem', fontWeight: 600,
              color: 'var(--text-muted, #64748b)', textTransform: 'uppercase', letterSpacing: '0.05em' }}>
              Consentimentos obrigatórios
            </p>

            <label style={{ display: 'flex', gap: '0.6rem', alignItems: 'flex-start', cursor: 'pointer' }}>
              <input type="checkbox" checked={consents.terms_of_service}
                onChange={() => setConsents(p => ({ ...p, terms_of_service: !p.terms_of_service }))}
                style={{ marginTop: '2px', accentColor: 'var(--accent-teal, #0d9488)', cursor: 'pointer' }} />
              <span style={{ fontSize: '0.82rem', color: 'var(--text, #0f172a)', lineHeight: 1.5 }}>
                Aceito os{' '}
                <Link to="/terms" target="_blank"
                  style={{ color: 'var(--accent-teal, #0d9488)' }}>Termos de Serviço</Link>
              </span>
            </label>

            <label style={{ display: 'flex', gap: '0.6rem', alignItems: 'flex-start', cursor: 'pointer' }}>
              <input type="checkbox" checked={consents.medical_disclaimer}
                onChange={() => setConsents(p => ({ ...p, medical_disclaimer: !p.medical_disclaimer }))}
                style={{ marginTop: '2px', accentColor: 'var(--accent-teal, #0d9488)', cursor: 'pointer' }} />
              <span style={{ fontSize: '0.82rem', color: 'var(--text, #0f172a)', lineHeight: 1.5 }}>
                Reconheço o{' '}
                <Link to="/medical-disclaimer" target="_blank"
                  style={{ color: 'var(--accent-teal, #0d9488)' }}>Aviso Médico</Link>
                {' '}— esta plataforma não é um serviço de emergência e não substitui o atendimento presencial
              </span>
            </label>

            <label style={{ display: 'flex', gap: '0.6rem', alignItems: 'flex-start', cursor: 'pointer' }}>
              <input type="checkbox" checked={consents.health_data_processing}
                onChange={() => setConsents(p => ({ ...p, health_data_processing: !p.health_data_processing }))}
                style={{ marginTop: '2px', accentColor: 'var(--accent-teal, #0d9488)', cursor: 'pointer' }} />
              <span style={{ fontSize: '0.82rem', color: 'var(--text, #0f172a)', lineHeight: 1.5 }}>
                Consinto o tratamento dos meus dados de saúde conforme descrito na{' '}
                <Link to="/privacy" target="_blank"
                  style={{ color: 'var(--accent-teal, #0d9488)' }}>Política de Privacidade</Link>
              </span>
            </label>

            <label style={{ display: 'flex', gap: '0.6rem', alignItems: 'flex-start', cursor: 'pointer' }}>
              <input type="checkbox" checked={consents.privacy_policy}
                onChange={() => setConsents(p => ({ ...p, privacy_policy: !p.privacy_policy }))}
                style={{ marginTop: '2px', accentColor: 'var(--accent-teal, #0d9488)', cursor: 'pointer' }} />
              <span style={{ fontSize: '0.82rem', color: 'var(--text, #0f172a)', lineHeight: 1.5 }}>
                Li e aceito a{' '}
                <Link to="/privacy" target="_blank"
                  style={{ color: 'var(--accent-teal, #0d9488)' }}>Política de Privacidade</Link>
              </span>
            </label>

            <label style={{ display: 'flex', gap: '0.6rem', alignItems: 'flex-start', cursor: 'pointer' }}>
              <input type="checkbox" checked={consents.telemedicine_consent}
                onChange={() => setConsents(p => ({ ...p, telemedicine_consent: !p.telemedicine_consent }))}
                style={{ marginTop: '2px', accentColor: 'var(--accent-teal, #0d9488)', cursor: 'pointer' }} />
              <span style={{ fontSize: '0.82rem', color: 'var(--text, #0f172a)', lineHeight: 1.5 }}>
                Consinto receber serviços de telemedicina através desta plataforma
              </span>
            </label>
          </div>

          <button type="submit" className="btn btn-primary btn-lg" disabled={loading || !allConsentsChecked}
            style={{ width: '100%', justifyContent: 'center', marginBottom: '0.75rem' }}>
            {loading ? t('register.loading') : t('register.submit')}
          </button>

          <button type="button" className="btn btn-outline btn-lg"
            style={{ width: '100%', justifyContent: 'center' }}
            onClick={() => navigate('/login')}>
            {t('register.cancel')}
          </button>
        </form>

        {error && <div className="toast error" style={{ position: 'relative', top: 0, right: 0, marginTop: '1rem' }}>{error}</div>}

        <div className="auth-toggle">
          {t('register.have_account')}{' '}
          <Link to="/login">{t('register.sign_in')}</Link>
        </div>

        <div style={{ marginTop: '0.75rem', textAlign: 'center' }}>
          <Link to="/" style={{ color: 'var(--accent-teal)', fontSize: '0.82rem', textDecoration: 'none' }}>
            {t('register.back_site')}
          </Link>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { Check, Copy, KeyRound, Loader2, ShieldCheck, ShieldOff } from 'lucide-react';
import api from '../api';
import { useAuth } from '../AuthContext';
import { useT } from '../i18n/LanguageContext';

type Stage = 'idle' | 'setup' | 'recovery';

export default function SecurityMfaPage() {
  const { t } = useT();
  const { user } = useAuth();
  const [enabled, setEnabled] = useState(false);
  const [mandatory, setMandatory] = useState(false);
  const [stage, setStage] = useState<Stage>('idle');
  const [secret, setSecret] = useState('');
  const [code, setCode] = useState('');
  const [recoveryCodes, setRecoveryCodes] = useState<string[]>([]);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [copied, setCopied] = useState(false);
  const [disableCode, setDisableCode] = useState('');

  // Read the authoritative MFA posture from the backend.
  useEffect(() => {
    api.get('/auth/mfa/status')
      .then(res => {
        setEnabled(Boolean(res.data.enabled));
        setMandatory(Boolean(res.data.mandatory));
      })
      .catch(() => {
        // Fallback: infer mandatory from role if the call fails.
        const role = user?.role || '';
        setMandatory(['doctor', 'nurse', 'pharmacist', 'admin', 'compliance_reviewer', 'corporate_admin'].includes(role));
      });
  }, [user]);

  const startSetup = async () => {
    setBusy(true); setError('');
    try {
      const res = await api.post('/auth/mfa/setup');
      setSecret(res.data.secret);
      setStage('setup');
    } catch (e: any) {
      setError(e.response?.data?.detail || 'Erro ao iniciar configuração.');
    } finally { setBusy(false); }
  };

  const confirmSetup = async () => {
    setBusy(true); setError('');
    try {
      const res = await api.post('/auth/mfa/verify', { code: code.trim() });
      setRecoveryCodes(res.data.recovery_codes || []);
      setEnabled(true);
      setStage('recovery');
      setCode('');
    } catch (e: any) {
      setError(e.response?.data?.detail || t('mfa.invalid_code'));
    } finally { setBusy(false); }
  };

  const disable = async () => {
    setBusy(true); setError('');
    try {
      await api.post('/auth/mfa/disable', { code: disableCode.trim() });
      setEnabled(false);
      setStage('idle');
      setDisableCode('');
    } catch (e: any) {
      setError(e.response?.data?.detail || t('mfa.invalid_code'));
    } finally { setBusy(false); }
  };

  const regen = async () => {
    setBusy(true); setError('');
    try {
      const res = await api.post('/auth/mfa/recovery-codes', { code: disableCode.trim() });
      setRecoveryCodes(res.data.recovery_codes || []);
      setStage('recovery');
      setDisableCode('');
    } catch (e: any) {
      setError(e.response?.data?.detail || t('mfa.invalid_code'));
    } finally { setBusy(false); }
  };

  const copyKey = () => {
    navigator.clipboard?.writeText(secret).then(() => {
      setCopied(true); setTimeout(() => setCopied(false), 1500);
    });
  };

  return (
    <div style={{ maxWidth: 560, margin: '0 auto', padding: '1.5rem 1.25rem 4rem' }}>
      <h1 style={{ margin: '0 0 0.25rem', fontSize: '1.3rem', fontWeight: 800, display: 'flex', alignItems: 'center', gap: 8 }}>
        <ShieldCheck size={22} style={{ color: 'var(--brand-primary)' }} /> {t('mfa.title')}
      </h1>
      <p style={{ margin: '0 0 1.25rem', color: 'var(--text-secondary)', fontSize: '0.88rem' }}>
        {t('mfa.subtitle')}
      </p>

      {mandatory && !enabled && (
        <div style={{ padding: '0.75rem 1rem', borderRadius: 10, marginBottom: '1rem',
          background: 'rgba(234,179,8,0.12)', border: '1px solid rgba(234,179,8,0.3)', color: '#a16207', fontSize: '0.85rem' }}>
          {t('mfa.mandatory_notice')}
        </div>
      )}

      <div className="card" style={{ padding: '1.25rem' }}>
        {/* Status row */}
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: stage === 'idle' ? 0 : '1.25rem' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, fontWeight: 700 }}>
            {enabled ? <ShieldCheck size={18} style={{ color: '#059669' }} /> : <ShieldOff size={18} style={{ color: 'var(--text-muted)' }} />}
            TOTP
            <span style={{ padding: '0.15rem 0.5rem', borderRadius: 999, fontSize: '0.72rem', fontWeight: 700,
              background: enabled ? 'rgba(16,185,129,0.15)' : 'rgba(100,116,139,0.15)',
              color: enabled ? '#047857' : '#64748b' }}>
              {enabled ? t('mfa.enabled_badge') : t('mfa.disabled_badge')}
            </span>
          </div>
          {stage === 'idle' && !enabled && (
            <button className="btn btn-primary btn-sm" onClick={startSetup} disabled={busy}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
              {busy && <Loader2 size={14} className="spin" />} {t('mfa.start_setup')}
            </button>
          )}
        </div>

        {/* Setup flow */}
        {stage === 'setup' && (
          <>
            <div style={{ fontSize: '0.9rem', fontWeight: 700, marginBottom: 6 }}>{t('mfa.step_scan')}</div>
            <p style={{ fontSize: '0.83rem', color: 'var(--text-secondary)', marginTop: 0 }}>{t('mfa.scan_help')}</p>
            <div style={{ display: 'flex', gap: 8, alignItems: 'center', marginBottom: '1.25rem' }}>
              <code style={{ flex: 1, padding: '0.6rem 0.8rem', borderRadius: 8, background: 'var(--bg-secondary)',
                border: '1px solid var(--border)', fontSize: '0.95rem', letterSpacing: '0.12em', wordBreak: 'break-all' }}>
                {secret}
              </code>
              <button className="btn btn-ghost btn-sm" onClick={copyKey} style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
                {copied ? <Check size={14} /> : <Copy size={14} />} {copied ? t('mfa.copied') : t('mfa.copy_key')}
              </button>
            </div>

            <div style={{ fontSize: '0.9rem', fontWeight: 700, marginBottom: 6 }}>{t('mfa.step_confirm')}</div>
            <p style={{ fontSize: '0.83rem', color: 'var(--text-secondary)', marginTop: 0 }}>{t('mfa.confirm_help')}</p>
            <input
              inputMode="numeric"
              value={code}
              onChange={e => setCode(e.target.value)}
              placeholder="123456"
              style={{ width: '100%', padding: '0.6rem 0.8rem', borderRadius: 8, border: '1px solid var(--border)',
                fontSize: '1.1rem', letterSpacing: '0.3em', textAlign: 'center', marginBottom: 12 }}
            />
            {error && <div style={{ color: '#dc2626', fontSize: '0.83rem', marginBottom: 10 }}>{error}</div>}
            <button className="btn btn-primary" onClick={confirmSetup} disabled={busy || code.trim().length < 6}
              style={{ display: 'inline-flex', alignItems: 'center', gap: 6 }}>
              {busy && <Loader2 size={14} className="spin" />} {t('mfa.confirm')}
            </button>
          </>
        )}

        {/* Recovery codes display */}
        {stage === 'recovery' && (
          <>
            <div style={{ fontSize: '0.9rem', fontWeight: 700, marginBottom: 6, display: 'flex', alignItems: 'center', gap: 6 }}>
              <KeyRound size={16} /> {t('mfa.recovery_title')}
            </div>
            <p style={{ fontSize: '0.83rem', color: 'var(--text-secondary)', marginTop: 0 }}>{t('mfa.recovery_help')}</p>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: 8, marginBottom: '1rem' }}>
              {recoveryCodes.map(rc => (
                <code key={rc} style={{ padding: '0.5rem 0.7rem', borderRadius: 6, background: 'var(--bg-secondary)',
                  border: '1px solid var(--border)', fontSize: '0.9rem', textAlign: 'center', letterSpacing: '0.08em' }}>
                  {rc}
                </code>
              ))}
            </div>
            <button className="btn btn-primary" onClick={() => setStage('idle')}>{t('mfa.recovery_saved')}</button>
          </>
        )}

        {/* Enabled management */}
        {stage === 'idle' && enabled && (
          <div style={{ marginTop: '1.25rem', borderTop: '1px solid var(--border)', paddingTop: '1rem' }}>
            <p style={{ fontSize: '0.83rem', color: 'var(--text-secondary)', marginTop: 0 }}>{t('mfa.disable_confirm')}</p>
            <input
              inputMode="numeric"
              value={disableCode}
              onChange={e => setDisableCode(e.target.value)}
              placeholder="123456"
              style={{ width: '100%', padding: '0.55rem 0.8rem', borderRadius: 8, border: '1px solid var(--border)',
                fontSize: '1rem', letterSpacing: '0.2em', textAlign: 'center', marginBottom: 10 }}
            />
            {error && <div style={{ color: '#dc2626', fontSize: '0.83rem', marginBottom: 10 }}>{error}</div>}
            <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
              <button className="btn btn-ghost btn-sm" onClick={regen} disabled={busy || disableCode.trim().length < 6}>
                {t('mfa.regen')}
              </button>
              <button className="btn btn-ghost btn-sm" onClick={disable} disabled={busy || disableCode.trim().length < 6}
                style={{ color: '#b91c1c' }}>
                {t('mfa.disable')}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useT } from '../i18n/LanguageContext';
import api from '../api';
import type { PatientState } from '../types';
import BookConsultationModal from '../components/BookConsultationModal';
import { useEffect } from 'react';
import {
  CheckCircle2, Droplets, Moon, Eye, Pill, Apple, Dumbbell,
  AlertTriangle, Activity, RefreshCw, User, ChevronRight,
} from 'lucide-react';

interface Medication {
  id: string;
  medication_name: string;
  dosage: string | null;
  frequency: string | null;
  is_current: boolean;
}

export default function SelfCarePage() {
  const { t } = useT();
  const navigate = useNavigate();
  const [patientState, setPatientState] = useState<PatientState | null>(null);
  const [loading, setLoading] = useState(true);
  const [showBooking, setShowBooking] = useState(false);
  const [medications, setMedications] = useState<Medication[]>([]);

  useEffect(() => {
    api.get('/api/v1/dashboard/patient-state')
      .then((res: any) => setPatientState(res.data))
      .catch(() => {})
      .finally(() => setLoading(false));

    // Load medications from backend
    api.get('/api/v1/medications/me')
      .then((res: any) => setMedications(res.data))
      .catch(() => {});
  }, []);

  const requestRenewal = (med: Medication) => {
    const params = new URLSearchParams({ med: med.medication_name });
    if (med.dosage) params.set('dose', med.dosage);
    if (med.frequency) params.set('freq', med.frequency);
    navigate(`/prescricoes/pedido?${params.toString()}`);
  };

  if (loading) return <div className="page-loading"><div className="spinner" /></div>;

  const tips = [
    { icon: <Droplets size={20} />, title: t('selfcare.tip_hydration'), desc: t('selfcare.tip_hydration_desc'), color: '#06b6d4' },
    { icon: <Moon size={20} />, title: t('selfcare.tip_rest'), desc: t('selfcare.tip_rest_desc'), color: '#8b5cf6' },
    { icon: <Eye size={20} />, title: t('selfcare.tip_monitor'), desc: t('selfcare.tip_monitor_desc'), color: '#f59e0b' },
    { icon: <Pill size={20} />, title: t('selfcare.tip_medication'), desc: t('selfcare.tip_medication_desc'), color: '#ef4444' },
    { icon: <Apple size={20} />, title: t('selfcare.tip_diet'), desc: t('selfcare.tip_diet_desc'), color: '#22c55e' },
    { icon: <Dumbbell size={20} />, title: t('selfcare.tip_exercise'), desc: t('selfcare.tip_exercise_desc'), color: '#3b82f6' },
  ];

  const seekReasons = [
    t('selfcare.seek_1'),
    t('selfcare.seek_2'),
    t('selfcare.seek_3'),
    t('selfcare.seek_4'),
  ];

  return (
    <>
      {/* Header */}
      <div className="page-header">
        <p style={{ fontSize: '0.75rem', letterSpacing: '0.15em', textTransform: 'uppercase', color: 'var(--text-muted)', marginBottom: '0.25rem' }}>
          {t('selfcare.title')}
        </p>
        <h1>{t('selfcare.title')}</h1>
        <p>{t('selfcare.subtitle')}</p>
      </div>

      {/* Good News Banner */}
      <div style={{
        background: 'linear-gradient(135deg, #22c55e, #16a34a)', color: '#fff',
        borderRadius: '14px', padding: '1.25rem 1.5rem', marginBottom: '1rem',
        display: 'flex', alignItems: 'center', gap: '1rem',
        boxShadow: '0 4px 20px rgba(34,197,94,0.3)',
      }}>
        <CheckCircle2 size={28} />
        <div style={{ flex: 1 }}>
          <div style={{ fontWeight: 700, fontSize: '1rem', marginBottom: '0.2rem' }}>
            {t('selfcare.good_news')}
          </div>
          <div style={{ fontSize: '0.88rem', opacity: 0.95 }}>
            {t('selfcare.low_risk_msg')}
          </div>
          {patientState?.last_triage_complaint && (
            <div style={{ marginTop: '0.4rem', fontSize: '0.82rem', opacity: 0.85 }}>
              {t('selfcare.complaint_label')} {patientState.last_triage_complaint}
            </div>
          )}
        </div>
      </div>

      {/* Quick Action Strip */}
      <div className="selfcare-quick-strip">
        <button className="selfcare-quick-btn" onClick={() => navigate('/triage')}>
          <Activity size={16} />
          <span>{t('selfcare.new_triage')}</span>
        </button>
        <button className="selfcare-quick-btn" onClick={() => setShowBooking(true)}>
          <ChevronRight size={16} />
          <span>{t('selfcare.book_anyway')}</span>
        </button>
        <button className="selfcare-quick-btn selfcare-quick-btn--renew"
          onClick={() => navigate('/patient/profile')}>
          <RefreshCw size={16} />
          <span>Renovar Receita</span>
        </button>
        <button className="selfcare-quick-btn" onClick={() => navigate('/patient/profile')}>
          <User size={16} />
          <span>Ver Perfil</span>
        </button>
      </div>

      {/* Current Medications Card */}
      <div className="card selfcare-meds-card" style={{ marginBottom: '1.25rem' }}>
        <div style={{
          padding: '1rem 1.25rem', borderBottom: '1px solid var(--border)',
          display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Pill size={16} style={{ color: '#ef4444' }} />
            <h3 style={{ fontSize: '0.95rem', fontWeight: 600, margin: 0 }}>{t('meds.title')}</h3>
          </div>
          <Link to="/patient/profile" style={{ fontSize: '0.78rem', color: 'var(--accent-teal)', textDecoration: 'none' }}>
            Gerir medicações →
          </Link>
        </div>
        <div style={{ padding: '1rem 1.25rem' }}>
          {medications.length === 0 ? (
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
              <span style={{ fontSize: '0.85rem', color: 'var(--text-secondary)' }}>
                {t('meds.none')}
              </span>
              <Link to="/patient/profile" style={{ fontSize: '0.82rem', color: 'var(--accent-teal)' }}>
                {t('meds.none_hint')}
              </Link>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.65rem' }}>
              {medications.map(med => (
                <div key={med.id} className="selfcare-med-row">
                  <div style={{ flex: 1 }}>
                    <span style={{ fontWeight: 700, fontSize: '0.88rem', color: 'var(--text-primary)' }}>{med.medication_name}</span>
                    {med.dosage && <span style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginLeft: '0.5rem' }}>• {med.dosage}</span>}
                    {med.frequency && <span style={{ fontSize: '0.75rem', color: 'var(--text-secondary)', marginLeft: '0.5rem' }}>• {med.frequency}</span>}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <button
                      className="btn btn-sm"
                      style={{ fontSize: '0.75rem', background: 'rgba(20,184,166,0.1)', color: 'var(--accent-teal)', border: '1px solid rgba(20,184,166,0.25)' }}
                      onClick={() => requestRenewal(med)}
                    >
                      <RefreshCw size={12} /> {t('meds.renew')}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Self-Care Tips Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
        {tips.map((tip, i) => (
          <div key={i} className="card" style={{ padding: '1.25rem' }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: '0.75rem' }}>
              <div style={{
                width: 42, height: 42, borderRadius: '10px', flexShrink: 0,
                background: `${tip.color}15`, display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: tip.color,
              }}>
                {tip.icon}
              </div>
              <div>
                <div style={{ fontWeight: 700, fontSize: '0.9rem', color: 'var(--text-primary)', marginBottom: '0.3rem' }}>
                  {tip.title}
                </div>
                <p style={{ fontSize: '0.82rem', color: 'var(--text-secondary)', margin: 0, lineHeight: 1.5 }}>
                  {tip.desc}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* When to Seek Help */}
      <div className="card" style={{ marginBottom: '1.5rem' }}>
        <div style={{
          padding: '1rem 1.25rem', borderBottom: '1px solid var(--border)',
          display: 'flex', alignItems: 'center', gap: '0.5rem',
        }}>
          <AlertTriangle size={16} style={{ color: '#f59e0b' }} />
          <h3 style={{ fontSize: '0.95rem', fontWeight: 600, margin: 0 }}>{t('selfcare.when_seek')}</h3>
        </div>
        <div style={{ padding: '1.25rem' }}>
          <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginTop: 0, marginBottom: '0.75rem' }}>
            {t('selfcare.seek_desc')}
          </p>
          <ul style={{ margin: 0, paddingLeft: '1.25rem' }}>
            {seekReasons.map((reason, i) => (
              <li key={i} style={{ fontSize: '0.85rem', color: 'var(--text-primary)', marginBottom: '0.4rem', lineHeight: 1.5 }}>
                {reason}
              </li>
            ))}
          </ul>
        </div>
      </div>

      <Link to="/dashboard" style={{ fontSize: '0.82rem', color: 'var(--text-muted)', textDecoration: 'none' }}>
        {t('selfcare.back_dashboard')}
      </Link>

      {/* Book Consultation Modal */}
      <BookConsultationModal
        open={showBooking}
        onClose={() => setShowBooking(false)}
        patientState={patientState}
        onBooked={() => { setShowBooking(false); navigate('/consultations'); }}
      />
    </>
  );
}

